window.HIDAYA_DATA.push({"id":"islamique-ei01","domaine":"islamique","unite":1,"theme":"الوحدة الأولى","tag":"EI01","langue":"ar","titre":"مدخل التزكية (القرآن الكريم) 1: الشطر الأول من سورة ق (الآية 1 إلى 15)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يرتّل المتعلم(ة) الآيات من 1 إلى 15 من سورة ق ترتيلا سليما برواية ورش عن نافع.","أن يحفظ المقطع حفظا متقنا مع سلامة الأداء.","أن يشرح المفردات الصعبة الواردة في المقطع شرحا دقيقا.","أن يستخرج المضامين الأساسية للمقطع (إثبات البعث، دلائل القدرة، مصير المكذبين).","أن يتعرّف أحكام النون الساكنة والتنوين ويطبقها على أمثلة من المقطع.","أن يستدل بآية من المقطع في موقف من حياته اليومية."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: في درس علوم الحياة والأرض، شاهد تلاميذ الأولى إعدادي صورا لحقول جافة في سهل تادلة بعد سنوات الجفاف، ثم صورا للحقل نفسه بعد موسم أمطار غزيرة وقد اخضرّ وأزهر. سأل أحدهم: هل يمكن أن يعود الإنسان إلى الحياة بعد الموت كما عادت هذه الأرض؟ هذا السؤال بعينه هو موضوع الشطر الأول من سورة ق.</p>\n<p><strong>التعريف بالسورة</strong>: سورة ق سورة <strong>مكية</strong>، عدد آياتها <strong>خمس وأربعون آية</strong>، ترتيبها الخمسون في المصحف الشريف، وهي من السور التي كان النبي صلى الله عليه وسلم يقرأ بها في خطبة العيد، فعن أم هشام بنت حارثة قالت: «ما أخذت (ق والقرآن المجيد) إلا عن لسان رسول الله صلى الله عليه وسلم يخطب بها كل جمعة» (أخرجه مسلم في صحيحه، كتاب الجمعة، حديث رقم 873). ومحورها الكبير هو <strong>البعث والنشور</strong> وإقامة الأدلة عليه.</p>\n<p><strong>نص المقطع (الآيات 1 إلى 15)</strong>:</p>\n<blockquote><p>بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ «ق ۚ وَالْقُرْآنِ الْمَجِيدِ (1) بَلْ عَجِبُوا أَنْ جَاءَهُمْ مُنْذِرٌ مِنْهُمْ فَقَالَ الْكَافِرُونَ هَٰذَا شَيْءٌ عَجِيبٌ (2) أَإِذَا مِتْنَا وَكُنَّا تُرَابًا ۖ ذَٰلِكَ رَجْعٌ بَعِيدٌ (3) قَدْ عَلِمْنَا مَا تَنْقُصُ الْأَرْضُ مِنْهُمْ ۖ وَعِنْدَنَا كِتَابٌ حَفِيظٌ (4) بَلْ كَذَّبُوا بِالْحَقِّ لَمَّا جَاءَهُمْ فَهُمْ فِي أَمْرٍ مَرِيجٍ (5) أَفَلَمْ يَنْظُرُوا إِلَى السَّمَاءِ فَوْقَهُمْ كَيْفَ بَنَيْنَاهَا وَزَيَّنَّاهَا وَمَا لَهَا مِنْ فُرُوجٍ (6) وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنْبَتْنَا فِيهَا مِنْ كُلِّ زَوْجٍ بَهِيجٍ (7) تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُنِيبٍ (8) وَنَزَّلْنَا مِنَ السَّمَاءِ مَاءً مُبَارَكًا فَأَنْبَتْنَا بِهِ جَنَّاتٍ وَحَبَّ الْحَصِيدِ (9) وَالنَّخْلَ بَاسِقَاتٍ لَهَا طَلْعٌ نَضِيدٌ (10) رِزْقًا لِلْعِبَادِ ۖ وَأَحْيَيْنَا بِهِ بَلْدَةً مَيْتًا ۚ كَذَٰلِكَ الْخُرُوجُ (11) كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَأَصْحَابُ الرَّسِّ وَثَمُودُ (12) وَعَادٌ وَفِرْعَوْنُ وَإِخْوَانُ لُوطٍ (13) وَأَصْحَابُ الْأَيْكَةِ وَقَوْمُ تُبَّعٍ ۚ كُلٌّ كَذَّبَ الرُّسُلَ فَحَقَّ وَعِيدِ (14) أَفَعَيِينَا بِالْخَلْقِ الْأَوَّلِ ۚ بَلْ هُمْ فِي لَبْسٍ مِنْ خَلْقٍ جَدِيدٍ (15)» — سورة ق، الآيات 1-15.</p></blockquote>\n<p><strong>نشاط الاكتشاف</strong>: يقرأ الأستاذ(ة) المقطع قراءة نموذجية مرتين، ثم يطلب من المتعلمين تتبع الآيات وتسجيل ثلاث كلمات لم يفهموها، وتسجيل كل كلمة تدل على مظهر من مظاهر الكون.</p>\n<p><strong>شرح المفردات</strong>:</p>\n<table><thead><tr><th>الكلمة</th><th>الشرح</th></tr></thead><tbody><tr><td>المجيد</td><td>العظيم الشريف الكثير الخير</td></tr><tr><td>منذر</td><td>مبلّغ يحذّر من عاقبة الإعراض</td></tr><tr><td>رجع بعيد</td><td>رجوع إلى الحياة يستبعدونه ويستحيلونه</td></tr><tr><td>كتاب حفيظ</td><td>اللوح المحفوظ الذي أحصى كل شيء</td></tr><tr><td>أمر مريج</td><td>أمر مضطرب مختلط لا يستقر على حال</td></tr><tr><td>فروج</td><td>شقوق وفتوق وعيوب</td></tr><tr><td>رواسي</td><td>جبال ثابتة راسخة</td></tr><tr><td>زوج بهيج</td><td>صنف من النبات حسن المنظر</td></tr><tr><td>منيب</td><td>راجع إلى الله بالطاعة والتوبة</td></tr><tr><td>حبّ الحصيد</td><td>الزرع الذي يُحصد كالقمح والشعير</td></tr><tr><td>باسقات</td><td>طوال مرتفعات</td></tr><tr><td>طلع نضيد</td><td>ثمر متراكب بعضه فوق بعض</td></tr><tr><td>أصحاب الرسّ</td><td>قوم كذبوا نبيهم، نُسبوا إلى بئر أو واد</td></tr><tr><td>تُبّع</td><td>لقب ملوك حِمْيَر باليمن</td></tr><tr><td>أفعيينا</td><td>أفعجزنا وضعفنا</td></tr><tr><td>لبس</td><td>شك والتباس</td></tr></tbody></table>\n<p><strong>المضامين الأساسية</strong>: يقسم الله تعالى بالقرآن المجيد ردّا على استغراب المشركين من بعثة رسول من جنسهم ومن إمكان البعث بعد الموت (الآيات 1-5)، ثم يسوق ثلاثة أدلة كونية على قدرته: بناء السماء وتزيينها بلا شقوق، ومدّ الأرض وإرساء الجبال وإنبات الأزواج البهيجة، وإنزال الماء المبارك الذي تحيا به الأرض الميتة (الآيات 6-11)، فمن أحيا الأرض بعد موتها قادر على إخراج الناس من قبورهم؛ ثم يذكّر بمصير الأمم المكذبة قبلهم (الآيات 12-14)، ويختم بحجة عقلية قاطعة: من قدر على الخلق الأول لا يعجزه الخلق الثاني (الآية 15).</p>\n<blockquote><p><strong>قاعدة استدلالية</strong>: الاستدلال على البعث في السورة يقوم على <strong>قياس الأولى</strong>: إعادة الشيء أهون من ابتدائه في تصور العقل البشري، والله على كل شيء قدير.</p></blockquote>\n<p><strong>القاعدة الترتيلية — أحكام النون الساكنة والتنوين</strong>: إذا جاء بعد النون الساكنة أو التنوين حرف من حروف الحلق الستة (أ، هـ، ع، ح، غ، خ) وجب <strong>الإظهار</strong>، كما في «مِنْ خَلْقٍ جَدِيدٍ». وإذا جاءت الباء وجب <strong>الإقلاب</strong> أي قلب النون ميما مخفاة. وإذا جاء حرف من (يرملون) وجب <strong>الإدغام</strong> بغنة في (ينمو) وبغيرها في اللام والراء، كما في «مِنْ كُلِّ زَوْجٍ بَهِيجٍ» ففي «زَوْجٍ بَهِيجٍ» إقلاب. وما عدا ذلك من الحروف الخمسة عشر يكون فيه <strong>الإخفاء</strong>، كما في «مُنْذِرٌ» و«عَبْدٍ مُنِيبٍ».</p>\n<p><strong>مثال محلول 1</strong>: استخرج حكم النون الساكنة في «أَنْ جَاءَهُمْ». الجواب: النون ساكنة بعدها جيم، والجيم من حروف الإخفاء، فالحكم <strong>إخفاء حقيقي</strong>.</p>\n<p><strong>مثال محلول 2</strong>: بيّن وجه الدلالة على البعث في قوله تعالى «وَأَحْيَيْنَا بِهِ بَلْدَةً مَيْتًا ۚ كَذَٰلِكَ الْخُرُوجُ». الجواب: شبّه الله خروج الناس من قبورهم بخروج النبات من الأرض الهامدة بعد نزول المطر؛ فالمشاهَد في الأرض دليل على المغيّب في الآخرة.</p>\n<p><strong>مثال محلول 3</strong>: كيف نستفيد من الآية 8 في حياتنا؟ الجواب: قوله «تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُنِيبٍ» يجعل النظر في الطبيعة عبادة؛ فالمتعلم(ة) حين يتأمل غابة الأرز بالأطلس المتوسط أو واحات درعة لا ينظر نظرة سائح فقط، بل نظرة متفكر يزداد بها إيمانا ويترجمها حرصا على هذه النعم.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<ul><li>سورة ق: مكية، 45 آية، ترتيبها 50، محورها البعث والنشور.</li><li>كان النبي صلى الله عليه وسلم يخطب بها في الجمعة والعيد (مسلم 873).</li><li>الأدلة الثلاثة على البعث في المقطع: دليل السماء، ودليل الأرض والنبات، ودليل إحياء الأرض بالماء.</li><li>الأمم المكذبة المذكورة: قوم نوح، أصحاب الرس، ثمود، عاد، فرعون، قوم لوط، أصحاب الأيكة، قوم تُبّع.</li><li><strong>الإنابة</strong>: الرجوع إلى الله بالتوبة والطاعة، وهي شرط الانتفاع بآيات الكون.</li><li>أحكام النون الساكنة والتنوين أربعة: إظهار، إدغام، إقلاب، إخفاء.</li></ul>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ قراءة «ق» بالوقف عليها ساكنة ثم وصلها بما بعدها بغير غنة؛ والصواب أن يقف القارئ على «ق» وقفا صحيحا أو يصلها بحكمها الترتيلي دون تكلف.</li><li>⚠️ الخلط بين <strong>الإخفاء</strong> و<strong>الإدغام</strong> في مثل «مُنْذِرٌ»: بعض المتعلمين يدغمون النون في الذال، والصواب أنه إخفاء لأن الذال ليست من حروف (يرملون).</li><li>⚠️ تفسير «كتاب حفيظ» بالكتاب المدرسي أو الدفتر؛ والصواب أنه اللوح المحفوظ الذي أحصى الله فيه كل شيء.</li><li>⚠️ ذكر الآيات بلا عزو، والصواب أن يُذكر اسم السورة ورقم الآية في كل استشهاد.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>أكمل: سورة ق سورة ... عدد آياتها ... ترتيبها في المصحف ... ومحورها ...</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اشرح المفردات الآتية: مريج، رواسي، باسقات، منيب.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اكتب من حفظك الآيات من 6 إلى 8 من سورة ق مع الشكل التام.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>عدّ الأمم المكذبة المذكورة في الآيتين 12 و13 و14.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>حدد حكم النون الساكنة أو التنوين فيما يأتي: «مُنْذِرٌ مِنْهُمْ»، «زَوْجٍ بَهِيجٍ»، «مِنْ خَلْقٍ»، «عَبْدٍ مُنِيبٍ».</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>استخرج من المقطع ثلاثة أدلة كونية على قدرة الله على البعث، وبيّن وجه الدلالة في كل دليل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ما معنى قوله تعالى «وَعِنْدَنَا كِتَابٌ حَفِيظٌ»؟ وما أثر الإيمان بهذا المعنى في سلوك المتعلم(ة)؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>علام يدل قول الكافرين «هَٰذَا شَيْءٌ عَجِيبٌ»؟ وبم ردّ عليهم القرآن الكريم؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>بيّن الفرق بين الإظهار والإخفاء، ومثّل لكل واحد بمثال من المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>اربط بين قوله تعالى «تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُنِيبٍ» وبين واجب المحافظة على الغطاء النباتي في المغرب.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>«أَفَعَيِينَا بِالْخَلْقِ الْأَوَّلِ». حلّل هذه الحجة العقلية في أربعة أسطر، مبيّنا كيف تردّ على من ينكر البعث.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>وضعية: قال زميل لك بعد وفاة جدّه: «لا أفهم كيف يعود الناس أحياء بعد أن صاروا ترابا». اكتب فقرة من ستة أسطر تجيبه فيها مستدلا بآيتين من المقطع مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>ارسم جدولا من ثلاثة أعمدة (الآية / المضمون / القيمة المستفادة) واملأه بخمسة أسطر من المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>قارن بين موقف «العبد المنيب» وموقف من هو «في أمر مريج» أمام آيات الكون.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"المجيد","v":"العظيم الشريف الكثير الخير"},{"r":"منذر","v":"مبلّغ يحذّر من عاقبة الإعراض"},{"r":"رجع بعيد","v":"رجوع إلى الحياة يستبعدونه ويستحيلونه"},{"r":"كتاب حفيظ","v":"اللوح المحفوظ الذي أحصى كل شيء"},{"r":"أمر مريج","v":"أمر مضطرب مختلط لا يستقر على حال"},{"r":"فروج","v":"شقوق وفتوق وعيوب"},{"r":"رواسي","v":"جبال ثابتة راسخة"},{"r":"زوج بهيج","v":"صنف من النبات حسن المنظر"},{"r":"منيب","v":"راجع إلى الله بالطاعة والتوبة"},{"r":"حبّ الحصيد","v":"الزرع الذي يُحصد كالقمح والشعير"},{"r":"باسقات","v":"طوال مرتفعات"},{"r":"طلع نضيد","v":"ثمر متراكب بعضه فوق بعض"},{"r":"أصحاب الرسّ","v":"قوم كذبوا نبيهم، نُسبوا إلى بئر أو واد"},{"r":"تُبّع","v":"لقب ملوك حِمْيَر باليمن"},{"r":"أفعيينا","v":"أفعجزنا وضعفنا"},{"r":"لبس","v":"شك والتباس"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (8 نقط)</strong></p>\n<ol><li>اكتب الآيات من 9 إلى 11 من سورة ق مع الشكل. (4 ن)</li><li>اشرح: حبّ الحصيد، طلع نضيد، لبس. (3 ن)</li><li>اذكر رقم الآية التي فيها إقلاب. (1 ن)</li></ol>\n<p><strong>التمرين الثاني (6 نقط)</strong> — بيّن ثلاثة أدلة على البعث وردت في المقطع، مع الاستشهاد لكل دليل بجزء من آية والعزو إليه.</p>\n<p><strong>التمرين الثالث (6 نقط)</strong> — وضعية: طلب منك نادي البيئة بالمؤسسة كلمة قصيرة في اليوم الوطني للشجرة. اكتب خمسة أسطر تربط فيها بين النظر في النبات والإيمان بالبعث، مستشهدا بآية واحدة مع العزو.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: كتابة الآيات بلا خطأ 4 ن (يُخصم 0,5 عن كل خطأ)؛ الشرح: حبّ الحصيد = الزرع الذي يُحصد، طلع نضيد = ثمر متراكب، لبس = شك والتباس (1 ن لكل شرح)؛ الآية التي فيها إقلاب: الآية 7 في «زَوْجٍ بَهِيجٍ» (1 ن).</li><li>التمرين الثاني: دليل السماء (الآية 6) + دليل الأرض والنبات (الآية 7) + دليل الماء وإحياء الأرض (الآيتان 9 و11)؛ لكل دليل 1,5 ن مع الاستشهاد، و1,5 ن للعزو الصحيح مجتمعا.</li><li>التمرين الثالث: سلامة اللغة 1 ن، الربط بين النظر والإيمان 2 ن، الاستشهاد الصحيح مع العزو 2 ن، اقتراح سلوك بيئي عملي 1 ن. نموذج: الشجرة آية من آيات الله، قال تعالى «وَأَنْبَتْنَا فِيهَا مِنْ كُلِّ زَوْجٍ بَهِيجٍ» (سورة ق، الآية 7)، فمن غرس شجرة فقد حفظ آية تُذكّر بقدرة الله على إحياء الموتى، وحفظ في الوقت نفسه ماء الأرض وهواءها.</li></ul>\n<hr>"}},
{"id":"islamique-ei02","domaine":"islamique","unite":2,"theme":"الوحدة الأولى","tag":"EI02","langue":"ar","titre":"مدخل التزكية (العقيدة) 1: العقيدة الصحيحة والعقائد الفاسدة","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) العقيدة لغة واصطلاحا.","أن يميّز بين العقيدة الصحيحة والعقائد الفاسدة بمعايير واضحة.","أن يستدل على وجوب توحيد الله بآيات وأحاديث مع العزو.","أن يذكر مظاهر العقائد الفاسدة في محيطه ويبيّن خطرها.","أن يعتزّ بثوابت الهوية الدينية المغربية: العقيدة الأشعرية والمذهب المالكي."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: قبل امتحان مهم، أحضر تلميذ خيطا أحمر ربطه في معصمه وقال: «هذا يجلب لي التوفيق». وقالت زميلته: «بل التوفيق من الله، والاستعداد بالمراجعة». من منهما على العقيدة الصحيحة؟ ولماذا؟</p>\n<p><strong>تعريف العقيدة</strong>: العقيدة <strong>لغة</strong> من العَقْد وهو الربط والإحكام والشدّ، ومنه عقد الحبل وعقد البيع. و<strong>اصطلاحا</strong>: ما يعقد عليه الإنسان قلبه ويجزم به جزما لا يخالطه شك، من الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره.</p>\n<blockquote><p><strong>العقيدة الصحيحة</strong>: هي الاعتقاد الجازم الموافق لما جاء في القرآن الكريم والسنة النبوية الصحيحة، وأصلها <strong>توحيد الله</strong> في ذاته وصفاته وأفعاله وعبادته، وتنزيهه عن كل ما لا يليق به.</p></blockquote>\n<blockquote><p><strong>العقيدة الفاسدة</strong>: كل اعتقاد يخالف ما دلّ عليه الوحي، كالإشراك بالله في العبادة، أو نسبة النفع والضر إلى غيره استقلالا، أو إنكار البعث والجزاء، أو التعلق بالخرافة والسحر والتنجيم.</p></blockquote>\n<p><strong>نشاط الاكتشاف</strong>: يوزّع الأستاذ(ة) بطاقات فيها عبارات (منها: «الشفاء بيد الله»، «هذا الحرز يحميني من الحسد»، «أدعو الله وأتوكل عليه وآخذ بالأسباب»، «الأبراج تحدد شخصيتي»)، ويطلب تصنيفها في عمودين: عقيدة صحيحة / عقيدة فاسدة، مع التعليل.</p>\n<p><strong>أدلة العقيدة الصحيحة</strong>: قال الله تعالى: «قُلْ هُوَ اللَّهُ أَحَدٌ. اللَّهُ الصَّمَدُ. لَمْ يَلِدْ وَلَمْ يُولَدْ. وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ» (سورة الإخلاص، الآيات 1-4)، وقال سبحانه: «لَيْسَ كَمِثْلِهِ شَيْءٌ ۖ وَهُوَ السَّمِيعُ الْبَصِيرُ» (سورة الشورى، الآية 11). وعن معاذ بن جبل رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «حق الله على العباد أن يعبدوه ولا يشركوا به شيئا» (أخرجه البخاري في صحيحه، كتاب الجهاد، حديث رقم 2856، ومسلم، كتاب الإيمان، حديث رقم 30).</p>\n<p><strong>مظاهر العقائد الفاسدة</strong>: الشرك الأكبر كدعاء غير الله وطلب الحاجات من الأموات؛ والتعلق بالتمائم والأحجبة اعتقادا أنها تنفع بذاتها؛ وتصديق الكهان والعرافين والمنجمين، وقد قال النبي صلى الله عليه وسلم: «من أتى عرّافا فسأله عن شيء لم تُقبل له صلاة أربعين ليلة» (أخرجه مسلم في صحيحه، كتاب السلام، حديث رقم 2230)؛ وإنكار البعث أو الاستهزاء بالدين؛ والتشاؤم بالأيام والأشخاص.</p>\n<p><strong>معايير التمييز</strong>: يُعرض الاعتقاد على ثلاثة معايير: (1) <strong>الدليل</strong>: هل يستند إلى نص صحيح أم إلى عادة موروثة؟ (2) <strong>التوحيد</strong>: هل يجعل النفع والضر بيد الله وحده أم يشرك معه غيره؟ (3) <strong>الأثر</strong>: هل يورث الطمأنينة والعمل بالأسباب أم الخوف والكسل والاتكال على الوهم؟</p>\n<p><strong>الأنموذج المغربي</strong>: يقوم النموذج الديني المغربي على ثوابت جامعة نصّ عليها الدستور والمنهاج الدراسي: <strong>العقيدة الأشعرية</strong> التي تجمع بين النقل والعقل وتنزّه الله عن مشابهة المخلوقات، و<strong>المذهب المالكي</strong> في الفروع، والتصوف السني السلوكي، و<strong>إمارة المؤمنين</strong> التي تحمي الملة والدين وتحفظ وحدة الأمة الدينية، وهو ما يقي المجتمع من التطرف والغلو ومن الخرافة معا (منهاج المادة 2016 — ampei.ma).</p>\n<p><strong>مثال محلول 1</strong>: شخص مريض ذهب إلى الطبيب ودعا الله بالشفاء. حكمه؟ الجواب: هذا عين العقيدة الصحيحة، لأنه أخذ بالسبب وعلّق الشفاء بالله؛ والأخذ بالأسباب لا ينافي التوكل بل هو من تمامه.</p>\n<p><strong>مثال محلول 2</strong>: امرأة علّقت خرزة زرقاء على ابنها لتدفع عنه العين. الجواب: هذا من العقائد الفاسدة لأنه تعليق النفع والدفع بشيء لم يجعله الله سببا شرعيا ولا حسّيا؛ والبديل الصحيح الرقية بالقرآن والأذكار النبوية والدعاء.</p>\n<p><strong>مثال محلول 3</strong>: قارئ في مجلة يقول إن مولود برج معيّن ناجح هذه السنة. الجواب: تصديق ذلك من العقائد الفاسدة لأنه ادعاء لعلم الغيب، والغيب لله وحده، قال تعالى: «قُلْ لَا يَعْلَمُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ» (سورة النمل، الآية 65).</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>العقيدة</td><td>ما يعقد عليه القلب جزما بلا شك</td></tr><tr><td>التوحيد</td><td>إفراد الله بالربوبية والألوهية والأسماء والصفات</td></tr><tr><td>الشرك</td><td>جعل شريك لله في ربوبيته أو ألوهيته</td></tr><tr><td>الخرافة</td><td>اعتقاد لا يستند إلى دليل شرعي ولا عقلي</td></tr><tr><td>التميمة</td><td>ما يُعلّق اعتقاد دفعه للضر بذاته</td></tr><tr><td>العرّاف/الكاهن</td><td>من يدّعي معرفة الغيب</td></tr><tr><td>العقيدة الأشعرية</td><td>المذهب الاعتقادي المعتمد بالمغرب، يجمع بين النقل والعقل وينزّه الله</td></tr><tr><td>الأسباب</td><td>ما جعله الله موصلا إلى النتائج، والأخذ بها من التوحيد</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الظن أن التوكل يعني ترك الأسباب؛ والصواب أن التوكل قلبيّ والأخذ بالأسباب عمليّ، وهما لا يتعارضان.</li><li>⚠️ الخلط بين <strong>الرقية الشرعية</strong> (بالقرآن والأدعية الثابتة) وبين <strong>السحر والتمائم</strong>؛ الأولى مشروعة والثانية ممنوعة.</li><li>⚠️ الاعتقاد أن زيارة الأضرحة في ذاتها شرك؛ التفصيل: زيارة القبور للاعتبار والدعاء للميت مشروعة، أما دعاء صاحب القبر وطلب الحاجات منه فهو الممنوع.</li><li>⚠️ الحكم على الأشخاص بالكفر عند وقوعهم في خطأ اعتقادي؛ والصواب أن التعليم والنصح والرفق هو المسلك التربوي، وأن الحكم على الأعيان من اختصاص أهل العلم.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف العقيدة لغة واصطلاحا.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر أركان الإيمان الستة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>صنّف في جدول: دعاء الله عند الشدة / تعليق حرز / الأخذ بالدواء / تصديق المنجم / التوكل على الله مع المراجعة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>أتمم: قال تعالى «لَيْسَ كَمِثْلِهِ شَيْءٌ ... » واذكر السورة ورقم الآية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>ما المذهب الاعتقادي والمذهب الفقهي المعتمدان بالمغرب؟</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>بيّن أثر العقيدة الصحيحة في ثلاثة مجالات: الدراسة، والعلاقة بالوالدين، والتعامل مع المرض.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>اذكر ثلاثة مظاهر للعقائد الفاسدة في المجتمع، واقترح لكل مظهر بديلا شرعيا.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>استدل بحديث نبوي على تحريم إتيان العرافين مع العزو الكامل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>لماذا كان التوحيد أصل العقيدة الصحيحة وأساسها؟ علّل بثلاثة أوجه.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>فسّر: كيف تحمي الثوابت الدينية المغربية المجتمع من الغلو ومن الخرافة في آن واحد؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميلك يرفض المراجعة قائلا: «إن كتب الله لي النجاح نجحت». ناقشه في ستة أسطر بأسلوب مهذب ودليل شرعي.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل العبارة: «الخرافة تُضعف الإرادة، والعقيدة الصحيحة تبني الإنسان الفاعل».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز بطاقة توعوية (عنوان + ثلاث رسائل + آية أو حديث) موجّهة إلى تلاميذ المؤسسة حول خطر التمائم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>قارن في جدول بين موقف المؤمن الموحّد وموقف المتعلق بالخرافة من حيث: مصدر النفع والضر، والأخذ بالأسباب، والحالة النفسية، والنتيجة العملية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"العقيدة","v":"ما يعقد عليه القلب جزما بلا شك"},{"r":"التوحيد","v":"إفراد الله بالربوبية والألوهية والأسماء والصفات"},{"r":"الشرك","v":"جعل شريك لله في ربوبيته أو ألوهيته"},{"r":"الخرافة","v":"اعتقاد لا يستند إلى دليل شرعي ولا عقلي"},{"r":"التميمة","v":"ما يُعلّق اعتقاد دفعه للضر بذاته"},{"r":"العرّاف/الكاهن","v":"من يدّعي معرفة الغيب"},{"r":"العقيدة الأشعرية","v":"المذهب الاعتقادي المعتمد بالمغرب، يجمع بين النقل والعقل وينزّه الله"},{"r":"الأسباب","v":"ما جعله الله موصلا إلى النتائج، والأخذ بها من التوحيد"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — عرّف: العقيدة، الشرك، الخرافة. ثم اذكر أركان الإيمان الستة.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — استدل بآية وحديث مع العزو الكامل على وجوب إفراد الله بالعبادة، واشرح وجه الدلالة في كل نص.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: صديقك يخاف من الرسوب لأن «رقم قاعته يجلب النحس». حرّر ردا من سبعة أسطر يجمع بين التصحيح العقدي والنصيحة العملية.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: كل تعريف 1,5 ن (العقيدة: جزم القلب؛ الشرك: جعل شريك لله؛ الخرافة: اعتقاد بلا دليل)، وأركان الإيمان 2,5 ن (0,5 عن كل أربعة أركان مع اكتمال العدد).</li><li>التمرين الثاني: الآية 2 ن مع العزو، الحديث 2 ن مع العزو (مثال: «حق الله على العباد أن يعبدوه ولا يشركوا به شيئا»، البخاري 2856 ومسلم 30)، وجه الدلالة 2 ن.</li><li>التمرين الثالث: تصحيح الاعتقاد بأن النفع والضر بيد الله 3 ن، الاستشهاد 2 ن، النصيحة العملية (المراجعة، النوم الكافي، الدعاء) 2 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei03","domaine":"islamique","unite":3,"theme":"الوحدة الأولى","tag":"EI03","langue":"ar","titre":"مدخل الاقتداء 1: بعثة الرسول صلى الله عليه وسلم ودعوته السرية والجهرية","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يحدد المتعلم(ة) ظروف البعثة النبوية وتاريخها.","أن يسرد أحداث نزول الوحي الأول سردا مرتبا.","أن يميّز بين مرحلتي الدعوة السرية والدعوة الجهرية من حيث الأسلوب والمدة والنتائج.","أن يستخلص الدروس التربوية من تدرّج الدعوة.","أن يقتدي بالنبي صلى الله عليه وسلم في التدرج والحكمة في الدعوة إلى الخير."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: أراد نادي المواطنة بالإعدادية إطلاق حملة لترشيد استهلاك الماء. اقترح فريق أن يبدأوا بإقناع مجموعة صغيرة من التلاميذ المتحمسين ثم يوسعوا الحملة، واقترح آخرون إعلانها مباشرة أمام كل التلاميذ. أي الأسلوبين أنجع؟ الجواب يظهر في تدرّج الدعوة النبوية.</p>\n<p><strong>قبل البعثة</strong>: كان مجتمع مكة يجمع بين خصال محمودة (الكرم، الوفاء، حماية الجوار) وانحرافات خطيرة (عبادة الأصنام، وأد البنات، الربا، الظلم، شرب الخمر). وكان النبي صلى الله عليه وسلم قبل البعثة معروفا بـ<strong>الصادق الأمين</strong>، متجنبا للأصنام، متعبّدا في <strong>غار حراء</strong> الليالي ذوات العدد.</p>\n<p><strong>نزول الوحي</strong>: بلغ النبي صلى الله عليه وسلم أربعين سنة، وفي شهر رمضان جاءه جبريل عليه السلام في غار حراء فقال: اقرأ. قال: «ما أنا بقارئ». فغطّه ثلاث مرات ثم قال: «اقرأ باسم ربك الذي خلق» (القصة في صحيح البخاري، كتاب بدء الوحي، حديث رقم 3). فرجع صلى الله عليه وسلم يرجف فؤاده إلى خديجة رضي الله عنها فقال: «زمّلوني زمّلوني»، فثبّتته بقولها: «كلا والله لا يخزيك الله أبدا، إنك لتصل الرحم وتحمل الكلّ وتكسب المعدوم وتقري الضيف وتعين على نوائب الحق» (البخاري، حديث رقم 3). ثم ذهبت به إلى ابن عمها <strong>ورقة بن نوفل</strong> فأخبره أنه الناموس الذي نزل على موسى.</p>\n<blockquote><p><strong>البعثة</strong>: تكليف الله لمحمد صلى الله عليه وسلم بالرسالة، وكانت في سن الأربعين، ومدة الوحي ثلاث وعشرون سنة: ثلاث عشرة بمكة وعشر بالمدينة.</p></blockquote>\n<p><strong>المرحلة الأولى: الدعوة السرية</strong> (نحو ثلاث سنوات): دعا النبي صلى الله عليه وسلم أقرب الناس إليه: خديجة بنت خويلد أول من آمن، وأبو بكر الصديق من الرجال، وعلي بن أبي طالب من الصبيان، وزيد بن حارثة من الموالي، ثم عثمان بن عفان والزبير بن العوام وعبد الرحمن بن عوف وسعد بن أبي وقاص وطلحة بن عبيد الله على يد أبي بكر. وكان مقر اللقاء <strong>دار الأرقم بن أبي الأرقم</strong> عند الصفا. وأسلوب هذه المرحلة: انتقاء المدعوين، وتربيتهم على القرآن، وستر الاجتماعات حماية للنواة الأولى.</p>\n<p><strong>المرحلة الثانية: الدعوة الجهرية</strong>: بعد نزول قوله تعالى «وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ» (سورة الشعراء، الآية 214)، وقوله «فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ» (سورة الحجر، الآية 94)، صعد النبي صلى الله عليه وسلم الصفا ونادى بطون قريش وقال لهم: «أرأيتم لو أخبرتكم أن خيلا بالوادي تريد أن تغير عليكم، أكنتم مصدقيّ؟» قالوا: نعم، ما جرّبنا عليك كذبا، قال: «فإني نذير لكم بين يدي عذاب شديد» (أخرجه البخاري، كتاب التفسير، حديث رقم 4770، ومسلم، كتاب الإيمان، حديث رقم 208). فقابله أبو لهب بالإعراض، وبدأت مرحلة الأذى والمواجهة.</p>\n<p><strong>نتائج المرحلتين</strong>: تكوين نواة صلبة من المؤمنين، وانتشار الخبر في مكة وخارجها، واشتداد الأذى على الضعفاء كبلال بن رباح وآل ياسر، مما مهّد للهجرة إلى الحبشة ثم إلى المدينة.</p>\n<p><strong>الدروس المستفادة</strong>: (1) <strong>التدرج</strong> في الإصلاح سنّة نبوية. (2) <strong>الحكمة</strong> في اختيار الأسلوب والزمان والمخاطَب. (3) <strong>القدوة</strong> قبل الكلمة: صدقُ النبي المعروف سابقا كان أول حججه. (4) <strong>التربية قبل التوسع</strong>: بناء الأفراد أهم من كثرة العدد.</p>\n<p><strong>مثال محلول 1</strong>: لماذا بدأ النبي صلى الله عليه وسلم بالأقربين؟ الجواب: لأنهم أعرف الناس بصدقه، ولأن حق القرابة يوجب النصح، ولأن نجاح الدعوة في الدائرة القريبة يمنحها مصداقية في الدائرة الأوسع.</p>\n<p><strong>مثال محلول 2</strong>: ما دلالة قوله «ما جرّبنا عليك كذبا»؟ الجواب: دلالة على أن الأخلاق سابقة على الخطاب، وأن المصداقية رصيد يُبنى قبل الحاجة إليه؛ وهذا درس مباشر للمتعلم(ة) في صدقه مع أساتذته وأسرته.</p>\n<p><strong>مثال محلول 3</strong>: كيف نطبق التدرج في حملة مدرسية؟ الجواب: نبدأ بفريق صغير مقتنع ومدرَّب، ثم ننتقل إلى الأقسام، ثم إلى المؤسسة كلها، مع إعداد وسائل الإقناع في كل مرحلة.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>الشرح</th></tr></thead><tbody><tr><td>البعثة</td><td>تكليف الله للنبي بالرسالة عند بلوغه الأربعين</td></tr><tr><td>الوحي</td><td>ما يُلقيه الله إلى أنبيائه من كلامه بواسطة الملك</td></tr><tr><td>غار حراء</td><td>غار في جبل النور بمكة كان يتعبد فيه النبي قبل البعثة</td></tr><tr><td>الدعوة السرية</td><td>مرحلة نحو ثلاث سنوات كان الدعاء فيها للأقربين في دار الأرقم</td></tr><tr><td>الدعوة الجهرية</td><td>مرحلة الإعلان بالدعوة بعد أمر الله بالصدع</td></tr><tr><td>الصدع بالأمر</td><td>الجهر به وإعلانه بلا مواربة</td></tr><tr><td>السابقون الأولون</td><td>أوائل من آمن بالنبي صلى الله عليه وسلم</td></tr><tr><td>ورقة بن نوفل</td><td>ابن عم خديجة، عالم نصراني بشّر بالنبوة</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الظن أن الدعوة السرية كانت خوفا وجُبنا؛ والصواب أنها <strong>تدبير حكيم</strong> لحماية النواة الأولى وتربيتها.</li><li>⚠️ الخلط بين أول من آمن مطلقا (خديجة رضي الله عنها) وأول من آمن من الرجال (أبو بكر) ومن الصبيان (علي) ومن الموالي (زيد).</li><li>⚠️ اعتبار مرحلة الجهر بداية الدعوة؛ والصواب أنها امتداد لمرحلة سرية سبقتها ودامت نحو ثلاث سنوات.</li><li>⚠️ رواية أحداث السيرة بلا مصدر؛ والصواب العزو إلى كتب الحديث والسيرة المعتمدة.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>في أي سن بُعث النبي صلى الله عليه وسلم؟ وكم دامت مدة الوحي؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر أول من آمن من: النساء، الرجال، الصبيان، الموالي.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>ما اسم الغار الذي نزل فيه الوحي؟ وفي أي جبل يوجد؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>أتمم الآية: «وَأَنْذِرْ ...» واذكر السورة ورقم الآية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>كم دامت الدعوة السرية تقريبا؟ وأين كان مركزها؟</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>قارن في جدول بين الدعوة السرية والجهرية من حيث: المدة، المخاطَب، الأسلوب، النتائج.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ما دلالة قول قريش للنبي صلى الله عليه وسلم: «ما جرّبنا عليك كذبا»؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>بم ثبّتت خديجة رضي الله عنها النبي صلى الله عليه وسلم؟ وما القيم التي أبرزتها في كلامها؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>لماذا اختار النبي صلى الله عليه وسلم دار الأرقم مكانا للقاء المسلمين؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>استخرج ثلاثة دروس تربوية من تدرّج الدعوة، وطبّق كل درس على وضعية مدرسية.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: كُلّفت مع زملائك بإطلاق مبادرة لمحاربة العنف اللفظي في المؤسسة. اقترح خطة من ثلاث مراحل مستلهمة من تدرّج الدعوة النبوية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف كانت أخلاق النبي صلى الله عليه وسلم قبل البعثة حجة له بعد البعثة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>رتّب زمنيا: نزول الوحي / التعبد في حراء / الصعود على الصفا / الاجتماع في دار الأرقم / نزول «فَاصْدَعْ بِمَا تُؤْمَرُ».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب فقرة من ستة أسطر عن أثر الاقتداء بالنبي صلى الله عليه وسلم في سلوك المتعلم(ة) المغربي اليوم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"البعثة","v":"تكليف الله للنبي بالرسالة عند بلوغه الأربعين"},{"r":"الوحي","v":"ما يُلقيه الله إلى أنبيائه من كلامه بواسطة الملك"},{"r":"غار حراء","v":"غار في جبل النور بمكة كان يتعبد فيه النبي قبل البعثة"},{"r":"الدعوة السرية","v":"مرحلة نحو ثلاث سنوات كان الدعاء فيها للأقربين في دار الأرقم"},{"r":"الدعوة الجهرية","v":"مرحلة الإعلان بالدعوة بعد أمر الله بالصدع"},{"r":"الصدع بالأمر","v":"الجهر به وإعلانه بلا مواربة"},{"r":"السابقون الأولون","v":"أوائل من آمن بالنبي صلى الله عليه وسلم"},{"r":"ورقة بن نوفل","v":"ابن عم خديجة، عالم نصراني بشّر بالنبوة"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — أجب بدقة: سن البعثة، مدة الوحي، مكان نزوله، أول من آمن من الرجال، مركز الدعوة السرية، الآية التي أمرت بالجهر، والصحابي الذي أسلم من الموالي.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — قارن بين الدعوة السرية والدعوة الجهرية في جدول من أربعة معايير.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: لاحظت انتشار السخرية من زميل بسبب لهجته. اكتب ثمانية أسطر تبيّن فيها كيف تعالج الموقف بالتدرج والحكمة مقتديا بالسيرة النبوية، مع الاستشهاد بآية أو حديث والعزو.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: 1 ن لكل جواب صحيح (أربعون سنة؛ 23 سنة؛ غار حراء؛ أبو بكر؛ دار الأرقم؛ «فَاصْدَعْ بِمَا تُؤْمَرُ» سورة الحجر 94؛ زيد بن حارثة).</li><li>التمرين الثاني: 1,5 ن لكل معيار مكتمل الطرفين.</li><li>التمرين الثالث: تشخيص الظاهرة 1,5 ن، خطة متدرجة (نصح فردي، ثم إشراك الأستاذ، ثم مبادرة قسمية) 3 ن، الاستشهاد مع العزو 1,5 ن، سلامة اللغة 1 ن. مثال للاستشهاد: «يَا أَيُّهَا الَّذِينَ آمَنُوا لَا يَسْخَرْ قَوْمٌ مِنْ قَوْمٍ عَسَىٰ أَنْ يَكُونُوا خَيْرًا مِنْهُمْ» (سورة الحجرات، الآية 11).</li></ul>\n<hr>"}},
{"id":"islamique-ei04","domaine":"islamique","unite":4,"theme":"الوحدة الأولى","tag":"EI04","langue":"ar","titre":"مدخل الاستجابة 1: العبادة غاية الخلق — أركان الإسلام (المفهوم والغايات)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) العبادة تعريفا شاملا.","أن يستدل على أن العبادة غاية خلق الإنسان.","أن يذكر أركان الإسلام الخمسة مرتبة مع أدلتها.","أن يبيّن غاية كل ركن ومقصده التربوي والاجتماعي.","أن يوسّع مفهوم العبادة ليشمل العمل والدراسة والإحسان."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: سُئل تلميذ: «ماذا فعلت اليوم من العبادة؟» فأجاب: «صليت الظهر فقط». فقال أستاذه: «وماذا عن مراجعتك لدروسك، وإعانتك أمّك، وصدقك مع صاحبك؟». هذا الحوار يفتح باب الدرس: ما حدّ العبادة؟</p>\n<p><strong>مفهوم العبادة</strong>: العبادة <strong>لغة</strong> الخضوع والتذلل. و<strong>اصطلاحا</strong>:</p>\n<blockquote><p><strong>العبادة</strong>: اسم جامع لكل ما يحبه الله ويرضاه من الأقوال والأعمال، الظاهرة والباطنة، إذا صحّت النية وطابق العملُ الشرع.</p></blockquote>\n<p>فالعبادة إذن ليست الصلاة والصيام فقط، بل تشمل <strong>العبادات المحضة</strong> (الصلاة، الزكاة، الصوم، الحج، الذكر) و<strong>العبادات المتعدية</strong> (طلب العلم، الإحسان إلى الوالدين، إتقان العمل، إماطة الأذى عن الطريق، الرفق بالحيوان)، بشرطين: <strong>الإخلاص</strong> لله، و<strong>الموافقة</strong> لهدي النبي صلى الله عليه وسلم.</p>\n<p><strong>العبادة غاية الخلق</strong>: قال الله تعالى: «وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ» (سورة الذاريات، الآية 56)، وقال: «وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ» (سورة البينة، الآية 5). ومعنى ذلك أن الوجود الإنساني له غاية، وأن العبادة تحرير للإنسان من عبودية المال والشهوة والخلق، وتوجيه لطاقته إلى ما ينفعه في الدنيا والآخرة.</p>\n<p><strong>أركان الإسلام</strong>: عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «بُني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمدا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وحج البيت، وصوم رمضان» (أخرجه البخاري في صحيحه، كتاب الإيمان، حديث رقم 8، ومسلم، كتاب الإيمان، حديث رقم 16).</p>\n<table><thead><tr><th>الركن</th><th>المفهوم الموجز</th><th>الغاية / المقصد</th></tr></thead><tbody><tr><td>الشهادتان</td><td>الإقرار بوحدانية الله ورسالة محمد صلى الله عليه وسلم قولا واعتقادا وعملا</td><td>تحقيق التوحيد وتحرير القلب من الخوف والتعلق بغير الله</td></tr><tr><td>الصلاة</td><td>عبادة قولية فعلية بشروط وأركان، خمس مرات في اليوم</td><td>صلة دائمة بالله، وتنظيم الوقت، ونهي عن الفحشاء</td></tr><tr><td>الزكاة</td><td>قدر واجب من المال يُدفع لمستحقيه بشروط معلومة</td><td>تطهير المال والنفس، وتحقيق التكافل ومحاصرة الفقر</td></tr><tr><td>الصوم</td><td>إمساك عن المفطرات من الفجر إلى الغروب في رمضان بنيّة</td><td>تربية الإرادة وتقوى الله والإحساس بالمحرومين</td></tr><tr><td>الحج</td><td>قصد بيت الله الحرام لأداء المناسك مرة في العمر لمن استطاع</td><td>تجديد الإيمان، وترسيخ وحدة الأمة والمساواة</td></tr></tbody></table>\n<p><strong>نشاط الاكتشاف</strong>: يُوزّع جدول ناقص فيه أسماء الأركان، ويُطلب من المجموعات ملء عمودي «المفهوم» و«الغاية» ثم عرضها ومناقشتها.</p>\n<p><strong>ترتيب الأركان ودلالته</strong>: بدأ الحديث بالشهادتين لأنهما أساس صحة باقي الأعمال، ثم الصلاة لأنها العبادة اليومية المتكررة، ثم الزكاة لأنها بعد اجتماعي، ثم الحج والصوم. وقد ورد الحج قبل الصوم في هذه الرواية، وفي رواية أخرى العكس، وذلك لا يؤثر في الحكم؛ فالترتيب في الذكر ليس ترتيبا في الفرض الزمني.</p>\n<p><strong>السياق المغربي</strong>: يظهر ركن الزكاة في المغرب في صور التكافل المنظم: صناديق التضامن، والمساهمة في المبادرات الاجتماعية، وتوزيع «الزكاة والصدقات» في المساجد خصوصا في رمضان. ويظهر الحج في تنظيم وزارة الأوقاف والشؤون الإسلامية للقرعة والبعثة الرسمية للحجاج. وتظهر الصلاة في حياة الحيّ حول المسجد، حيث يُنظّم الوقت على الأذان.</p>\n<p><strong>مثال محلول 1</strong>: هل مراجعة الدروس عبادة؟ الجواب: نعم إذا نوى المتعلم بها طلب العلم النافع ونفع أمته، فطلب العلم من أفضل القربات، قال صلى الله عليه وسلم: «من سلك طريقا يطلب فيه علما سلك الله به طريقا إلى الجنة» (أخرجه مسلم، كتاب الذكر والدعاء، حديث رقم 2699).</p>\n<p><strong>مثال محلول 2</strong>: من صلى ليراه الناس فقط؟ الجواب: عمله غير مقبول لتخلّف شرط الإخلاص، فالميزان قوله صلى الله عليه وسلم: «إنما الأعمال بالنيات» (أخرجه البخاري، كتاب بدء الوحي، حديث رقم 1).</p>\n<p><strong>مثال محلول 3</strong>: تلميذ يتصدق بجزء من مصروفه اليومي على زميل محتاج. الجواب: هذا عمل صالح يدخل في معنى الزكاة الأوسع (الصدقة التطوعية)، ويربي التكافل، ولا يُغني عن الزكاة الواجبة على من ملك نصابا.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>العبادة</td><td>كل ما يحبه الله ويرضاه من قول أو عمل بإخلاص وموافقة للشرع</td></tr><tr><td>الإخلاص</td><td>تصفية العمل من كل قصد غير وجه الله</td></tr><tr><td>المتابعة</td><td>موافقة العمل لهدي النبي صلى الله عليه وسلم</td></tr><tr><td>الركن</td><td>ما لا يقوم البناء إلا به، وتركُه يُخلّ بالإسلام</td></tr><tr><td>النصاب</td><td>القدر الذي إذا بلغه المال وجبت فيه الزكاة</td></tr><tr><td>المناسك</td><td>أعمال الحج المشروعة كالطواف والسعي والوقوف بعرفة</td></tr><tr><td>العبادات المتعدية</td><td>ما ينتفع به الغير كالإحسان وطلب العلم وإتقان العمل</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ حصر العبادة في الصلاة والصيام؛ والصواب أن كل عمل نافع بنية صالحة عبادة.</li><li>⚠️ الاعتقاد أن الزكاة تطوع؛ والصواب أنها <strong>فرض</strong> على من ملك النصاب وحال عليه الحول، بشروطها.</li><li>⚠️ الظن أن حسن النية يكفي مع مخالفة الشرع؛ والصواب أن العمل يُشترط فيه الإخلاص والموافقة معا.</li><li>⚠️ الخلط بين الحج والعمرة؛ الحج ركن في وقت معلوم، والعمرة نافلة مؤكدة عند المالكية تُؤدى في أي وقت.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف العبادة لغة واصطلاحا.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر أركان الإسلام الخمسة كما وردت في حديث ابن عمر مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>أتمم: «وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ ...» وحدد السورة والآية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>ما شرطا قبول العبادة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>صنّف إلى عبادة محضة ومتعدية: الصوم، إماطة الأذى عن الطريق، الذكر، مساعدة الجار، الطواف، إتقان الواجب المدرسي.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>بيّن غاية كل ركن من أركان الإسلام في سطر واحد.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>علّل: كان تقديم الشهادتين على باقي الأركان أمرا لازما.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>كيف تكون الدراسة عبادة؟ استدل بحديث مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>اذكر ثلاث صور من صور التكافل في المجتمع المغربي تحقق مقصد الزكاة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>ما الفرق بين الركن والسنة؟ مثّل لكل واحد.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميلك يقول: «أنا أحسن الأخلاق ولا أصلي، والأخلاق أهم». حرّر ردا من ستة أسطر بحجة شرعية وأسلوب لطيف.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل العلاقة بين الصوم وتربية الإرادة عند المتعلم(ة) في مواجهة الهاتف والسهر.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز مبيانا شجريا لمفهوم العبادة يوضح فرعيها وأمثلتهما.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب خمسة أسطر تبيّن كيف يتحول العمل العادي (كتنظيف القسم) إلى عبادة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"العبادة","v":"كل ما يحبه الله ويرضاه من قول أو عمل بإخلاص وموافقة للشرع"},{"r":"الإخلاص","v":"تصفية العمل من كل قصد غير وجه الله"},{"r":"المتابعة","v":"موافقة العمل لهدي النبي صلى الله عليه وسلم"},{"r":"الركن","v":"ما لا يقوم البناء إلا به، وتركُه يُخلّ بالإسلام"},{"r":"النصاب","v":"القدر الذي إذا بلغه المال وجبت فيه الزكاة"},{"r":"المناسك","v":"أعمال الحج المشروعة كالطواف والسعي والوقوف بعرفة"},{"r":"العبادات المتعدية","v":"ما ينتفع به الغير كالإحسان وطلب العلم وإتقان العمل"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — 1) عرّف العبادة اصطلاحا. 2) اذكر أركان الإسلام مرتبة. 3) اذكر شرطي قبول العمل.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — اربط في جدول بين ثلاثة أركان وغاياتها التربوية والاجتماعية، مع الاستشهاد بنص واحد والعزو إليه.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: نادي التضامن بمؤسستك يعدّ عملية دعم لتلاميذ محتاجين. اكتب كلمة من ثمانية أسطر تحفّز الزملاء على المشاركة، مبيّنا أن هذا العمل عبادة، بدليل شرعي مع العزو.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 2 ن، الأركان 3 ن (0,6 لكل ركن)، الشرطان 2 ن.</li><li>التمرين الثاني: 1,5 ن لكل ركن مع غايته، و1,5 ن للاستشهاد الصحيح مع العزو.</li><li>التمرين الثالث: بيان أن العمل عبادة متعدية 2 ن، الاستشهاد مع العزو 2 ن، قوة الإقناع والتنظيم 2 ن، سلامة اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei05","domaine":"islamique","unite":5,"theme":"الوحدة الأولى","tag":"EI05","langue":"ar","titre":"مدخل القسط 1: حق الله (التوحيد والإخلاص)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) القسط والحق والتوحيد والإخلاص.","أن يبيّن أن حق الله مقدّم على سائر الحقوق وأنه أصلها.","أن يستدل على وجوب التوحيد والإخلاص بنصوص مع العزو.","أن يميّز بين العمل المخلص وعمل الرياء بأمثلة من واقعه.","أن يقترح سلوكات عملية لتحقيق الإخلاص في حياته المدرسية."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: تلميذان ساهما في تنظيف ساحة المؤسسة؛ أحدهما عمل بجدّ ولم يبحث عن التصوير، والآخر التقط صورا ونشرها وتوقف عن العمل بعدها. العملان في الظاهر واحد، فما الذي فرّق بينهما عند الله؟</p>\n<p><strong>مفاهيم أساسية</strong>:</p>\n<blockquote><p><strong>القسط</strong>: العدل وإعطاء كل ذي حق حقه من غير جور ولا نقصان، قال تعالى: «وَأَقِيمُوا الْوَزْنَ بِالْقِسْطِ» (سورة الرحمن، الآية 9).</p></blockquote>\n<blockquote><p><strong>حق الله</strong>: ما وجب للله تعالى على عباده، وأصله <strong>التوحيد</strong>: عبادته وحده لا شريك له، ثم طاعته فيما أمر ونهى.</p></blockquote>\n<blockquote><p><strong>التوحيد</strong>: إفراد الله تعالى بالربوبية (الخلق والملك والتدبير) والألوهية (العبادة) والأسماء والصفات.</p></blockquote>\n<blockquote><p><strong>الإخلاص</strong>: تصفية القصد لله في العمل، بحيث لا يبتغي العامل بعمله إلا وجه الله.</p></blockquote>\n<p><strong>دليل تقديم حق الله</strong>: عن معاذ بن جبل رضي الله عنه أن النبي صلى الله عليه وسلم قال: «يا معاذ، أتدري ما حق الله على العباد؟ ... حق الله على العباد أن يعبدوه ولا يشركوا به شيئا» (أخرجه البخاري، كتاب الجهاد، حديث رقم 2856، ومسلم، كتاب الإيمان، حديث رقم 30). وقال تعالى: «وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا» (سورة النساء، الآية 36)، فبدأ بحق الله قبل ذكر حقوق الوالدين والأقارب والجيران، وهذا ترتيب دالّ.</p>\n<p><strong>الإخلاص ميزان القبول</strong>: قال صلى الله عليه وسلم: «إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى» (أخرجه البخاري، كتاب بدء الوحي، حديث رقم 1، ومسلم، كتاب الإمارة، حديث رقم 1907). وقال تعالى: «فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ» (سورة الزمر، الآية 2).</p>\n<p><strong>ضدّ الإخلاص: الرياء والشرك الأصغر</strong>: الرياء أن يعمل الإنسان العمل الصالح ليراه الناس ويثنوا عليه. وهو من الأمراض الخفية التي تُحبط الأجر؛ وقد ورد في الحديث: «من كان يرجو لقاء ربه فليعمل عملا صالحا ولا يشرك بعبادة ربه أحدا» (سورة الكهف، الآية 110) بيانا قرآنيا لشرط القبول.</p>\n<p><strong>علامات الإخلاص</strong>: استواء العمل في السر والعلن، وعدم التوقف عن الخير عند غياب الثناء، وقبول النصيحة، وعدم انتظار المقابل. ومن <strong>وسائل تحقيقه</strong>: تجديد النية قبل العمل، وإخفاء بعض الأعمال الصالحة، والدعاء بصلاح القلب، وتذكّر أن الله مطلع على السرائر.</p>\n<p><strong>الأثر في الحياة المدرسية</strong>: المتعلم المخلص يراجع دروسه لأن العلم أمانة لا ليقال إنه الأول فقط؛ ولا يغش في الفرض لأن الرقيب هو الله لا الأستاذ؛ ويؤدي عمل المجموعة كاملا وإن لم يُنسب إليه؛ ويشارك في أنشطة المؤسسة خدمة لا استعراضا. وهذا معنى قول العلماء: <strong>الإخلاص يجعل من التلميذ عاملا لا ممثلا</strong>.</p>\n<p><strong>السياق المغربي</strong>: تُبرز الثوابت الدينية بالمغرب مركزية التوحيد؛ فخطبة الجمعة، ودرس المسجد، ومواسم الذكر والمواسم الدينية كذكرى المولد النبوي، كلها فضاءات لتجديد التوحيد وتصحيح المقاصد. وإمارة المؤمنين مؤسسة تحمي هذا الأصل بحفظ وحدة العقيدة ومنع الفتنة في الدين.</p>\n<p><strong>مثال محلول 1</strong>: تلميذ يتصدق أمام الكاميرا. الجواب: العمل نافع للفقير في ذاته، لكن أجر صاحبه ينقص أو يذهب بحسب قصده؛ والأولى إخفاء الصدقة إلا إذا قصد تحفيز غيره بلا استعراض.</p>\n<p><strong>مثال محلول 2</strong>: من يترك الصلاة في السفر خوف السخرية. الجواب: هذا خوف من غير الله في موضع طاعته، والصواب أداء الحق لصاحبه؛ فحق الله مقدّم على رضا الناس.</p>\n<p><strong>مثال محلول 3</strong>: من يذاكر ليتفوق ويعيل أسرته مستقبلا وينفع بلده. الجواب: هذا مقصد صالح، فالنية الحسنة تحوّل العمل الدنيوي إلى عبادة، ولا مانع من قصد النجاح ما لم يزاحم قصدَ وجه الله.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>القسط</td><td>العدل وإعطاء كل ذي حق حقه</td></tr><tr><td>حق الله</td><td>ما وجب للله على عباده، وأصله التوحيد والطاعة</td></tr><tr><td>توحيد الربوبية</td><td>إفراده بالخلق والملك والتدبير</td></tr><tr><td>توحيد الألوهية</td><td>إفراده بالعبادة والدعاء والاستعانة</td></tr><tr><td>الإخلاص</td><td>تصفية العمل من كل قصد غير وجه الله</td></tr><tr><td>الرياء</td><td>إظهار العمل الصالح لينال ثناء الناس</td></tr><tr><td>السرّ والعلن</td><td>استواء حال العبد فيهما علامة الإخلاص</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الظن أن الإخلاص يعني ترك كل عمل ظاهر؛ والصواب أن إظهار الخير للتحفيز جائز إذا خلا من طلب الثناء.</li><li>⚠️ الخلط بين <strong>الرياء</strong> وبين <strong>فرح المؤمن بالثناء</strong> بعد العمل؛ الأول قصد فاسد قبل العمل، والثاني شعور لا يُؤاخذ عليه إن لم يُطلب.</li><li>⚠️ تصور أن حق الله ينافس حقوق الناس؛ والصواب أنه أصلها، فمن عرف حق الله أدى حق والديه وجاره وبيئته.</li><li>⚠️ اعتبار النية وحدها كافية؛ والصواب أن العمل يحتاج إخلاصا في القصد وصوابا في الصفة.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف: القسط، حق الله، الإخلاص، الرياء.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>أتمم حديث معاذ رضي الله عنه: «حق الله على العباد ...» مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر أقسام التوحيد الثلاثة مع تعريف موجز لكل قسم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>أتمم: «فَاعْبُدِ اللَّهَ ...» واذكر السورة والآية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>اذكر ثلاث علامات للإخلاص.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>علّل تقديم حق الله على حقوق الخلق بثلاثة أوجه.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ميّز بين المواقف الآتية: من يذاكر ليرضي الله ووالديه / من يذاكر ليقال إنه عبقري / من يترك المذاكرة اتكالا على القدر.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>اذكر ثلاث وسائل عملية لتحقيق الإخلاص في الحياة المدرسية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>ما أثر الرياء على العمل الصالح؟ استدل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>كيف يكون رفض الغش في الامتحان تحقيقا لحق الله؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميلك لا يشارك في تنظيف القسم إلا حين يحضر المدير. حرّر حوارا من ست جمل تصحّح فيه مفهومه للعمل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل العبارة: «الإخلاص يجعل من التلميذ عاملا لا ممثلا».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>قارن في جدول بين المخلص والمرائي من حيث: القصد، الاستمرارية، السر والعلن، الأثر في الغير، والنتيجة عند الله.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب فقرة من ستة أسطر عن أثر التوحيد في تحرير الإنسان من الخوف والتبعية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"القسط","v":"العدل وإعطاء كل ذي حق حقه"},{"r":"حق الله","v":"ما وجب للله على عباده، وأصله التوحيد والطاعة"},{"r":"توحيد الربوبية","v":"إفراده بالخلق والملك والتدبير"},{"r":"توحيد الألوهية","v":"إفراده بالعبادة والدعاء والاستعانة"},{"r":"الإخلاص","v":"تصفية العمل من كل قصد غير وجه الله"},{"r":"الرياء","v":"إظهار العمل الصالح لينال ثناء الناس"},{"r":"السرّ والعلن","v":"استواء حال العبد فيهما علامة الإخلاص"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — عرّف القسط والإخلاص والرياء، ثم اذكر أقسام التوحيد.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — أتمم حديث «إنما الأعمال ...» مع العزو، وبيّن وجه دلالته على أن الإخلاص شرط قبول العمل.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: عُرض عليك في مجموعة الواتساب حلّ الفرض قبل موعده. اكتب ثمانية أسطر تبيّن موقفك ومبرراته الشرعية والتربوية، مع استشهاد واحد والعزو.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: 1,5 ن لكل تعريف صحيح، 2,5 ن لأقسام التوحيد الثلاثة.</li><li>التمرين الثاني: نص الحديث 2 ن، العزو 1 ن (البخاري 1، مسلم 1907)، وجه الدلالة 3 ن.</li><li>التمرين الثالث: رفض واضح مع تعليل بحق الله 3 ن، الاستشهاد مع العزو 2 ن، البديل العملي (المراجعة الجماعية المشروعة) 1 ن، سلامة اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei06","domaine":"islamique","unite":6,"theme":"الوحدة الأولى","tag":"EI06","langue":"ar","titre":"مدخل الحكمة 1: الإتقان عبادة وعملا","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) الإتقان والإحسان لغة واصطلاحا.","أن يستدل على مشروعية الإتقان ومنزلته بنصوص مع العزو.","أن يبيّن مجالات الإتقان في العبادة والدراسة والعمل.","أن يستخرج آثار الإتقان على الفرد والأسرة والوطن.","أن يضع خطة شخصية لإتقان عمله المدرسي."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: أنجز فريقان مجسّما لعرض علمي: الأول أتمّ عمله بسرعة بأخطاء في القياسات وأوراق ممزقة، والثاني أعاد القياس ونظّف المجسّم وكتب البيانات بخط واضح. حصل الثاني على تقدير أفضل، فقال الأول: «المهم أن ننجز». فأي الفهمين يوافق تعليم الإسلام؟</p>\n<p><strong>تعريف الإتقان</strong>: الإتقان <strong>لغة</strong> من أتقن الشيء أي أحكمه وأحسن صنعه. و<strong>اصطلاحا</strong>:</p>\n<blockquote><p><strong>الإتقان</strong>: أداء العمل على أحسن وجه ممكن، بضبط أصوله وشروطه، وإحكام تفاصيله، وبلوغ درجة الجودة المتاحة، بنية التقرب إلى الله.</p></blockquote>\n<p>وهو ثمرة <strong>الإحسان</strong>، وقد جاء في الحديث: «إن الله كتب الإحسان على كل شيء» (أخرجه مسلم في صحيحه، كتاب الصيد والذبائح، حديث رقم 1955). وفي الحديث الآخر: «إن الله تعالى يحب إذا عمل أحدكم عملا أن يتقنه» (أخرجه أبو يعلى في مسنده، وحسّنه الألباني في صحيح الجامع الصغير برقم 1880؛ وقد تكلم بعض المحدثين في إسناده، ومعناه صحيح تشهد له نصوص كثيرة).</p>\n<p><strong>الإتقان في الخلق دليل ونموذج</strong>: قال الله تعالى: «صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ» (سورة النمل، الآية 88)، وقال: «الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ» (سورة السجدة، الآية 7)، وقال: «مَا تَرَىٰ فِي خَلْقِ الرَّحْمَٰنِ مِنْ تَفَاوُتٍ» (سورة الملك، الآية 3). فالكون كله مبني على الإحكام، والمؤمن يقتدي بسنة الله في خلقه فيُحكم عمله.</p>\n<p><strong>مجالات الإتقان</strong>:</p>\n<ol><li><strong>في العبادة</strong>: إتمام أركان الصلاة والطمأنينة فيها؛ فقد قال النبي صلى الله عليه وسلم للذي لم يطمئن في صلاته: «ارجع فصلّ، فإنك لم تصلّ» (أخرجه البخاري، كتاب الأذان، حديث رقم 757).</li><li><strong>في الدراسة</strong>: ضبط الدرس، وترتيب الدفتر، ومراجعة الجواب قبل تسليم الورقة، وتقديم عمل نظيف مقروء.</li><li><strong>في المهنة والحرفة</strong>: الأمانة في الصنعة؛ وللمغرب في هذا تراث عريق في الصناعة التقليدية (الزليج بفاس، النقش على النحاس، النجارة والزخرفة في المدارس العلمية العتيقة) يقوم كله على قاعدة الإتقان وتوريث الحرفة بالمعايير.</li><li><strong>في العمل الجماعي والمواطنة</strong>: احترام المواعيد، وإتمام النصيب من العمل، والحفاظ على المرافق العمومية.</li></ol>\n<p><strong>شروط الإتقان</strong>: صحة النية، والعلم بأصول العمل (فلا إتقان مع جهل)، والتخطيط والتدرج، والمراجعة والتقويم الذاتي، والصبر على التفاصيل، وقبول الملاحظات.</p>\n<p><strong>عوائق الإتقان</strong>: العجلة، والتسويف، والاكتفاء بالحد الأدنى، والغش الذي يوهم بالنجاح دون كفاءة، وضعف تدبير الوقت.</p>\n<p><strong>آثار الإتقان</strong>: للفرد ثقة بالنفس ورضا وأجر عند الله؛ وللأسرة استقرار وحُسن سمعة؛ وللوطن جودة في المنتوج والخدمة وتنافسية اقتصادية؛ ولذلك ارتبط شعار الجودة في المشاريع التنموية بالمغرب بمعايير الإتقان في التكوين المهني والصناعة.</p>\n<p><strong>مثال محلول 1</strong>: تلميذ يسلّم بحثا منسوخا حرفيا من الإنترنت. الجواب: هذا ليس إتقانا بل تفريط وأمانة مخرومة؛ فالإتقان أن يقرأ ويفهم ويعيد الصياغة ويوثّق مصادره.</p>\n<p><strong>مثال محلول 2</strong>: صانع يخفي عيبا في المنتوج. الجواب: هذا نقيض الإتقان ومن الغش المحرّم، وقد قال النبي صلى الله عليه وسلم: «من غشّ فليس مني» (أخرجه مسلم، كتاب الإيمان، حديث رقم 102 بمعناه: «من غشّنا فليس منا»).</p>\n<p><strong>مثال محلول 3</strong>: تلميذة تعيد كتابة تمرين رياضيات بخط أوضح وتتحقق من النتيجة. الجواب: هذا إتقان في الدراسة، وأثره مباشر في النقطة وفي بناء العادة.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>الإتقان</td><td>إحكام العمل وأداؤه على أحسن وجه</td></tr><tr><td>الإحسان</td><td>فعل الحسن، ومنه مراقبة الله في العمل</td></tr><tr><td>الجودة</td><td>بلوغ العمل المعايير المطلوبة وزيادة</td></tr><tr><td>التسويف</td><td>تأخير العمل عن وقته بلا عذر</td></tr><tr><td>الغشّ</td><td>إخفاء عيب أو تحصيل نتيجة بغير استحقاق</td></tr><tr><td>التقويم الذاتي</td><td>مراجعة المرء عمله لتصحيحه قبل تسليمه</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الخلط بين الإتقان و<strong>الكمال المستحيل</strong>؛ المطلوب أحسن وجه ممكن في حدود الطاقة، لا الوسوسة والتعطيل.</li><li>⚠️ حصر الإتقان في المظهر (خط جميل) مع إهمال المضمون؛ والصواب أن الإتقان يشمل الصحة والدقة والترتيب معا.</li><li>⚠️ الظن أن السرعة دليل النجاح؛ والصواب أن العجلة تُنقص الجودة، وقد وصف النبي صلى الله عليه وسلم التأني بأنه من الله.</li><li>⚠️ اعتبار الإتقان شأنا دنيويا لا أجر فيه؛ والصواب أنه عبادة إذا صحبته النية.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف الإتقان لغة واصطلاحا.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>أتمم: «إن الله كتب الإحسان ...» مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>أتمم الآية: «صُنْعَ اللَّهِ الَّذِي ...» مع ذكر السورة والآية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر أربعة مجالات للإتقان.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>اذكر ثلاثة من عوائق الإتقان.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>بيّن الفرق بين الإتقان والعجلة من حيث النتيجة، بمثالين من حياتك المدرسية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>كيف يكون إتمام الصلاة والطمأنينة فيها إتقانا؟ استدل بحديث مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>اذكر ثلاثة شروط للإتقان واشرح واحدا منها.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>اربط بين الإتقان في الصناعة التقليدية المغربية وسمعة المنتوج الوطني.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>لماذا يُعدّ الغش نقيضا للإتقان؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: كُلّفتم بإعداد عرض جماعي في مادة الجغرافيا. ضع خطة عمل من خمس خطوات تضمن إتقان العرض وتوزيع المهام.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل العبارة: «الإتقان عبادة قبل أن يكون مهارة».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>قارن في جدول بين عمل متقن وعمل مهمل من حيث: النية، التخطيط، الوقت، النتيجة، أثره على الغير.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب سبعة أسطر عن أثر الإتقان في تنمية بلدك، مستشهدا بنص شرعي مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"الإتقان","v":"إحكام العمل وأداؤه على أحسن وجه"},{"r":"الإحسان","v":"فعل الحسن، ومنه مراقبة الله في العمل"},{"r":"الجودة","v":"بلوغ العمل المعايير المطلوبة وزيادة"},{"r":"التسويف","v":"تأخير العمل عن وقته بلا عذر"},{"r":"الغشّ","v":"إخفاء عيب أو تحصيل نتيجة بغير استحقاق"},{"r":"التقويم الذاتي","v":"مراجعة المرء عمله لتصحيحه قبل تسليمه"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — 1) عرّف الإتقان اصطلاحا. 2) اذكر ثلاثة شروط له وثلاثة عوائق.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — أتمم النصين مع العزو: «إن الله كتب الإحسان ...» و«صُنْعَ اللَّهِ الَّذِي ...»، ثم بيّن وجه الاستدلال بهما على وجوب إحكام العمل.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: أُسند إلى قسمكم إعداد لوحة إعلامية عن التراث المحلي لعرضها في أسبوع المؤسسة. حرّر عشرة أسطر تقترح فيها خطة إتقان اللوحة وتبيّن أثر الإتقان على صورة المؤسسة، مع استشهاد واحد والعزو.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 2 ن، الشروط 2 ن، العوائق 2 ن.</li><li>التمرين الثاني: كل نص 1,5 ن مع عزوه، ووجه الاستدلال 3 ن (الله أتقن خلقه فالاقتداء يقتضي إحكام العمل، والإحسان مكتوب على كل شيء فيشمل كل عمل).</li><li>التمرين الثالث: خطة من خطوات واضحة 3 ن، بيان الأثر 2 ن، الاستشهاد مع العزو 2 ن، سلامة اللغة 1 ن.</li></ul>\n<hr>\n<p>## الوحدة الثانية</p>"}},
{"id":"islamique-ei07","domaine":"islamique","unite":7,"theme":"الوحدة الثانية","tag":"EI07","langue":"ar","titre":"مدخل التزكية (القرآن الكريم) 2: الشطر الثاني من سورة ق (الآية 16 إلى 37)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يرتّل المتعلم(ة) الآيات 16-37 من سورة ق ترتيلا سليما.","أن يحفظ المقطع أو جزءا منه حسب ما يقرره الأستاذ(ة).","أن يشرح مفردات المقطع شرحا صحيحا.","أن يستخرج مضامينه: قرب الله من الإنسان، كتابة الملكين، سكرة الموت، أهوال القيامة، جزاء الفريقين.","أن يطبّق أحكام القلقلة على أمثلة من المقطع.","أن يستثمر مضامين المقطع في مراقبة الله في القول والعمل."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: نشر تلميذ تعليقا ساخرا من زميله في مجموعة القسم، ثم حذفه بعد دقائق وقال: «انتهى الأمر، لم يعد له أثر». فهل تُمحى الكلمة فعلا؟ الشطر الثاني من سورة ق يجيب بجواب حاسم.</p>\n<p><strong>نص المقطع (نماذج من الآيات مع الحفاظ على الترتيب)</strong>:</p>\n<blockquote><p>«وَلَقَدْ خَلَقْنَا الْإِنْسَانَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِ نَفْسُهُ ۖ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ (16) إِذْ يَتَلَقَّى الْمُتَلَقِّيَانِ عَنِ الْيَمِينِ وَعَنِ الشِّمَالِ قَعِيدٌ (17) مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ (18) وَجَاءَتْ سَكْرَةُ الْمَوْتِ بِالْحَقِّ ۖ ذَٰلِكَ مَا كُنْتَ مِنْهُ تَحِيدُ (19) وَنُفِخَ فِي الصُّورِ ۚ ذَٰلِكَ يَوْمُ الْوَعِيدِ (20) وَجَاءَتْ كُلُّ نَفْسٍ مَعَهَا سَائِقٌ وَشَهِيدٌ (21) لَقَدْ كُنْتَ فِي غَفْلَةٍ مِنْ هَٰذَا فَكَشَفْنَا عَنْكَ غِطَاءَكَ فَبَصَرُكَ الْيَوْمَ حَدِيدٌ (22)» — سورة ق، الآيات 16-22.</p></blockquote>\n<blockquote><p>«وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ (31) هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍ (32) مَنْ خَشِيَ الرَّحْمَٰنَ بِالْغَيْبِ وَجَاءَ بِقَلْبٍ مُنِيبٍ (33) ادْخُلُوهَا بِسَلَامٍ ۖ ذَٰلِكَ يَوْمُ الْخُلُودِ (34) لَهُمْ مَا يَشَاءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ (35)» — سورة ق، الآيات 31-35.</p></blockquote>\n<blockquote><p>«إِنَّ فِي ذَٰلِكَ لَذِكْرَىٰ لِمَنْ كَانَ لَهُ قَلْبٌ أَوْ أَلْقَى السَّمْعَ وَهُوَ شَهِيدٌ (37)» — سورة ق، الآية 37.</p></blockquote>\n<p><strong>شرح المفردات</strong>:</p>\n<table><thead><tr><th>الكلمة</th><th>الشرح</th></tr></thead><tbody><tr><td>توسوس به نفسه</td><td>تحدّثه به نفسه سرّا</td></tr><tr><td>حبل الوريد</td><td>عرق في العنق، كناية عن شدة القرب</td></tr><tr><td>المتلقيان</td><td>الملكان الموكلان بكتابة الأعمال</td></tr><tr><td>قعيد</td><td>جالس ملازم</td></tr><tr><td>رقيب عتيد</td><td>حاضر حافظ لا يغيب</td></tr><tr><td>سكرة الموت</td><td>شدته وغمرته</td></tr><tr><td>تحيد</td><td>تميل عنه وتهرب</td></tr><tr><td>الصور</td><td>القرن الذي ينفخ فيه إسرافيل</td></tr><tr><td>سائق وشهيد</td><td>ملك يسوقه وملك يشهد عليه</td></tr><tr><td>أوّاب</td><td>كثير الرجوع إلى الله بالتوبة</td></tr><tr><td>حفيظ</td><td>حافظ لحدود الله وأوامره</td></tr><tr><td>أُزلفت</td><td>قُرّبت</td></tr><tr><td>مزيد</td><td>زيادة من النعيم فوق ما يشاءون</td></tr></tbody></table>\n<p><strong>المضامين الأساسية</strong>: يبدأ المقطع بإثبات <strong>إحاطة علم الله</strong> بالإنسان حتى بحديث نفسه، وقربه منه قربا يفوق قرب حبل الوريد؛ ثم يذكّر بـ<strong>الملكين الكاتبين</strong> اللذين لا يفوتهما قول ولا عمل؛ ثم ينتقل إلى <strong>سكرة الموت</strong> التي لا مفرّ منها، ثم إلى <strong>النفخ في الصور</strong> ومجيء كل نفس مع سائق وشهيد، ثم إلى <strong>كشف الغطاء</strong> وزوال الغفلة، ثم إلى <strong>محاورة القرين</strong> ومصير الكافر المعاند المنّاع للخير، ثم إلى <strong>مشهد الجنة</strong> وقد أُزلفت للمتقين الأوّابين الحافظين الخاشين ربهم بالغيب، وتُختم الآيات بأن هذا كله ذكرى لمن كان له قلب واعٍ أو ألقى سمعه وهو حاضر الذهن.</p>\n<blockquote><p><strong>قاعدة تربوية</strong>: الآية 18 «مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ» أصل في <strong>مسؤولية الكلمة</strong>، منطوقة كانت أو مكتوبة على الشاشة.</p></blockquote>\n<p><strong>القاعدة الترتيلية — القلقلة</strong>: القلقلة اضطراب في مخرج الحرف عند سكونه حتى يُسمع له نبرة قوية، وحروفها مجموعة في «قُطْبُ جَدٍّ» (ق، ط، ب، ج، د). وهي نوعان: <strong>صغرى</strong> إذا كان الحرف ساكنا في وسط الكلمة، مثل «يَقْطَعُونَ»، ومنه في مقطعنا «أَقْرَبُ» في الآية 16. و<strong>كبرى</strong> إذا كان الحرف آخر الكلمة ووُقف عليه، مثل الوقف على «مَزِيدٌ» — وهي دال — و«الْوَعِيدِ» في الآية 20.</p>\n<p><strong>نشاط تطبيقي</strong>: يستخرج المتعلمون من المقطع خمس كلمات فيها قلقلة ويصنفونها إلى صغرى وكبرى، مع بيان الحرف.</p>\n<p><strong>مثال محلول 1</strong>: ما دلالة قوله «وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ»؟ الجواب: قرب علم الله وإحاطته واطلاعه، لا قرب مسافة ولا حلول؛ وهذا موافق للعقيدة الأشعرية في تنزيه الله عن المكان والجهة.</p>\n<p><strong>مثال محلول 2</strong>: كيف نستفيد من الآية 22 «لَقَدْ كُنْتَ فِي غَفْلَةٍ مِنْ هَٰذَا»؟ الجواب: الغفلة سبب التفريط، وعلاجها الذكر والمحاسبة اليومية؛ فيخصص المتعلم دقائق قبل النوم لمراجعة يومه.</p>\n<p><strong>مثال محلول 3</strong>: ما صفات أهل الجنة في الآيات 32-33؟ الجواب: أوّاب (كثير التوبة)، حفيظ (حافظ لحدود الله)، خاشٍ للرحمن بالغيب (يراقبه حيث لا يراه الناس)، جاء بقلب منيب. وهذه الصفات كلها قابلة للتطبيق في سنّ المتعلم.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<ul><li>علم الله محيط بالسر والعلن وبحديث النفس.</li><li>الملكان الكاتبان: رقيب عتيد، عن اليمين وعن الشمال.</li><li>مراحل مصير الإنسان في المقطع: الموت ← النفخ في الصور ← الحشر ← كشف الغطاء ← الحساب ← الجزاء.</li><li>صفات أهل الجنة: أوّاب، حفيظ، خاشٍ بالغيب، صاحب قلب منيب.</li><li>شرط الانتفاع بالذكرى: قلب واعٍ أو إصغاء حاضر (الآية 37).</li><li>القلقلة: حروفها (قطب جدّ)، وأنواعها صغرى وكبرى.</li></ul>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ فهم «أقرب إليه من حبل الوريد» على قرب المسافة؛ والصواب أنه قرب العلم والإحاطة، تنزيها لله عن الجسمية والمكان.</li><li>⚠️ الظن أن الملكين يكتبان الأفعال دون الأقوال؛ والآية صريحة في القول: «مَا يَلْفِظُ مِنْ قَوْلٍ».</li><li>⚠️ الخلط بين القلقلة الصغرى والكبرى؛ الضابط: سكون أصلي في وسط الكلمة (صغرى) أو سكون بسبب الوقف في آخرها (كبرى).</li><li>⚠️ الاقتصار على تخويف المتعلمين بمشاهد العذاب؛ والتوازن القرآني يجمع بين الترغيب والترهيب، والمقطع ذكر الجنة كما ذكر النار.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>اشرح: حبل الوريد، عتيد، تحيد، أوّاب، أُزلفت.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اكتب من حفظك الآيات 16-18 من سورة ق مع الشكل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>من هما المتلقيان؟ وأين موقع كل واحد منهما؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر حروف القلقلة، ومثّل بمثال من المقطع لكل نوع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>أتمم: «مَا يَلْفِظُ مِنْ قَوْلٍ ...» مع رقم الآية.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>رتّب المشاهد كما وردت في المقطع: الحشر، سكرة الموت، النفخ في الصور، كشف الغطاء، دخول الجنة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>استخرج من المقطع أربع صفات لأهل الجنة واشرح كل صفة في سطر.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>بيّن كيف تكون الآية 18 قاعدة في التعامل مع مواقع التواصل الاجتماعي.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>ما المقصود بقوله تعالى «فَبَصَرُكَ الْيَوْمَ حَدِيدٌ»؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>علّل: ختم المقطع بقوله «لِمَنْ كَانَ لَهُ قَلْبٌ أَوْ أَلْقَى السَّمْعَ وَهُوَ شَهِيدٌ».</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميلك يسبّ ويعتذر قائلا: «كلام وينتهي». اكتب سبعة أسطر تردّ عليه بمضامين المقطع مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف يجمع المقطع بين الترهيب والترغيب؟ وما أثر هذا التوازن في تربية المتعلم(ة)؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز جدولا: (الآية / المشهد / القيمة التربوية) لخمس آيات من المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>قارن بين «الغافل» و«الأوّاب الحفيظ» من خلال المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"توسوس به نفسه","v":"تحدّثه به نفسه سرّا"},{"r":"حبل الوريد","v":"عرق في العنق، كناية عن شدة القرب"},{"r":"المتلقيان","v":"الملكان الموكلان بكتابة الأعمال"},{"r":"قعيد","v":"جالس ملازم"},{"r":"رقيب عتيد","v":"حاضر حافظ لا يغيب"},{"r":"سكرة الموت","v":"شدته وغمرته"},{"r":"تحيد","v":"تميل عنه وتهرب"},{"r":"الصور","v":"القرن الذي ينفخ فيه إسرافيل"},{"r":"سائق وشهيد","v":"ملك يسوقه وملك يشهد عليه"},{"r":"أوّاب","v":"كثير الرجوع إلى الله بالتوبة"},{"r":"حفيظ","v":"حافظ لحدود الله وأوامره"},{"r":"أُزلفت","v":"قُرّبت"},{"r":"مزيد","v":"زيادة من النعيم فوق ما يشاءون"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — اكتب الآيات 31-33 مع الشكل، واشرح: أزلفت، أوّاب، حفيظ.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — استخرج من المقطع ثلاثة مشاهد من مشاهد يوم القيامة مرتبة، مع الاستشهاد لكل مشهد.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: انتشر في مجموعة القسم مقطع فيه سخرية من تلميذ. اكتب ثمانية أسطر تبيّن حكم ذلك وأثره، وتقترح حلا عمليا، مستشهدا بآيتين من المقطع مع العزو.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: الآيات 4 ن، الشرح 3 ن.</li><li>التمرين الثاني: 2 ن لكل مشهد مع استشهاده (سكرة الموت 19؛ النفخ في الصور 20؛ مجيء النفس مع سائق وشهيد 21)، وتُخصم 0,5 عن خطأ الترتيب.</li><li>التمرين الثالث: بيان حرمة السخرية وتسجيل القول 3 ن، الاستشهاد مع العزو 2 ن، الحل العملي (الاعتذار، حذف المقطع، تدخل الأستاذ) 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei08","domaine":"islamique","unite":8,"theme":"الوحدة الثانية","tag":"EI08","langue":"ar","titre":"مدخل التزكية (العقيدة) 2: أركان الإيمان (حديث جبريل عليه السلام)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يروي المتعلم(ة) حديث جبريل عليه السلام ويعزوه إلى مصدره.","أن يعدّد أركان الإيمان الستة ويعرّف كل ركن.","أن يميّز بين مراتب الدين الثلاث: الإسلام والإيمان والإحسان.","أن يبيّن أثر الإيمان بكل ركن في سلوك المؤمن.","أن يستثمر مفهوم الإحسان في تقويم أعماله اليومية."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: سأل أب ابنه: «ما الفرق بين قولنا: فلان مسلم، وفلان مؤمن، وفلان محسن؟» فتردد الابن. وهذا الفرق بيّنه النبي صلى الله عليه وسلم في حديث واحد جامع سُمّي <strong>حديث جبريل</strong> وسمّاه العلماء «أم السنة».</p>\n<p><strong>نص الحديث</strong>: عن عمر بن الخطاب رضي الله عنه قال: بينما نحن جلوس عند رسول الله صلى الله عليه وسلم ذات يوم، إذ طلع علينا رجل شديد بياض الثياب، شديد سواد الشعر، لا يُرى عليه أثر السفر، ولا يعرفه منا أحد، حتى جلس إلى النبي صلى الله عليه وسلم فأسند ركبتيه إلى ركبتيه ووضع كفيه على فخذيه وقال: يا محمد أخبرني عن الإسلام. فقال: «الإسلام أن تشهد أن لا إله إلا الله وأن محمدا رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلا». قال: صدقت. قال: فأخبرني عن الإيمان. قال: «أن تؤمن بالله وملائكته وكتبه ورسله واليوم الآخر، وتؤمن بالقدر خيره وشره». قال: صدقت. قال: فأخبرني عن الإحسان. قال: «أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك». ثم انصرف، فقال النبي صلى الله عليه وسلم: «هذا جبريل أتاكم يعلّمكم دينكم» (أخرجه مسلم في صحيحه، كتاب الإيمان، حديث رقم 8، وأخرجه البخاري بنحوه، كتاب الإيمان، حديث رقم 50).</p>\n<p><strong>أركان الإيمان الستة</strong>:</p>\n<table><thead><tr><th>الركن</th><th>معناه</th><th>أثره في السلوك</th></tr></thead><tbody><tr><td>الإيمان بالله</td><td>التصديق بوجوده ووحدانيته وكماله وتنزيهه</td><td>الطمأنينة، والاستقامة، وعدم الخوف من غيره</td></tr><tr><td>الإيمان بالملائكة</td><td>التصديق بوجودهم وأنهم عباد مكرمون لا يعصون الله</td><td>مراقبة الأقوال والأعمال (الكاتبون)</td></tr><tr><td>الإيمان بالكتب</td><td>التصديق بما أنزل الله من كتب، وآخرها القرآن</td><td>تعظيم الوحي والعمل بالقرآن</td></tr><tr><td>الإيمان بالرسل</td><td>التصديق برسالتهم جميعا، وخاتمهم محمد صلى الله عليه وسلم</td><td>الاقتداء وحسن اتباع الهدي</td></tr><tr><td>الإيمان باليوم الآخر</td><td>التصديق بالبعث والحساب والجزاء</td><td>الجدّ في العمل واجتناب الظلم</td></tr><tr><td>الإيمان بالقدر</td><td>التصديق بأن ما شاء الله كان، مع الأخذ بالأسباب</td><td>الرضا والصبر وعدم اليأس</td></tr></tbody></table>\n<p><strong>مراتب الدين الثلاث</strong>: <strong>الإسلام</strong> أعمال ظاهرة (الأركان الخمسة)، و<strong>الإيمان</strong> اعتقاد باطن (الأركان الستة)، و<strong>الإحسان</strong> مرتبة جامعة بينهما تُتقن بها العبادة، وهي أن تعبد الله كأنك تراه. فمن أدى الأركان الظاهرة فهو مسلم، ومن صدّق بالغيب فهو مؤمن، ومن استحضر مراقبة الله فبلغ درجة المحسنين.</p>\n<p><strong>الإيمان بالقدر ولا جبر</strong>: من الأخطاء الشائعة الاحتجاج بالقدر على ترك العمل. والصواب أن الإيمان بالقدر يقتضي الأخذ بالأسباب ثم التسليم للنتيجة، قال النبي صلى الله عليه وسلم: «احرص على ما ينفعك واستعن بالله ولا تعجز» (أخرجه مسلم، كتاب القدر، حديث رقم 2664).</p>\n<p><strong>السياق المغربي</strong>: يقوم الاعتقاد في المغرب على <strong>المنهج الأشعري</strong> الذي يجمع بين الدليل النقلي والنظر العقلي في مسائل الإيمان، ويحفظ التنزيه في صفات الله؛ وهذا ما يُدرَّس في الكتاتيب والمدارس العتيقة وفي دروس المساجد، ويحفظ وحدة الاعتقاد بين المغاربة.</p>\n<p><strong>مثال محلول 1</strong>: تلميذ يصلي في وقتها ويؤدي واجباته لكنه يغش في الامتحان. الجواب: نقص في مرتبة الإحسان؛ لأنه لم يستحضر أن الله يراه، فوقع التناقض بين العبادة والسلوك.</p>\n<p><strong>مثال محلول 2</strong>: من رسب فقال: «هذا قدري ولا فائدة من المحاولة». الجواب: فهم خاطئ للقدر؛ الصحيح أن يحلل أسباب الرسوب ويضع خطة، فالقدر لا يُعلم إلا بعد وقوعه، والأمر بالسعي قائم.</p>\n<p><strong>مثال محلول 3</strong>: من ينكر عذاب القبر أو الجنة والنار بحجة أنه لم يرها. الجواب: الإيمان تصديق بالغيب بخبر الصادق؛ والعقل يقبل ما لم يُدركه الحسّ إذا ثبت الخبر، وهذا معنى «الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ» (سورة البقرة، الآية 3).</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>الإيمان</td><td>تصديق بالقلب وقول باللسان وعمل بالجوارح</td></tr><tr><td>الغيب</td><td>ما غاب عن الحس ولا يُعلم إلا بخبر صادق</td></tr><tr><td>القدر</td><td>تقدير الله للأشياء بعلمه ومشيئته وكتابته وخلقه</td></tr><tr><td>الإحسان</td><td>أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك</td></tr><tr><td>أم السنة</td><td>وصف لحديث جبريل لجمعه أصول الدين</td></tr><tr><td>الملائكة</td><td>خلق نوراني مكرم لا يعصون الله ما أمرهم</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الاحتجاج بالقدر لترك السعي؛ والصواب أن الإيمان بالقدر يحفّز على العمل ويريح القلب من نتيجة ما بعد بذل الوسع.</li><li>⚠️ الظن أن الإسلام والإيمان مترادفان دائما؛ والتحقيق أنهما إذا اجتمعا في سياق واحد افترقا في المعنى، وإذا افترقا اجتمعا.</li><li>⚠️ حصر الإيمان في القلب دون عمل؛ والصواب أنه تصديق وقول وعمل، يزيد بالطاعة وينقص بالمعصية.</li><li>⚠️ الخوض في كيفية صفات الله؛ والمنهج الأشعري المعتمد بالمغرب يقوم على التنزيه وترك التشبيه.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>من روى حديث جبريل؟ وأين أُخرج؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>عدّد أركان الإيمان الستة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>عرّف الإحسان كما ورد في الحديث.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>ما معنى: الغيب، القدر، الملائكة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>لماذا سُمّي الحديث «أم السنة»؟</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>قارن في جدول بين الإسلام والإيمان والإحسان من حيث المعنى والمظهر.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>بيّن أثر الإيمان باليوم الآخر في ثلاثة سلوكات مدرسية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>كيف يُصحَّح فهم من يحتج بالقدر على الكسل؟ استدل بحديث مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>اذكر ثلاثة من أعمال الملائكة كما وردت في القرآن الكريم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>بيّن العلاقة بين الإيمان بالكتب والإيمان بالرسل.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميلك يقول: «الإيمان في القلب ولا يحتاج عملا». حرّر ردا من سبعة أسطر بدليل شرعي وحجة عقلية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف تجعل مرتبة الإحسان من المتعلم إنسانا صادقا حتى في الخلوة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز خطاطة تجمع مراتب الدين الثلاث وأركان كل مرتبة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ستة أسطر عن أثر الإيمان بالقدر في مواجهة الفشل الدراسي.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"الإيمان","v":"تصديق بالقلب وقول باللسان وعمل بالجوارح"},{"r":"الغيب","v":"ما غاب عن الحس ولا يُعلم إلا بخبر صادق"},{"r":"القدر","v":"تقدير الله للأشياء بعلمه ومشيئته وكتابته وخلقه"},{"r":"الإحسان","v":"أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك"},{"r":"أم السنة","v":"وصف لحديث جبريل لجمعه أصول الدين"},{"r":"الملائكة","v":"خلق نوراني مكرم لا يعصون الله ما أمرهم"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — اكتب جواب النبي صلى الله عليه وسلم عن الإيمان وعن الإحسان في حديث جبريل مع العزو، ثم عرّف الغيب.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — املأ جدولا يربط بين ثلاثة أركان من أركان الإيمان وأثر كل ركن في سلوك المتعلم(ة).</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: صديقك انقطع عن المراجعة بعد نقطة ضعيفة وقال: «كُتب عليّ الفشل». اكتب تسعة أسطر تصحح فيها فهمه للقدر وتقترح خطة عملية، مع استشهاد والعزو.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: نص الإيمان 3 ن، نص الإحسان 2 ن، العزو 1 ن، تعريف الغيب 1 ن.</li><li>التمرين الثاني: 2 ن لكل ركن مع أثره الصحيح.</li><li>التمرين الثالث: تصحيح مفهوم القدر 3 ن، الاستشهاد مع العزو 2 ن، الخطة العملية 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei09","domaine":"islamique","unite":9,"theme":"الوحدة الثانية","tag":"EI09","langue":"ar","titre":"مدخل الاقتداء 2: ثبات الرسول صلى الله عليه وسلم","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) الثبات ويميّزه عن العناد.","أن يذكر صور أذى قريش للنبي صلى الله عليه وسلم وأصحابه.","أن يستدل بمواقف من السيرة على ثبات النبي صلى الله عليه وسلم.","أن يستخرج مقومات الثبات وأسبابه.","أن يقتدي بالنبي صلى الله عليه وسلم في الثبات على المبدأ أمام ضغط المجموعة."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: تعرّضت تلميذة للسخرية لأنها ترفض المشاركة في مقاطع مسيئة لأستاذ، وضغط عليها بعض الزملاء بالمقاطعة. هل تتراجع أم تثبت؟ وكيف تثبت دون عنف؟ سيرة النبي صلى الله عليه وسلم تعطينا النموذج.</p>\n<p><strong>تعريف الثبات</strong>:</p>\n<blockquote><p><strong>الثبات</strong>: لزوم الحق والاستمرار عليه مع الصبر على المشاق، وعدم التراجع بسبب الإغراء أو التهديد أو سخرية الناس.</p></blockquote>\n<p>وليس الثبات عنادا؛ فالعناد لزوم الرأي بعد ظهور خطئه، والثبات لزوم الحق بعد ظهور صوابه، والفرق بينهما في <strong>الدليل</strong> لا في القوة.</p>\n<p><strong>صور الأذى الذي واجهه النبي صلى الله عليه وسلم وأصحابه</strong>: التكذيب والاستهزاء واتهامه بالسحر والشعر؛ وإيذاؤه في جسده كما فعل عقبة بن أبي معيط؛ ووضع الشوك في طريقه؛ ومحاولة إغرائه بالمال والملك مقابل ترك الدعوة؛ والحصار في <strong>شعب أبي طالب</strong> نحو ثلاث سنوات مع مقاطعة اقتصادية واجتماعية؛ وتعذيب المستضعفين كبلال بن رباح وآل ياسر وخباب بن الأرت. وقد قال خبّاب رضي الله عنه: «شكونا إلى رسول الله صلى الله عليه وسلم وهو متوسد بردة له في ظل الكعبة، فقلنا: ألا تستنصر لنا؟ ألا تدعو لنا؟ فقال: قد كان من قبلكم المؤمن يُمشط بأمشاط الحديد... والله لَيتمّنّ الله هذا الأمر حتى يسير الراكب من صنعاء إلى حضرموت لا يخاف إلا الله» (أخرجه البخاري في صحيحه، كتاب المناقب، حديث رقم 3612، بمعناه في مواضع أخرى).</p>\n<p><strong>مواقف دالة على ثباته</strong>: موقفه في <strong>الطائف</strong> حين ردّه أهلها وأغروا به سفهاءهم، فرجع ولم يدع عليهم بالهلاك بل قال دعاءه المعروف في الرجاء؛ وموقفه يوم أراد أعمامه أن يعرضوا عليه المال والزعامة فأبى الاستجابة لشرط ترك الدعوة؛ وثباته في عام الحصار حتى تمزقت الصحيفة. وقد سألت عائشة رضي الله عنها النبي صلى الله عليه وسلم: هل أتى عليك يوم كان أشد من يوم أحد؟ فذكر يوم العقبة بالطائف وما لقيه من ثقيف (أخرجه البخاري، كتاب بدء الخلق، حديث رقم 3231، ومسلم بنحوه، حديث رقم 1795).</p>\n<p><strong>مقومات الثبات (أسبابه)</strong>:</p>\n<ol><li><strong>قوة اليقين بالله</strong> ومعرفة أن النصر بيده: «إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا» (سورة النحل، الآية 128).</li><li><strong>الصلة بالقرآن</strong>، فقد كان الوحي ينزل مثبّتا: «فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ» (سورة الأحقاف، الآية 35).</li><li><strong>الرفقة الصالحة</strong>: صحبة أبي بكر وخديجة وأبي طالب في مرحلة الحماية.</li><li><strong>وضوح الهدف</strong> ومعرفة الغاية، فمن عرف لماذا يعمل صبر على كيف يعمل.</li><li><strong>الاعتبار بسنن السابقين</strong> كما في حديث خبّاب.</li><li><strong>الدعاء</strong> واللجوء إلى الله.</li></ol>\n<p><strong>ثمار الثبات</strong>: انتشار الدعوة، وتحوّل بعض الخصوم إلى أنصار، وقدوة عملية لكل مصلح، ودرس تاريخي أن الحق يحتاج زمنا وصبرا لا انفعالا.</p>\n<p><strong>الثبات في حياة المتعلم(ة)</strong>: الثبات على الصلاة في السفر وبين الأصدقاء، وعلى الصدق وإن خسر منفعة، وعلى رفض الغش والتدخين والمحتوى الضار، وعلى مواصلة الدراسة رغم الظروف الاجتماعية الصعبة. وفي المغرب أمثلة كثيرة لتلاميذ من مناطق جبلية يقطعون مسافات طويلة للوصول إلى الإعدادية، وهذا وجه من وجوه الثبات على طلب العلم.</p>\n<p><strong>مثال محلول 1</strong>: ما الفرق بين الثبات والتعصب؟ الجواب: الثبات مبني على دليل ويقبل الحوار في التفاصيل، والتعصب يرفض الدليل ويعادي المخالف؛ والنبي صلى الله عليه وسلم كان يثبت على أصل الرسالة ويرفق بالمخالف.</p>\n<p><strong>مثال محلول 2</strong>: كيف نثبت أمام ضغط المجموعة؟ الجواب: بتقوية القناعة بالمعرفة، وبالاعتزاز بالهوية، وباختيار الأصدقاء، وبالخروج من النقاش الجارح بأدب، وبإخبار الأستاذ أو الأسرة عند الحاجة.</p>\n<p><strong>مثال محلول 3</strong>: هل الثبات يعني عدم المرونة في الأساليب؟ الجواب: لا؛ فالنبي صلى الله عليه وسلم ثبت على الغاية وغيّر الأساليب (السرية ثم الجهر، الهجرة إلى الحبشة، عرض الدعوة على القبائل). الثبات في المبادئ والمرونة في الوسائل.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>الثبات</td><td>لزوم الحق والصبر على المشاق دون تراجع</td></tr><tr><td>العناد</td><td>التمسك بالرأي بعد ظهور خطئه</td></tr><tr><td>الحصار (شعب أبي طالب)</td><td>مقاطعة قريش لبني هاشم نحو ثلاث سنوات</td></tr><tr><td>يوم العقبة</td><td>يوم الطائف الذي لقي فيه النبي أشد الأذى</td></tr><tr><td>أولو العزم</td><td>الرسل أصحاب الصبر العظيم</td></tr><tr><td>ضغط المجموعة</td><td>تأثير الجماعة على الفرد لدفعه إلى سلوك ما</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الخلط بين الثبات والعنف؛ فثبات النبي صلى الله عليه وسلم بمكة كان بالصبر والحجة، لا بالانتقام.</li><li>⚠️ الظن أن الثبات يعني رفض تغيير الأساليب؛ والصواب المرونة في الوسائل مع الثبات على المقاصد.</li><li>⚠️ تصور أن الثبات موهبة لا تُكتسب؛ والصواب أنه يُبنى بالعلم والصحبة والدعاء والتدريب.</li><li>⚠️ نسبة أحداث السيرة بلا تحقيق؛ فبعض ما يُروى في كتب السيرة يحتاج تمييزا بين الصحيح والمرسل، والواجب العزو الدقيق.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف الثبات وبيّن فرقه عن العناد.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر أربع صور من أذى قريش للنبي صلى الله عليه وسلم وأصحابه.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>كم دام الحصار في شعب أبي طالب؟ ومن استُهدف به؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>من الصحابي الذي قال: «ألا تستنصر لنا؟» وأين أُخرج الحديث؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>أتمم: «فَاصْبِرْ كَمَا صَبَرَ ...» مع ذكر السورة والآية.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>اذكر أربعة مقومات للثبات واشرح اثنين منها.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>بيّن أثر الرفقة الصالحة في الثبات، بمثال من السيرة ومثال من واقعك.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>ما الحكمة من ذكر قصص السابقين في حديث خبّاب؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>كيف نجمع بين الثبات على المبادئ والمرونة في الوسائل؟ مثّل من السيرة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>استخرج من موقف الطائف قيمتين وطبّقهما على وضعية مدرسية.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: يضغط عليك زملاؤك للمشاركة في تصوير أستاذ ونشره. اكتب تسعة أسطر تبيّن موقفك وطريقة رفضك بأدب، مقتديا بثبات النبي صلى الله عليه وسلم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل العبارة: «الثبات مهارة تُكتسب لا صفة تُوهب».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>قارن في جدول بين الثابت والمتردد من حيث: الدافع، ردّ الفعل أمام السخرية، النتيجة، وأثره على المجموعة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ستة أسطر عن ثبات التلميذ المغربي في المناطق النائية على طلب العلم، وبيّن دور الأسرة والمؤسسة في دعمه.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"الثبات","v":"لزوم الحق والصبر على المشاق دون تراجع"},{"r":"العناد","v":"التمسك بالرأي بعد ظهور خطئه"},{"r":"الحصار (شعب أبي طالب)","v":"مقاطعة قريش لبني هاشم نحو ثلاث سنوات"},{"r":"يوم العقبة","v":"يوم الطائف الذي لقي فيه النبي أشد الأذى"},{"r":"أولو العزم","v":"الرسل أصحاب الصبر العظيم"},{"r":"ضغط المجموعة","v":"تأثير الجماعة على الفرد لدفعه إلى سلوك ما"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — عرّف الثبات، واذكر ثلاث صور من أذى قريش، وثلاثة مقومات للثبات.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — اذكر موقفين من مواقف ثبات النبي صلى الله عليه وسلم مع الاستشهاد والعزو لأحدهما.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: يقترح عليك أصدقاؤك التغيب الجماعي عن حصة لتأجيل فرض. حرّر عشرة أسطر تبيّن موقفك ومبرراته، وأسلوب الرفض المهذب، وأثر الثبات في مثل هذه المواقف.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 2 ن، صور الأذى 2 ن، المقومات 2 ن.</li><li>التمرين الثاني: كل موقف 2 ن، الاستشهاد مع العزو 2 ن (مثال: حديث خبّاب، البخاري 3612).</li><li>التمرين الثالث: الموقف الواضح 2 ن، المبررات الشرعية والتربوية 3 ن، أسلوب الرفض 2 ن، اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei10","domaine":"islamique","unite":10,"theme":"الوحدة الثانية","tag":"EI10","langue":"ar","titre":"مدخل الاستجابة 2: الطهارة (أنواعها ومقاصدها)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) الطهارة لغة واصطلاحا.","أن يميّز بين الطهارة المائية والترابية وبين طهارة الحدث وطهارة الخبث.","أن يذكر فرائض الوضوء وسننه على المشهور من المذهب المالكي.","أن يبيّن أحكام الغسل والتيمم وحالات المصير إليه.","أن يستخلص مقاصد الطهارة الصحية والتربوية والاجتماعية."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: في رحلة مدرسية إلى منطقة جبلية، انقطع الماء عن المخيم قبل صلاة العصر. اقترح تلميذ تأخير الصلاة إلى العودة، وقال آخر: نتيمم ونصلي في وقتها. من المصيب؟ ولماذا؟</p>\n<p><strong>تعريف الطهارة</strong>: <strong>لغة</strong> النظافة والنقاء من الأوساخ والأقذار. و<strong>اصطلاحا</strong>:</p>\n<blockquote><p><strong>الطهارة</strong>: صفة حكمية أو رفع لما يمنع من الصلاة، وتكون بإزالة النجاسة عن البدن أو الثوب أو المكان (<strong>طهارة الخبث</strong>)، أو برفع الحدث بالوضوء أو الغسل أو التيمم (<strong>طهارة الحدث</strong>).</p></blockquote>\n<p><strong>أنواع الطهارة</strong>:</p>\n<ol><li><strong>الطهارة المائية</strong>: بالماء الطهور، وهي الأصل، قال تعالى: «وَأَنْزَلْنَا مِنَ السَّمَاءِ مَاءً طَهُورًا» (سورة الفرقان، الآية 48). وتشمل: <strong>الوضوء</strong> لرفع الحدث الأصغر، و<strong>الغسل</strong> لرفع الحدث الأكبر.</li><li><strong>الطهارة الترابية (التيمم)</strong>: بديل عند تعذر الماء أو تعذر استعماله، قال تعالى: «فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا» (سورة النساء، الآية 43).</li></ol>\n<p><strong>فرائض الوضوء عند المالكية</strong> سبع: <strong>النية</strong>، وغسل الوجه، وغسل اليدين إلى المرفقين، ومسح جميع الرأس، وغسل الرجلين إلى الكعبين، و<strong>الدلك</strong>، و<strong>الفور</strong> (الموالاة). وسننه ثمان منها: غسل اليدين إلى الكوعين قبل الشروع، والمضمضة، والاستنشاق والاستنثار، ومسح الأذنين، وردّ مسح الرأس، وترتيب الفرائض. وفضائله: التسمية، والتيامن، والسواك، والاقتصاد في الماء.</p>\n<blockquote><p><strong>قاعدة مالكية مهمة</strong>: الدلك والفور من فرائض الوضوء عند المالكية، بخلاف بعض المذاهب الأخرى التي تعدّهما سنة؛ وترك الفريضة عمدا يوجب الإعادة، وترك السنة ينقص الأجر ولا يُبطل.</p></blockquote>\n<p><strong>نواقض الوضوء</strong>: خروج الخارج المعتاد من السبيلين (البول، الغائط، الريح)، وزوال العقل بنوم ثقيل أو إغماء أو سكر، والردة، وملامسة تُقصد بها اللذة على تفصيل عند المالكية.</p>\n<p><strong>الغسل</strong>: يجب من الجنابة، ومن الحيض والنفاس. وفرائضه: النية، وتعميم الجسد بالماء، والدلك، وتخليل الشعر. وسننه: البدء بغسل اليدين، والمضمضة والاستنشاق، ومسح الأذنين. ويُسنّ الغسل لصلاة الجمعة والعيدين وللإحرام.</p>\n<p><strong>التيمم</strong>: شروط المصير إليه: <strong>فقد الماء</strong> أو عدم القدرة على استعماله (مرض، برد شديد يُخشى منه ضرر، خوف نفاد الماء اللازم للشرب). وصفته: النية، ثم ضرب اليدين على صعيد طاهر، ومسح الوجه، ثم مسح اليدين إلى الكوعين (وإلى المرفقين على وجه مستحسن عند المالكية في بعض الصور). ويكون بالتراب أو ما اتصل بالأرض من رمل وحجر.</p>\n<p><strong>نشاط تطبيقي</strong>: يُنجز المتعلمون جدولا ثلاثيا: (فرض / سنة / مبطل) لكل من الوضوء والغسل، وتُعرض النتائج للمقارنة.</p>\n<p><strong>مقاصد الطهارة</strong>:</p>\n<ul><li><strong>تعبدية</strong>: شرط لصحة الصلاة والطواف، قال صلى الله عليه وسلم: «لا تُقبل صلاة بغير طهور» (أخرجه مسلم في صحيحه، كتاب الطهارة، حديث رقم 224 بمعناه).</li><li><strong>صحية</strong>: الوقاية من الأمراض والعدوى، وتنظيف الجسم مرات في اليوم.</li><li><strong>تربوية ونفسية</strong>: انتظام في الوقت، وطهارة الظاهر تُعين على طهارة الباطن، وقد قال صلى الله عليه وسلم: «الطهور شطر الإيمان» (أخرجه مسلم، كتاب الطهارة، حديث رقم 223 من حديث أبي مالك الأشعري).</li><li><strong>اجتماعية</strong>: حسن المظهر واحترام الجالس إليك في القسم والمسجد.</li><li><strong>بيئية</strong>: الاقتصاد في الماء واجب شرعي وسلوك مواطن، وهو أمر ملحّ في المغرب في سياق الإجهاد المائي وسنوات الجفاف؛ فالوضوء المقتصد ماء أقل بكثير ولا ينقص الأجر.</li></ul>\n<p><strong>مثال محلول 1</strong>: تلميذ توضأ ونسي مسح رأسه. الجواب: مسح جميع الرأس فريضة عند المالكية، فوضوءه غير صحيح ويلزمه إعادة ما ترك مع مراعاة الفور، فإن طال الزمن أعاد الوضوء.</p>\n<p><strong>مثال محلول 2</strong>: مسافر في الصحراء لا يجد ماء. الجواب: يتيمم بصعيد طاهر ويصلي في الوقت، ولا يؤخر الصلاة؛ لأن الوقت مقدّم، والتيمم رفع للحرج.</p>\n<p><strong>مثال محلول 3</strong>: من انتقض وضوءه بعد الوضوء بريح. الجواب: يعيد الوضوء لأن الريح من نواقض الوضوء.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>طهارة الحدث</td><td>رفع المانع من الصلاة بالوضوء أو الغسل أو التيمم</td></tr><tr><td>طهارة الخبث</td><td>إزالة النجاسة عن البدن أو الثوب أو المكان</td></tr><tr><td>الحدث الأصغر</td><td>ما يوجب الوضوء</td></tr><tr><td>الحدث الأكبر</td><td>ما يوجب الغسل</td></tr><tr><td>الدلك</td><td>إمرار اليد على العضو مع الماء، وهو فريضة عند المالكية</td></tr><tr><td>الفور</td><td>الموالاة بين أعضاء الوضوء بلا تفريق طويل</td></tr><tr><td>الصعيد الطيب</td><td>التراب الطاهر وما اتصل بالأرض</td></tr><tr><td>الماء الطهور</td><td>الطاهر في نفسه المطهّر لغيره</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الإسراف في ماء الوضوء ظنّا أن كثرة الماء تزيد الأجر؛ والصواب أن الاقتصاد سنة وحفظ الماء أمانة.</li><li>⚠️ الاقتصار على مسح بعض الرأس؛ والمشهور عند المالكية وجوب مسح <strong>جميع</strong> الرأس.</li><li>⚠️ الظن أن التيمم يجوز مع وجود الماء لمجرد المشقة الخفيفة؛ والصواب أنه رخصة بشروط: فقد الماء أو تعذر استعماله لعذر معتبر.</li><li>⚠️ الخلط بين ما يوجب الوضوء وما يوجب الغسل؛ فالنوم الثقيل ينقض الوضوء ولا يوجب الغسل.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف الطهارة لغة واصطلاحا.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر فرائض الوضوء عند المالكية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر أربع سنن من سنن الوضوء.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>أتمم: «فَلَمْ تَجِدُوا مَاءً ...» مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>ما نواقض الوضوء؟ اذكر ثلاثة.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>قارن في جدول بين الطهارة المائية والترابية من حيث: الحكم، الوسيلة، شرط المصير إليها.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>بيّن الفرق بين ما يوجب الوضوء وما يوجب الغسل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>اذكر خمسة من مقاصد الطهارة مع مثال لكل مقصد.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>ما حكم من ترك الدلك في الوضوء عند المالكية؟ علّل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>استدل بحديثين على منزلة الطهارة مع العزو.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: في مخيم مدرسي انقطع الماء ولم يبق إلا قليل يكفي للشرب. بيّن الحكم الشرعي وكيفية أداء الصلاة مع التعليل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف يكون ترشيد ماء الوضوء عبادة ومواطنة في الوقت نفسه؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز جدولا ثلاثيا (فرض / سنة / مبطل) للوضوء والغسل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ستة أسطر تبيّن العلاقة بين طهارة البدن وطهارة القلب.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"طهارة الحدث","v":"رفع المانع من الصلاة بالوضوء أو الغسل أو التيمم"},{"r":"طهارة الخبث","v":"إزالة النجاسة عن البدن أو الثوب أو المكان"},{"r":"الحدث الأصغر","v":"ما يوجب الوضوء"},{"r":"الحدث الأكبر","v":"ما يوجب الغسل"},{"r":"الدلك","v":"إمرار اليد على العضو مع الماء، وهو فريضة عند المالكية"},{"r":"الفور","v":"الموالاة بين أعضاء الوضوء بلا تفريق طويل"},{"r":"الصعيد الطيب","v":"التراب الطاهر وما اتصل بالأرض"},{"r":"الماء الطهور","v":"الطاهر في نفسه المطهّر لغيره"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — 1) عرّف الطهارة اصطلاحا. 2) اذكر فرائض الوضوء عند المالكية. 3) اذكر شرطين للمصير إلى التيمم.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — أتمم الآية «فَلَمْ تَجِدُوا مَاءً ...» والحديث «الطهور ...» مع العزو، وبيّن وجه الاستدلال بكل نص.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: لاحظت في مرافق المؤسسة إسرافا في ماء الوضوء وصنابير مفتوحة. اكتب ثمانية أسطر تحرّر فيها مقترحا لنادي البيئة يربط بين الحكم الشرعي والسلوك المدني.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 2 ن، الفرائض 3,5 ن (0,5 لكل فريضة)، شرطا التيمم 1,5 ن.</li><li>التمرين الثاني: النصان 3 ن مع العزو، وجه الاستدلال 3 ن.</li><li>التمرين الثالث: تشخيص الظاهرة 1,5 ن، الحكم الشرعي في الإسراف مع دليل 2,5 ن، مقترحات عملية (إصلاح الصنابير، ملصقات توعية، تكليف مراقبين) 2 ن، اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei11","domaine":"islamique","unite":11,"theme":"الوحدة الثانية","tag":"EI11","langue":"ar","titre":"مدخل القسط 2: حق النفس (الحفظ والرعاية)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) حق النفس ويبيّن منزلته بين الحقوق.","أن يحدد مجالات رعاية النفس: البدن، العقل، الدين، الوقت، المشاعر.","أن يستدل على حرمة الاعتداء على النفس بنصوص مع العزو.","أن يبيّن مخاطر التدخين والمخدرات والسلوكات الخطرة.","أن يضع برنامجا شخصيا لرعاية نفسه بدنيا وعقليا وروحيا."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: تلميذ ينام متأخرا أمام الهاتف، يستيقظ متعبا، لا يفطر، يعوّض ذلك بالمنبهات، ويقول: «جسدي ملكي وأنا حرّ». هل الحرية بهذا المعنى؟ وما حق نفسه عليه؟</p>\n<p><strong>مفهوم حق النفس</strong>:</p>\n<blockquote><p><strong>حق النفس</strong>: ما أوجبه الشرع على الإنسان تجاه ذاته من حفظ ورعاية وتنمية، بحيث لا يعتدي عليها بإهمال أو إفراط، ولا يعرّضها لما يُهلكها أو يُنقص كرامتها.</p></blockquote>\n<p>والنفس أمانة من الله، وليست ملكا مطلقا لصاحبها؛ ولذلك حرّم الشرع الاعتداء عليها، قال الله تعالى: «وَلَا تَقْتُلُوا أَنْفُسَكُمْ ۚ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا» (سورة النساء، الآية 29)، وقال: «وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ» (سورة البقرة، الآية 195)، وقال النبي صلى الله عليه وسلم: «لا ضرر ولا ضرار» (أخرجه ابن ماجه في سننه، كتاب الأحكام، حديث رقم 2341، ومالك في الموطأ، وهو حديث حسن بمجموع طرقه).</p>\n<p><strong>مجالات رعاية النفس</strong>:</p>\n<ol><li><strong>حفظ الدين</strong>: بالصلاة والذكر والعلم النافع، فالنفس تحتاج غذاء روحيا كما تحتاج غذاء ماديا.</li><li><strong>حفظ البدن</strong>: بالتغذية المتوازنة، والنوم الكافي (8-9 ساعات في هذه السن)، والرياضة، والنظافة، والتطبيب عند المرض، وقد قال النبي صلى الله عليه وسلم: «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وفي كل خير» (أخرجه مسلم، كتاب القدر، حديث رقم 2664).</li><li><strong>حفظ العقل</strong>: بطلب العلم، وتجنّب كل مُذهب للعقل من خمر ومخدرات، وبتنقية ما يُستهلك من محتوى.</li><li><strong>حفظ الوقت</strong>: بتنظيم اليوم بين الدراسة والراحة والأسرة، فالوقت هو عمر الإنسان.</li><li><strong>حفظ المشاعر والكرامة</strong>: بعدم احتقار الذات، وطلب المساعدة عند الضيق النفسي من الأسرة أو مستشار الحياة المدرسية، ورفض التنمّر.</li></ol>\n<p><strong>السلوكات المهددة للنفس</strong>: التدخين والشيشة، والمخدرات والأقراص المهلوسة، والسرعة على الدراجات دون خوذة، والسهر المفرط وإدمان الشاشات، والعزلة، والحميات القاسية أو الأكل غير المتوازن. وقد نظّم المغرب برامج وطنية للوقاية من الإدمان، ومنع التدخين في الفضاءات العمومية والمؤسسات التعليمية، والمؤسسة التعليمية شريك في هذه الوقاية عبر النوادي الصحية والخلايا الاجتماعية.</p>\n<p><strong>قاعدة فقهية مؤطرة</strong>: «الضرر يُزال»، و«لا ضرر ولا ضرار»، و«ما أدى إلى محرّم فهو محرّم»؛ وعلى هذا يُبنى القول بأن كل ما ثبت ضرره على البدن أو العقل يُمنع، وإن لم يكن منصوصا عليه باسمه.</p>\n<p><strong>مثال محلول 1</strong>: تلميذ يدخّن ويقول: «سيجارة واحدة لا تضر». الجواب: ثبوت ضرر التبغ قطعي، والقليل مدخل للكثير، والقاعدة أن ما أدى إلى الضرر ممنوع؛ فالتدخين إضرار بالنفس وبالمحيط (التدخين السلبي) وإتلاف للمال.</p>\n<p><strong>مثال محلول 2</strong>: تلميذة تترك الفطور خوفا من الوزن. الجواب: رعاية الجسم لا تعني إيذاءه؛ والصواب استشارة مختص واعتماد تغذية متوازنة، فالجسم أمانة، والتفريط في الغذاء يضعف التركيز والدراسة.</p>\n<p><strong>مثال محلول 3</strong>: من يسهر إلى الفجر على الشاشات. الجواب: تفريط في حق النفس في النوم وفي حق العقل في التركيز، ويؤدي إلى تفويت الصلاة والدراسة؛ والحل تنظيم الوقت وإبعاد الهاتف عن الفراش.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>حق النفس</td><td>ما يجب على الإنسان تجاه ذاته من حفظ وتنمية</td></tr><tr><td>الأمانة</td><td>ما استُحفظ الإنسان عليه ويُسأل عنه</td></tr><tr><td>التهلكة</td><td>الهلاك والوقوع في الضرر البالغ</td></tr><tr><td>الضرار</td><td>إيقاع الضرر بقصد المقابلة أو العدوان</td></tr><tr><td>الإدمان</td><td>تعلّق قهري بمادة أو سلوك يصعب تركه</td></tr><tr><td>التوازن</td><td>إعطاء كل جانب من جوانب النفس حقه بلا إفراط</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ فهم الحرية على أنها فعل ما يضر؛ والصواب أن الحرية مسؤولة، والنفس أمانة لا ملك مطلق.</li><li>⚠️ إهمال الجانب الروحي والاقتصار على الجسد أو العكس؛ والصواب التوازن بين الدين والبدن والعقل.</li><li>⚠️ اعتبار طلب المساعدة النفسية ضعفا؛ والصواب أنه من رعاية النفس وحفظها.</li><li>⚠️ الاستهانة بالسلوكات الصغيرة الضارة (سيجارة، سهر، إهمال وجبة)؛ والصواب أن العادات تُبنى بالتكرار.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف حق النفس.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>أتمم: «وَلَا تُلْقُوا بِأَيْدِيكُمْ ...» مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر مجالات رعاية النفس الخمسة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر أربعة سلوكات مهددة للنفس.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>اذكر قاعدة فقهية تدل على منع كل ما فيه ضرر.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>بيّن كيف تكون الصلاة رعاية للنفس لا تكليفا عليها.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>علّل: النفس أمانة لا ملك مطلق. اذكر دليلين.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>اذكر ثلاثة أضرار للتدخين: على المدخّن، وعلى محيطه، وعلى المال.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>كيف يكون تنظيم الوقت أداء لحق النفس؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>استدل بحديث على فضل القوة البدنية للمؤمن مع العزو.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: عُرضت عليك سيجارة في محيط المؤسسة مع سخرية من رفضك. حرّر تسعة أسطر تبيّن فيها موقفك وحجتك الشرعية والصحية وطريقة الرفض.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل العبارة: «الحرية المسؤولة تحمي النفس، والحرية بلا ضابط تُهلكها».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز برنامجا يوميا (من الاستيقاظ إلى النوم) يوازن بين الدين والدراسة والبدن والأسرة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ستة أسطر عن دور المؤسسة التعليمية والأسرة في الوقاية من الإدمان.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"حق النفس","v":"ما يجب على الإنسان تجاه ذاته من حفظ وتنمية"},{"r":"الأمانة","v":"ما استُحفظ الإنسان عليه ويُسأل عنه"},{"r":"التهلكة","v":"الهلاك والوقوع في الضرر البالغ"},{"r":"الضرار","v":"إيقاع الضرر بقصد المقابلة أو العدوان"},{"r":"الإدمان","v":"تعلّق قهري بمادة أو سلوك يصعب تركه"},{"r":"التوازن","v":"إعطاء كل جانب من جوانب النفس حقه بلا إفراط"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — عرّف حق النفس، واذكر مجالات رعايتها، وقاعدة فقهية دالة على منع الضرر.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — أتمم الآيتين: «وَلَا تَقْتُلُوا ...» و«وَلَا تُلْقُوا ...» مع العزو، وبيّن ما يُستفاد منهما في موضوع الدرس.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: كُلّفت بإعداد ورقة توعوية لنادي الصحة بمؤسستك حول مخاطر السهر وإدمان الشاشات. حرّر عشرة أسطر تضمّنها التشخيص والأدلة والحلول.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 2 ن، المجالات 2,5 ن، القاعدة 1,5 ن.</li><li>التمرين الثاني: الآيتان 3 ن مع العزو، الاستفادة 3 ن.</li><li>التمرين الثالث: التشخيص 2 ن، الأدلة الشرعية 2 ن، الحلول العملية 3 ن، اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei12","domaine":"islamique","unite":12,"theme":"الوحدة الثانية","tag":"EI12","langue":"ar","titre":"مدخل الحكمة 2: التعامل الإيجابي مع وسائل الاتصال الحديثة","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعدّد المتعلم(ة) وسائل الاتصال الحديثة ومنافعها.","أن يميّز بين الاستعمال الإيجابي والاستعمال السلبي لهذه الوسائل.","أن يستدل على ضوابط الكلمة والخبر بنصوص شرعية مع العزو.","أن يحدد مخاطر الاستعمال السيئ: التشهير، الغيبة، الأخبار الزائفة، التنمر الرقمي، إهمال الدراسة.","أن يصوغ ميثاقا صفّيا للاستعمال الرشيد للهاتف والشبكات."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: انتشر في مجموعة القسم خبر عن إلغاء الفرض، فصدّقه أغلب التلاميذ ولم يراجعوا، ثم تبيّن أن الخبر غير صحيح. من المسؤول؟ وما الضابط الشرعي في نقل الأخبار؟</p>\n<p><strong>وسائل الاتصال الحديثة ومنافعها</strong>: الهاتف الذكي، والإنترنت، وتطبيقات المراسلة، والشبكات الاجتماعية، ومنصات الفيديو والتعلم. ومنافعها: صلة الرحم والتواصل مع الأقارب في المهجر، والتعلم عن بعد (منصات وزارة التربية الوطنية مثل TelmidTICE)، وتصريف الأعمال الإدارية، ونشر الخير والتوعية، والتعريف بالتراث المغربي، والمشاركة في المبادرات التضامنية.</p>\n<p><strong>الضوابط الشرعية للكلمة والخبر</strong>:</p>\n<blockquote><p><strong>قاعدة أولى — مسؤولية الكلمة</strong>: «مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ» (سورة ق، الآية 18)، وقال النبي صلى الله عليه وسلم: «من كان يؤمن بالله واليوم الآخر فليقل خيرا أو ليصمت» (أخرجه البخاري، كتاب الأدب، حديث رقم 6018، ومسلم، كتاب الإيمان، حديث رقم 47 بنحوه).</p></blockquote>\n<blockquote><p><strong>قاعدة ثانية — التثبت قبل النشر</strong>: «يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا» (سورة الحجرات، الآية 6)، وقال تعالى: «وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ» (سورة الإسراء، الآية 36).</p></blockquote>\n<blockquote><p><strong>قاعدة ثالثة — حفظ حرمة المسلم</strong>: «الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ» (أخرجه البخاري، كتاب الإيمان، حديث رقم 10)، ومنع الغيبة والسخرية والتجسس: «وَلَا تَجَسَّسُوا وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا» (سورة الحجرات، الآية 12).</p></blockquote>\n<p><strong>مظاهر الاستعمال السلبي</strong>: نشر الأخبار الزائفة، والتشهير وتصوير الناس بلا إذن، والتنمر الرقمي، والغيبة في المجموعات المغلقة، ومشاهدة المحتوى الضار، وإضاعة الوقت وإهمال الدراسة، وإدمان الشاشات والسهر، والتحايل والنصب، وسرقة أعمال الآخرين بلا توثيق. وهذه المظاهر يعاقب على بعضها القانون المغربي أيضا، خصوصا ما يتعلق بالتشهير والاعتداء على المعطيات الشخصية.</p>\n<p><strong>مبادئ الاستعمال الإيجابي</strong>: <strong>النية</strong> (لماذا أفتح الهاتف الآن؟)، و<strong>التثبت</strong> (هل الخبر موثوق؟ ما مصدره؟)، و<strong>الاحترام</strong> (هل يقبل صاحبه أن يُنشر عنه هذا؟)، و<strong>تدبير الوقت</strong> (حدّ زمني يومي، وإبعاد الهاتف وقت المراجعة والنوم)، و<strong>النافع</strong> (متابعة محتوى تعليمي وعلمي)، و<strong>الخصوصية</strong> (عدم نشر معطيات شخصية أو صور الأسرة).</p>\n<p><strong>نشاط الاكتشاف</strong>: تُوزّع على المجموعات أربع حالات (خبر زائف، صورة تلميذ نُشرت بلا إذن، تعليق ساخر، مجموعة مراجعة منظمة)، ويُطلب تصنيفها وتحديد الضابط الشرعي والحل العملي لكل حالة.</p>\n<p><strong>مثال محلول 1</strong>: تلميذ أعاد نشر خبر عن إلغاء الدراسة بلا مصدر. الجواب: أخطأ لأنه لم يتبين، والآية أمرت بالتبين؛ والصواب التحقق من الموقع الرسمي أو الإدارة قبل النشر، والاعتذار وتصحيح الخبر.</p>\n<p><strong>مثال محلول 2</strong>: صوّر تلميذ زميله وهو نائم في الحصة ونشر الصورة للتضحيك. الجواب: هذا اعتداء على حرمة الزميل وقد يُدخل في السخرية المحرّمة، ويوجب حذف الصورة والاعتذار وطلب العفو؛ ولا عذر بأن القصد المزاح.</p>\n<p><strong>مثال محلول 3</strong>: مجموعة قسم لتبادل التمارين وتذكير بالمواعيد. الجواب: هذا استعمال إيجابي، ويُستحسن ضبطه بميثاق: أوقات، ومنع الرسائل الجارحة، ومنع الرسائل ليلا، وتعيين مشرف من التلاميذ.</p>\n<p><strong>السياق المغربي وقيم المواطنة</strong>: تُشجّع منظومة التربية على استعمال الرقميات في التعلم، كما تُذكّر بمسؤولية النشر. والمساجد والمجالس العلمية تنشر دروسا موثوقة على المنصات، وهذا نموذج للاستعمال النافع؛ في مقابل ذلك، الفتوى الفردية والمحتوى الديني غير الموثوق على الشبكات مصدر تشويش، والصواب الرجوع إلى المصادر المعتمدة وأهل العلم.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>وسائل الاتصال الحديثة</td><td>الأدوات الرقمية التي تنقل الأخبار والصور والأصوات بسرعة</td></tr><tr><td>التثبت</td><td>التحقق من صحة الخبر قبل قبوله أو نشره</td></tr><tr><td>الخبر الزائف</td><td>خبر مُختلق أو محرّف يُنشر بقصد أو بغفلة</td></tr><tr><td>التنمر الرقمي</td><td>إيذاء متكرر لشخص عبر الوسائل الرقمية</td></tr><tr><td>التشهير</td><td>فضح شخص ونشر ما يسيء إليه بين الناس</td></tr><tr><td>الخصوصية</td><td>حق الإنسان في ألا تُنشر معطياته وصوره بلا إذن</td></tr><tr><td>الاستعمال الرشيد</td><td>استعمال منظم بنية صالحة وضوابط زمنية وأخلاقية</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ اعتبار الوسائل شرّا في ذاتها؛ والصواب أنها أدوات، والحكم يتبع الاستعمال.</li><li>⚠️ الظن أن الغيبة في مجموعة مغلقة لا حكم لها؛ والصواب أنها غيبة وقد تكون أشدّ لسرعة انتشارها.</li><li>⚠️ الاحتجاج بأن «الكل ينشر» لتبرير نشر خبر مشكوك فيه؛ والصواب أن كثرة الناشرين ليست دليل صحة.</li><li>⚠️ الاقتصار على المنع بلا بديل؛ والصواب تربية على الاستعمال النافع وتنظيم الوقت.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>اذكر أربع وسائل من وسائل الاتصال الحديثة وأربع منافع لها.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>أتمم: «إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَإٍ ...» مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>أتمم الحديث: «من كان يؤمن بالله واليوم الآخر ...» مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>عرّف: الخبر الزائف، التنمر الرقمي، التشهير.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>اذكر أربعة مظاهر للاستعمال السلبي.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>صنّف الحالات الآتية إلى إيجابي وسلبي مع التعليل: متابعة درس على منصة تعليمية / نشر صورة زميل للتضحيك / مجموعة لتنظيم المراجعة / إعادة نشر خبر بلا مصدر.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>بيّن كيف تكون الغيبة في مجموعة مغلقة أشد أثرا من الغيبة في مجلس.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>اذكر ثلاثة مبادئ للاستعمال الرشيد واشرح واحدا منها.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>كيف تتحقق من صحة خبر تربوي يخص مؤسستك؟ اذكر ثلاث خطوات.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>ما أثر إدمان الشاشات على الدراسة والصحة؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: وصلك مقطع يسخر من تلميذ ذي احتياج خاص. حرّر عشرة أسطر تبيّن الحكم الشرعي، وواجبك، والخطوات العملية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: «الوسيلة محايدة، والقيمة في المستعمل».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>صُغ ميثاقا صفيا من ثمانية بنود لاستعمال الهاتف والمجموعات.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب سبعة أسطر عن كيفية استعمال الشبكات للتعريف بالتراث المغربي وخدمة قيم المواطنة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"وسائل الاتصال الحديثة","v":"الأدوات الرقمية التي تنقل الأخبار والصور والأصوات بسرعة"},{"r":"التثبت","v":"التحقق من صحة الخبر قبل قبوله أو نشره"},{"r":"الخبر الزائف","v":"خبر مُختلق أو محرّف يُنشر بقصد أو بغفلة"},{"r":"التنمر الرقمي","v":"إيذاء متكرر لشخص عبر الوسائل الرقمية"},{"r":"التشهير","v":"فضح شخص ونشر ما يسيء إليه بين الناس"},{"r":"الخصوصية","v":"حق الإنسان في ألا تُنشر معطياته وصوره بلا إذن"},{"r":"الاستعمال الرشيد","v":"استعمال منظم بنية صالحة وضوابط زمنية وأخلاقية"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — اذكر ثلاث قواعد شرعية في التعامل مع الأخبار والكلمة، مع نص واحد لكل قاعدة والعزو.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — صنّف أربع حالات (تُعطى في ورقة الفرض) إلى استعمال إيجابي وسلبي مع التعليل.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: انتشر في مجموعة المستوى خبر زائف عن تأجيل الامتحانات فتوقف كثير من التلاميذ عن المراجعة. حرّر عشرة أسطر تبيّن المسؤولية الشرعية والأخلاقية، وتقترح إجراءات لمنع تكرار ذلك.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: كل قاعدة مع نصها وعزوها 2 ن.</li><li>التمرين الثاني: 1,5 ن لكل حالة مصنفة ومعلّلة.</li><li>التمرين الثالث: بيان المسؤولية 3 ن، الاستشهاد مع العزو 2 ن، الإجراءات العملية 2 ن، اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei13","domaine":"islamique","unite":13,"theme":"الوحدة الثانية","tag":"EI13","langue":"ar","titre":"مدخل التزكية (القرآن الكريم) 3: الشطر الثالث من سورة ق (الآية 38 إلى 45)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يرتّل المتعلم(ة) الآيات 38-45 من سورة ق ترتيلا سليما ويحفظها.","أن يشرح مفردات المقطع.","أن يستخرج مضامينه: خلق السماوات والأرض، الأمر بالصبر والتسبيح، مشهد الخروج، مهمة النبي في التذكير.","أن يتعرّف أحكام المدود (الجائز والواجب) ويطبقها.","أن يستثمر مضامين المقطع في الصبر على الطاعة والمراجعة."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: تلميذ يشتكي: «أراجع ولا أرى نتيجة، وأنصح صديقي فلا يستجيب، فسأتوقف». المقطع الأخير من سورة ق يعطي جوابا في كلمتين: «فَاصْبِرْ» و«سَبِّحْ».</p>\n<p><strong>نص المقطع كاملا (38-45)</strong>:</p>\n<blockquote><p>«وَلَقَدْ خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِنْ لُغُوبٍ (38) فَاصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ (39) وَمِنَ اللَّيْلِ فَسَبِّحْهُ وَأَدْبَارَ السُّجُودِ (40) وَاسْتَمِعْ يَوْمَ يُنَادِ الْمُنَادِ مِنْ مَكَانٍ قَرِيبٍ (41) يَوْمَ يَسْمَعُونَ الصَّيْحَةَ بِالْحَقِّ ۚ ذَٰلِكَ يَوْمُ الْخُرُوجِ (42) إِنَّا نَحْنُ نُحْيِي وَنُمِيتُ وَإِلَيْنَا الْمَصِيرُ (43) يَوْمَ تَشَقَّقُ الْأَرْضُ عَنْهُمْ سِرَاعًا ۚ ذَٰلِكَ حَشْرٌ عَلَيْنَا يَسِيرٌ (44) نَحْنُ أَعْلَمُ بِمَا يَقُولُونَ ۖ وَمَا أَنْتَ عَلَيْهِمْ بِجَبَّارٍ ۖ فَذَكِّرْ بِالْقُرْآنِ مَنْ يَخَافُ وَعِيدِ (45)» — سورة ق، الآيات 38-45.</p></blockquote>\n<p><strong>شرح المفردات</strong>:</p>\n<table><thead><tr><th>الكلمة</th><th>الشرح</th></tr></thead><tbody><tr><td>لغوب</td><td>تعب وإعياء</td></tr><tr><td>فاصبر</td><td>احتمل بحسن رضا واستمرار</td></tr><tr><td>سبّح بحمد ربك</td><td>نزّهه عن كل نقص مع الثناء عليه</td></tr><tr><td>أدبار السجود</td><td>أعقاب الصلوات</td></tr><tr><td>المنادِ</td><td>الملك الذي ينادي للحشر</td></tr><tr><td>الصيحة</td><td>النفخة في الصور</td></tr><tr><td>يوم الخروج</td><td>يوم القيامة حين يخرج الناس من قبورهم</td></tr><tr><td>المصير</td><td>المرجع والمآل</td></tr><tr><td>تشقّق الأرض</td><td>تتصدع وتنفتح</td></tr><tr><td>سراعا</td><td>مسرعين</td></tr><tr><td>بجبّار</td><td>بمسلّط تُكرههم على الإيمان</td></tr></tbody></table>\n<p><strong>المضامين الأساسية</strong>: يقرر المقطع أولا <strong>كمال قدرة الله</strong> بخلق السماوات والأرض بلا تعب، فيكون البعث أهون؛ ثم يُوجّه النبي صلى الله عليه وسلم إلى <strong>الصبر والتسبيح</strong> في أوقات مخصوصة (قبل طلوع الشمس، وقبل الغروب، ومن الليل، وأعقاب الصلوات)، وهذا إشعار بأن الصلاة والذكر هما زاد الثابت؛ ثم يعرض <strong>مشهد الخروج</strong>: نداء المنادي، والصيحة، وتشقق الأرض، وسرعة الحشر الذي هو على الله يسير؛ ثم يبيّن أن مهمة النبي صلى الله عليه وسلم <strong>التذكير لا الإكراه</strong>: «وَمَا أَنْتَ عَلَيْهِمْ بِجَبَّارٍ ۖ فَذَكِّرْ بِالْقُرْآنِ».</p>\n<blockquote><p><strong>قاعدة دعوية</strong>: الآية 45 أصل في أن الدعوة بالتذكير والبيان، لا بالقسر والإكراه، ولهذا تختم السورة التي بدأت بالقسم بالقرآن بالأمر بالتذكير به.</p></blockquote>\n<p><strong>القاعدة الترتيلية — المدود</strong>: المد إطالة الصوت بحرف من حروف المد (الألف، الواو، الياء). و<strong>المد الواجب</strong> هو المتصل: أن يأتي بعد حرف المد همزة في <strong>الكلمة نفسها</strong>، فيُمدّ وجوبا مقدار أربع أو خمس حركات، مثاله «جَاءَ»، «السَّمَاءِ» عند وجود الهمزة. و<strong>المد الجائز</strong> هو المنفصل: أن يأتي حرف المد في آخر كلمة والهمزة في أول الكلمة التالية، مثاله «إِنَّا نَحْنُ» ليس منه، ومثاله الصحيح «يَا أَيُّهَا»، ويُمدّ أو يُقصر حسب الرواية؛ وفي رواية ورش يُمدّ المنفصل عادة بمقدار المتصل.</p>\n<p><strong>نشاط تطبيقي</strong>: يستخرج المتعلمون من المقطع كلمات فيها مد ويصنفونها، مع تحديد مقدار المد.</p>\n<p><strong>مثال محلول 1</strong>: علاقة الآية 38 بالآية 15 من السورة. الجواب: كلتاهما حجة على القدرة: الآية 15 نفت العجز عن الخلق الأول، والآية 38 نفت التعب عن خلق السماوات والأرض؛ فالنتيجة أن البعث يسير على الله.</p>\n<p><strong>مثال محلول 2</strong>: ما الحكمة من تحديد أوقات التسبيح؟ الجواب: لأن هذه الأوقات مواطن انتقال (بداية النهار، آخره، الليل، أعقاب الصلوات) فيحتاج الإنسان فيها إلى تجديد الصلة؛ وهي تشير إلى أوقات الصلوات المفروضة.</p>\n<p><strong>مثال محلول 3</strong>: كيف نفهم «وَمَا أَنْتَ عَلَيْهِمْ بِجَبَّارٍ» مع الأمر بالدعوة؟ الجواب: الدعوة واجب البيان، والهداية بيد الله؛ فالداعية يبلّغ ولا يملك القلوب، وهذا يريحه من الإحباط ويمنعه من الإكراه.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<ul><li>خلق السماوات والأرض في ستة أيام بلا تعب دليل على كمال القدرة.</li><li>زاد الصابر: الصبر والتسبيح، وأوقاته: قبل الطلوع، قبل الغروب، من الليل، أدبار السجود.</li><li>مشاهد الخروج: نداء المنادي ← الصيحة ← تشقق الأرض ← الحشر السريع.</li><li>«إِنَّا نَحْنُ نُحْيِي وَنُمِيتُ وَإِلَيْنَا الْمَصِيرُ» خلاصة عقدية للسورة.</li><li>مهمة الرسول: التذكير بالقرآن لا الإكراه.</li><li>المدود: واجب (متصل) وجائز (منفصل)، وحروف المد ثلاثة.</li></ul>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ فهم «ستة أيام» على أيامنا المعروفة قطعا؛ والصواب أن الأيام هنا مدد يعلمها الله، والمقصود بيان الإحكام لا القياس الزمني البشري.</li><li>⚠️ الخلط بين المد المتصل والمنفصل؛ الضابط: الهمزة في الكلمة نفسها (متصل واجب) أو في الكلمة التالية (منفصل جائز).</li><li>⚠️ الاستدلال بالآية 45 على ترك الدعوة؛ والصواب أنها تنفي الإكراه لا البلاغ.</li><li>⚠️ الوقف في وسط المعنى مثل الوقف على «وَسَبِّحْ» دون إتمام «بِحَمْدِ رَبِّكَ»، وهو وقف يُفسد المعنى.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>اكتب الآيات 43-45 من سورة ق مع الشكل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اشرح: لغوب، أدبار السجود، الصيحة، سراعا، بجبّار.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر أوقات التسبيح الواردة في المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>ما حروف المد؟ وما الفرق بين المتصل والمنفصل؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>أتمم: «فَذَكِّرْ بِالْقُرْآنِ ...» مع رقم الآية.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>رتّب مشاهد يوم الخروج كما وردت في المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>بيّن وجه الاستدلال في الآية 38 على إمكان البعث.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>ما العلاقة بين الصبر والتسبيح في الآية 39؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>استخرج من المقطع ثلاث كلمات فيها مد وحدد نوعه.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>كيف تفهم قوله «وَمَا أَنْتَ عَلَيْهِمْ بِجَبَّارٍ» في سياق الدعوة اليوم؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: صديقك يريد أن يجبر أخاه الصغير على الصلاة بالضرب. حرّر ثمانية أسطر تبيّن الخطأ وتقترح بديلا تربويا مستدلا بالمقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف تكون الصلاة والذكر زادا للصبر في حياة المتعلم(ة)؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز جدولا (الآية / المضمون / القيمة) لخمس آيات من المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ستة أسطر عن العبرة من قوله تعالى «إِنَّا نَحْنُ نُحْيِي وَنُمِيتُ وَإِلَيْنَا الْمَصِيرُ».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"لغوب","v":"تعب وإعياء"},{"r":"فاصبر","v":"احتمل بحسن رضا واستمرار"},{"r":"سبّح بحمد ربك","v":"نزّهه عن كل نقص مع الثناء عليه"},{"r":"أدبار السجود","v":"أعقاب الصلوات"},{"r":"المنادِ","v":"الملك الذي ينادي للحشر"},{"r":"الصيحة","v":"النفخة في الصور"},{"r":"يوم الخروج","v":"يوم القيامة حين يخرج الناس من قبورهم"},{"r":"المصير","v":"المرجع والمآل"},{"r":"تشقّق الأرض","v":"تتصدع وتنفتح"},{"r":"سراعا","v":"مسرعين"},{"r":"بجبّار","v":"بمسلّط تُكرههم على الإيمان"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — اكتب الآيتين 39 و40 مع الشكل، واشرح: لغوب، أدبار السجود، المنادِ.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — استخرج من المقطع مضمونين، مع الاستشهاد لكل مضمون وبيان القيمة المستفادة.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: عضو في نادي القرآن يريد إلزام التلاميذ بحضور أنشطة النادي بالتهديد. حرّر ثمانية أسطر تصحح فيها المنهج بالاستدلال بالآية 45 وتقترح أساليب تحفيزية.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: الآيتان 4 ن، الشرح 3 ن.</li><li>التمرين الثاني: كل مضمون 2 ن مع استشهاده، والقيمة 2 ن.</li><li>التمرين الثالث: تصحيح المنهج بنفي الإكراه 3 ن، الاستشهاد مع العزو 2 ن، الأساليب التحفيزية (مسابقات، شهادات تقدير، أنشطة جماعية) 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>\n<p>## الوحدة الثالثة — الدروس EI14 إلى EI19</p>\n<p>تُبنى الوحدة الثالثة على المداخل الستة نفسها في دورة ثالثة: التزكية (الشطر الأول من سورة لقمان، والنظر والتفكر)، والاقتداء (صبر السابقين الأولين)، والاستجابة (أحكام الصلاة ومقاصدها)، والقسط (حق الغير)، والحكمة (التجمل بمحاسن الأخلاق). وتُستثمر مكتسبات الوحدتين السابقتين في وضعيات أعقد.</p>"}},
{"id":"islamique-ei14","domaine":"islamique","unite":14,"theme":"الوحدة الثالثة — الدروس EI14 إلى EI19","tag":"EI14","langue":"ar","titre":"مدخل التزكية (القرآن الكريم) 4: الشطر الأول من سورة لقمان (الآية 1 إلى 11)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يرتّل المتعلم(ة) الآيات 1-11 من سورة لقمان ترتيلا سليما ويحفظها.","أن يشرح مفردات المقطع شرحا صحيحا.","أن يستخرج مضامينه: صفة المحسنين، وصفة المستكبرين، وأدلة القدرة في الخلق.","أن يوازن بين موقف المهتدي وموقف المستكبر من آيات الله.","أن يستثمر المقطع في تقويم علاقته بالقرآن وبالمحتوى الذي يستمع إليه."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: في القسم تلميذان: أحدهما ينصت إلى الدرس ويعمل بما فهم، والآخر يُعرض ويُشغل نفسه بغيره. سورة لقمان تفتح بهذه المقارنة نفسها بين المحسن والمستكبر.</p>\n<p><strong>التعريف بالسورة</strong>: سورة لقمان مكية، عدد آياتها أربع وثلاثون آية، سُمّيت باسم لقمان الحكيم لما حكاه الله من وصاياه لابنه. وموضوعها الكبير: التوحيد، والحكمة، وحقوق الوالدين، والقيم الأخلاقية. وتُدرّس في الدورة الثانية بالمستوى الأولى إعدادي بالمغرب على ثلاثة أشطر (ملخصات التربية الإسلامية للأولى إعدادي).</p>\n<p><strong>نص المقطع (1-11)</strong>:</p>\n<blockquote><p>«الم (1) تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ (2) هُدًى وَرَحْمَةً لِلْمُحْسِنِينَ (3) الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُمْ بِالْآخِرَةِ هُمْ يُوقِنُونَ (4) أُولَٰئِكَ عَلَىٰ هُدًى مِنْ رَبِّهِمْ ۖ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ (5) وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا ۚ أُولَٰئِكَ لَهُمْ عَذَابٌ مُهِينٌ (6) وَإِذَا تُتْلَىٰ عَلَيْهِ آيَاتُنَا وَلَّىٰ مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ (7) إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتُ النَّعِيمِ (8) خَالِدِينَ فِيهَا ۖ وَعْدَ اللَّهِ حَقًّا ۚ وَهُوَ الْعَزِيزُ الْحَكِيمُ (9) خَلَقَ السَّمَاوَاتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ۖ وَأَلْقَىٰ فِي الْأَرْضِ رَوَاسِيَ أَنْ تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِنْ كُلِّ دَابَّةٍ ۚ وَأَنْزَلْنَا مِنَ السَّمَاءِ مَاءً فَأَنْبَتْنَا فِيهَا مِنْ كُلِّ زَوْجٍ كَرِيمٍ (10) هَٰذَا خَلْقُ اللَّهِ فَأَرُونِي مَاذَا خَلَقَ الَّذِينَ مِنْ دُونِهِ ۚ بَلِ الظَّالِمُونَ فِي ضَلَالٍ مُبِينٍ (11)» — سورة لقمان، الآيات 1-11.</p></blockquote>\n<p><strong>شرح المفردات</strong>:</p>\n<table><thead><tr><th>الكلمة</th><th>الشرح</th></tr></thead><tbody><tr><td>الكتاب الحكيم</td><td>القرآن المحكم الذي لا خلل فيه، الناطق بالحكمة</td></tr><tr><td>المحسنين</td><td>الذين يعملون الصالحات بإخلاص وإتقان</td></tr><tr><td>يوقنون</td><td>يعتقدون اعتقادا جازما لا شك فيه</td></tr><tr><td>المفلحون</td><td>الفائزون الناجون</td></tr><tr><td>لهو الحديث</td><td>كل قول باطل يُشغل عن الحق ويصرف عن ذكر الله</td></tr><tr><td>هزوا</td><td>سخرية واستهزاء</td></tr><tr><td>مهين</td><td>مُذلّ يورث الهوان</td></tr><tr><td>ولّى مستكبرا</td><td>أعرض معرضا متعاليا</td></tr><tr><td>وقرا</td><td>ثِقلا وصمما</td></tr><tr><td>عمد</td><td>أعمدة وسواري</td></tr><tr><td>رواسي</td><td>جبالا ثوابت</td></tr><tr><td>أن تميد بكم</td><td>كي لا تتحرك وتضطرب بكم</td></tr><tr><td>بثّ</td><td>نشر وفرّق</td></tr><tr><td>زوج كريم</td><td>صنف نافع حسن من النبات</td></tr></tbody></table>\n<p><strong>المضامين الأساسية</strong>:</p>\n<ol><li><strong>القرآن كتاب حكيم هدى ورحمة</strong> لمن أحسن، وليس مجرد كلام يُسمع؛ فهو هدى في العقل ورحمة في القلب.</li><li><strong>صفات المحسنين ثلاث</strong>: إقامة الصلاة، وإيتاء الزكاة، واليقين بالآخرة؛ فجمعت الصلة بالله، والصلة بالخلق، والعقيدة في الغيب. ونتيجتها: الهدى والفلاح.</li><li><strong>صفات المعرضين</strong>: اشتراء لهو الحديث، والإضلال بغير علم، والاستهزاء بالآيات، والإعراض المستكبر عند سماع القرآن، حتى كأن في أذنه وقرا. وعقوبتهم: عذاب مهين أليم.</li><li><strong>جزاء المؤمنين</strong>: جنات النعيم خالدين فيها، ووعد الله حق.</li><li><strong>أدلة القدرة في الكون</strong>: السماوات بلا عمد، والجبال الرواسي، وبثّ الدواب، وإنزال الماء، وإنبات الأزواج الكريمة. ثم التحدي: «فَأَرُونِي مَاذَا خَلَقَ الَّذِينَ مِنْ دُونِهِ».</li></ol>\n<blockquote><p><strong>قاعدة</strong>: المقطع يبني الاستدلال على التوحيد بمنهج <strong>النظر في الخلق</strong>، وهو المنهج نفسه الذي تقرره العقيدة الأشعرية المعتمدة بالمغرب: الاستدلال بالمخلوق على الخالق، وبالأثر على المؤثر.</p></blockquote>\n<p><strong>تنبيه في تفسير «لهو الحديث»</strong>: عبّر أهل التفسير عن لهو الحديث بكل ما يصرف عن الحق من قول باطل، وذكر بعضهم أمثلة من زمنهم. والمناسب في التدريس بيان <strong>المعنى الجامع</strong> (كل قول يُشغل عن الحق ويصرف عن ذكر الله ويُستهزأ به بالدين) دون التوسع في مسائل خلافية تفصيلية أو إصدار أحكام فردية، فالمسائل الفقهية التفصيلية مرجعها أهل العلم والمؤسسات العلمية المعتمدة.</p>\n<p><strong>مثال محلول 1</strong>: لماذا قال «هُدًى وَرَحْمَةً لِلْمُحْسِنِينَ» ولم يقل للناس كافة؟ الجواب: لأن القرآن هدى للناس جميعا في أصل خطابه، لكن الانتفاع به لا يحصل إلا لمن أحسن الاستجابة؛ فتخصيص المحسنين تخصيص بالانتفاع لا بالخطاب.</p>\n<p><strong>مثال محلول 2</strong>: ما دلالة «كَأَنَّ فِي أُذُنَيْهِ وَقْرًا»؟ الجواب: تشبيه بليغ يبيّن أن الإعراض عن الحق يعطّل حاسة السمع عن أداء وظيفتها؛ فالمشكل ليس في الأذن بل في القلب المستكبر.</p>\n<p><strong>مثال محلول 3</strong>: استخرج ثلاثة أدلة كونية من الآية 10 وبيّن فائدة كل دليل للإنسان. الجواب: السماوات بلا عمد (دلالة على عظم القدرة)، والجبال الرواسي (تثبيت الأرض)، والماء والنبات (الغذاء والحياة).</p>\n<p><strong>السياق المغربي</strong>: تُقرأ سورة لقمان في المصاحف المغربية برواية ورش عن نافع، وتُسمع في المساجد وحلقات تحفيظ القرآن بالكتاتيب القرآنية، وهي من السور التي يُعتنى بها في المسابقات القرآنية الوطنية لما فيها من وصايا تربوية.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<ul><li>سورة لقمان مكية، 34 آية، مدارها: التوحيد والحكمة والقيم.</li><li>القرآن: هدى ورحمة، والانتفاع به مرتبط بالإحسان.</li><li>صفات المحسنين: إقامة الصلاة، إيتاء الزكاة، اليقين بالآخرة ← الهدى والفلاح.</li><li>صفات المعرضين: لهو الحديث، الإضلال بغير علم، الاستهزاء، الإعراض المستكبر ← عذاب مهين.</li><li>أدلة الكون: السماوات بلا عمد، الرواسي، الدواب، الماء، النبات.</li><li>«فَأَرُونِي مَاذَا خَلَقَ الَّذِينَ مِنْ دُونِهِ» تحدٍّ يُبطل الشرك.</li></ul>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ فهم «للمحسنين» على أن القرآن غير موجّه لغيرهم؛ والصواب أن التخصيص للانتفاع لا للخطاب.</li><li>⚠️ التوسع في تفسير «لهو الحديث» بأحكام تفصيلية وإصدار فتاوى فردية؛ والصواب الاقتصار على المعنى الجامع والرجوع لأهل العلم.</li><li>⚠️ الخلط بين «عمد» بمعنى الأعمدة و«عمد» في قراءات أخرى؛ والمقصود نفي الأعمدة المرئية.</li><li>⚠️ الوقف على «هُدًى» في الآية 5 وقطع «مِنْ رَبِّهِمْ»، وهو وقف يُضعف المعنى.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>اكتب الآيات 3-5 من سورة لقمان مع الشكل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اشرح: لهو الحديث، وقرا، رواسي، تميد، زوج كريم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر صفات المحسنين الثلاث كما وردت في الآية 4.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>كم عدد آيات سورة لقمان؟ وما نوعها؟ ولم سُمّيت بهذا الاسم؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>أتمم: «هَٰذَا خَلْقُ اللَّهِ ...» مع رقم الآية.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>قارن في جدول بين المحسنين والمعرضين (الصفات / الجزاء).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>استخرج من الآية 10 خمسة أدلة على قدرة الله، وبيّن فائدة كل دليل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>ما دلالة قوله «كَأَنَّ فِي أُذُنَيْهِ وَقْرًا»؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>كيف تكون الصلاة والزكاة واليقين بالآخرة منظومة واحدة لا صفات متفرقة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>استخرج من المقطع كلمتين فيهما مد وحدد نوع المد.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميل يقول: «أستمع للقرآن أحيانا لكني لا أعمل بشيء منه». حرّر ثمانية أسطر تناصحه فيها بالاستدلال بالآية 3.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف يوظف المقطع النظر في الكون دليلا على التوحيد؟ واذكر مثالين معاصرين.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز جدولا (الآية / المضمون / القيمة) لست آيات من المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن معيار اختيار ما نسمعه ونشاهده في ضوء قوله تعالى «وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"الكتاب الحكيم","v":"القرآن المحكم الذي لا خلل فيه، الناطق بالحكمة"},{"r":"المحسنين","v":"الذين يعملون الصالحات بإخلاص وإتقان"},{"r":"يوقنون","v":"يعتقدون اعتقادا جازما لا شك فيه"},{"r":"المفلحون","v":"الفائزون الناجون"},{"r":"لهو الحديث","v":"كل قول باطل يُشغل عن الحق ويصرف عن ذكر الله"},{"r":"هزوا","v":"سخرية واستهزاء"},{"r":"مهين","v":"مُذلّ يورث الهوان"},{"r":"ولّى مستكبرا","v":"أعرض معرضا متعاليا"},{"r":"وقرا","v":"ثِقلا وصمما"},{"r":"عمد","v":"أعمدة وسواري"},{"r":"رواسي","v":"جبالا ثوابت"},{"r":"أن تميد بكم","v":"كي لا تتحرك وتضطرب بكم"},{"r":"بثّ","v":"نشر وفرّق"},{"r":"زوج كريم","v":"صنف نافع حسن من النبات"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — اكتب الآية 10 مع الشكل، واشرح: رواسي، تميد، زوج كريم، وقرا.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — أنجز جدول مقارنة بين المحسنين والمعرضين في المقطع (الصفات والجزاء) مع استشهاد واحد لكل طرف.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: ينشغل بعض تلاميذ قسمك بمحتوى يسخر من التعاليم الدينية. حرّر عشرة أسطر تبيّن الحكم في ضوء الآيتين 6 و7، وتقترح بديلا عمليا داخل المؤسسة.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: الآية 4 ن، الشرح 3 ن.</li><li>التمرين الثاني: الصفات 3 ن، الجزاء 2 ن، الاستشهادان 1 ن.</li><li>التمرين الثالث: بيان الحكم 3 ن، الاستشهاد مع العزو 2 ن، البديل العملي 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei15","domaine":"islamique","unite":15,"theme":"الوحدة الثالثة — الدروس EI14 إلى EI19","tag":"EI15","langue":"ar","titre":"مدخل التزكية (العقيدة) 3: النظر والتفكر سبيل المعرفة والهداية","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) النظر والتفكر ويميّز بينهما.","أن يستدل على مشروعية النظر والتفكر بنصوص من القرآن والسنة مع العزو.","أن يعدّد مجالات النظر: الآفاق، والنفس، والتاريخ، والوحي.","أن يبيّن ضوابط النظر السليم وحدوده.","أن ينجز نشاطا للنظر في ظاهرة كونية أو ذاتية ويستخرج منها عبرة إيمانية."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: سُئل تلميذ: «كيف عرفت أن لهذا الكون خالقا؟» فقال: «قيل لي». فسأله زميله: «وهل لك دليل أنت؟» درسنا اليوم يجيب: للإنسان طريق عقلي إلى المعرفة اسمه النظر والتفكر.</p>\n<p><strong>التعريفات</strong>:</p>\n<blockquote><p><strong>النظر</strong>: تأمل الشيء ومقدماته للانتقال منه إلى نتيجة؛ فهو حركة العقل من المحسوس إلى الحكم.</p></blockquote>\n<blockquote><p><strong>التفكر</strong>: إعمال الفكر في المخلوقات والأحداث لاستخراج العبرة والدلالة على الخالق.</p></blockquote>\n<blockquote><p><strong>الفرق بينهما</strong>: النظر أقرب إلى بناء الدليل (منهج)، والتفكر أقرب إلى استثمار الدليل وجوا في القلب (أثر). وهما متلازمان: نظر بلا تفكر يصير جدلا، وتفكر بلا نظر يصير خيالا.</p></blockquote>\n<p><strong>الأدلة الشرعية</strong>:</p>\n<ul><li>«إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الْأَلْبَابِ (190) الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ (191)» (سورة آل عمران، الآيتان 190-191).</li><li>«قُلِ انْظُرُوا مَاذَا فِي السَّمَاوَاتِ وَالْأَرْضِ» (سورة يونس، الآية 101).</li><li>«أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ» (سورة الغاشية، الآية 17).</li><li>«وَفِي أَنْفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ» (سورة الذاريات، الآية 21).</li><li>«سَنُرِيهِمْ آيَاتِنَا فِي الْآفَاقِ وَفِي أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ» (سورة فصلت، الآية 53).</li></ul>\n<p><strong>مجالات النظر والتفكر</strong>:</p>\n<table><thead><tr><th>المجال</th><th>أمثلة</th><th>العبرة</th></tr></thead><tbody><tr><td>الآفاق (الكون)</td><td>السماء، الجبال، البحر، النبات، تعاقب الليل والنهار</td><td>عظمة القدرة وإحكام التدبير</td></tr><tr><td>النفس (الإنسان)</td><td>خلق الجنين، الحواس، العقل، الذاكرة، النوم</td><td>تكريم الإنسان وضعفه معا</td></tr><tr><td>التاريخ والأمم</td><td>مصائر الظالمين، سنن قيام الحضارات وسقوطها</td><td>سنن الله لا تتغير</td></tr><tr><td>الوحي (القرآن)</td><td>إحكام الكتاب، تناسق آياته، إعجازه</td><td>صدق النبوة</td></tr></tbody></table>\n<p><strong>ضوابط النظر السليم</strong>:</p>\n<ol><li>أن يُبنى على العلم لا على الظن: «وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ» (سورة الإسراء، الآية 36).</li><li>أن يهدف إلى المعرفة والعمل لا إلى الجدل والمراء.</li><li>أن يعرف حدود العقل: فالعقل يدرك وجود الخالق ووجوب توحيده، ولا يستقل بمعرفة تفاصيل الغيب والأحكام التي لا تُعرف إلا بالوحي.</li><li>ألا يخوض في ذات الله؛ فالتفكر في المخلوقات لا في الذات.</li><li>أن يُقرن النظر بالذكر والدعاء كما في آية آل عمران: نظر ثم «رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا».</li></ol>\n<p><strong>البعد المذهبي المغربي</strong>: منهج العقيدة المعتمد بالمغرب هو <strong>العقيدة الأشعرية</strong>، ومن أصولها الاستدلال العقلي المنضبط بالنقل: الاستدلال بالحدوث والإتقان على وجود الخالق، مع تنزيهه عن مشابهة المخلوقات، والتسليم في تفاصيل الغيب لما جاء به الوحي. وقد أُقرّت هذه الثوابت في المرجعية الدينية الوطنية: المذهب المالكي في الفقه، والعقيدة الأشعرية، والتصوف السنّي، وإمارة المؤمنين (مستجدات منهاج التربية الإسلامية).</p>\n<p><strong>نشاط الاكتشاف</strong>: تُوزع بطاقات مجالات (ظاهرة كونية، عضو في جسم الإنسان، حدث تاريخي، آية قرآنية)، وينجز كل فريق بطاقة نظر: الظاهرة ← الملاحظة ← الدلالة ← العبرة ← الالتزام.</p>\n<p><strong>مثال محلول 1</strong>: ما وجه دلالة تعاقب الليل والنهار على وجود الخالق؟ الجواب: انتظام لا يتخلف، والانتظام يدل على مدبّر عليم؛ ولو كان بالمصادفة لاختلف واضطرب.</p>\n<p><strong>مثال محلول 2</strong>: لماذا نهى الشرع عن التفكر في ذات الله؟ الجواب: لأن العقل يدرك المحدود، وذات الله ليست كذات المخلوقات، فالخوض فيها يوقع في التشبيه أو الحيرة؛ فالباب المفتوح هو التفكر في الخلق.</p>\n<p><strong>مثال محلول 3</strong>: تلميذ يقول: «العلم الحديث يفسر كل شيء فلا حاجة للإيمان». الجواب: العلم يبيّن <strong>كيف</strong> تعمل الظواهر، والإيمان يجيب عن <strong>من</strong> أوجدها و<strong>لماذا</strong>؛ فالسؤالان مختلفان، والعلم يزيد المؤمن يقينا كلما اكتشف إحكاما جديدا.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>النظر</td><td>تأمل يبني الدليل وينقل من المحسوس إلى الحكم</td></tr><tr><td>التفكر</td><td>إعمال الفكر في المخلوقات لاستخراج العبرة</td></tr><tr><td>أولو الألباب</td><td>أصحاب العقول الراجحة</td></tr><tr><td>الآفاق</td><td>الكون الواسع من سماء وأرض</td></tr><tr><td>السنن</td><td>القوانين الثابتة التي أجراها الله في الخلق والتاريخ</td></tr><tr><td>العقيدة الأشعرية</td><td>مذهب في العقيدة يجمع الدليل العقلي المنضبط مع التسليم للنقل، وهو المعتمد بالمغرب</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الظن أن الإيمان تقليد بلا دليل؛ والصواب أن الشرع دعا إلى النظر والاستدلال.</li><li>⚠️ التفكر في ذات الله؛ والصواب أن التفكر في المخلوقات لا في الذات.</li><li>⚠️ اعتبار العلم التجريبي منافسا للإيمان؛ والصواب أنه يجيب عن سؤال آخر ويخدم اليقين.</li><li>⚠️ تحويل النظر إلى جدال لإسكات المخالف؛ والصواب أن مقصده المعرفة والعمل.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف النظر والتفكر، وبيّن الفرق بينهما.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر آيتين تدعوان إلى النظر مع العزو الكامل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>عدّد مجالات النظر الأربعة مع مثال لكل مجال.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر ثلاثة من ضوابط النظر السليم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>ما الثوابت الدينية الوطنية بالمغرب؟</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>بيّن وجه دلالة انتظام تعاقب الليل والنهار على وجود الخالق.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>لماذا لا يجوز التفكر في ذات الله؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>أنجز بطاقة نظر لظاهرة المطر (الملاحظة / الدلالة / العبرة / الالتزام).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>ما الفرق بين النظر المنتج والجدل العقيم؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>استخرج من الآيتين 190-191 من آل عمران صفات أولي الألباب.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: قال زميلك: «العلم يفسر كل شيء فلا حاجة إلى الإيمان». حرّر عشرة أسطر تناقش هذه المقولة مناقشة هادئة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف يكون النظر في النفس البشرية أقرب دليل على الخالق؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز جدولا لثلاث ظواهر (الظاهرة / الوجه العلمي / العبرة الإيمانية).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن أثر النظر والتفكر في تقوية اليقين وفي حماية المتعلم من الشبهات.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"النظر","v":"تأمل يبني الدليل وينقل من المحسوس إلى الحكم"},{"r":"التفكر","v":"إعمال الفكر في المخلوقات لاستخراج العبرة"},{"r":"أولو الألباب","v":"أصحاب العقول الراجحة"},{"r":"الآفاق","v":"الكون الواسع من سماء وأرض"},{"r":"السنن","v":"القوانين الثابتة التي أجراها الله في الخلق والتاريخ"},{"r":"العقيدة الأشعرية","v":"مذهب في العقيدة يجمع الدليل العقلي المنضبط مع التسليم للنقل، وهو المعتمد بالمغرب"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — عرّف النظر والتفكر، واذكر مجالات النظر الأربعة مع مثال لكل مجال.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — اذكر أربعة من ضوابط النظر السليم، واستشهد لواحد منها بنص مع العزو.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: يعرض عليك زميل مقاطع تُشكّك في الدين بحجة العلم. حرّر عشرة أسطر تبيّن منهجك في التعامل مع الشبهة، وتوضح علاقة العلم بالإيمان، وتقترح مراجع موثوقة.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريفان 2 ن، المجالات وأمثلتها 4 ن.</li><li>التمرين الثاني: كل ضابط 1,25 ن، والاستشهاد مع العزو 1 ن.</li><li>التمرين الثالث: منهج التعامل مع الشبهة 3 ن، بيان علاقة العلم بالإيمان 3 ن، المراجع الموثوقة 1 ن، اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei16","domaine":"islamique","unite":16,"theme":"الوحدة الثالثة — الدروس EI14 إلى EI19","tag":"EI16","langue":"ar","titre":"مدخل الاقتداء 3: صبر السابقين الأولين في الدعوة إلى الله","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) السابقين الأولين ويذكر أمثلة منهم.","أن يسرد نماذج من صبرهم على الأذى بأمانة تاريخية.","أن يستخرج أنواع الصبر ومظاهره في مرحلة الدعوة المكية.","أن يستدل بنصوص من القرآن والسنة على فضل الصبر مع العزو.","أن يستثمر النموذج في الصبر على التعلم والمواقف الصعبة."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: تلميذة تركت نادي القراءة بعد أسبوعين لأن زميلاتها سخرن منها. كيف صبر أول المسلمين على أذى أشدّ بكثير؟</p>\n<p><strong>من هم السابقون الأولون؟</strong> هم أول من دخل الإسلام من الرجال والنساء والموالي، ومنهم: خديجة بنت خويلد رضي الله عنها أول من آمن، وأبو بكر الصديق، وعلي بن أبي طالب، وزيد بن حارثة، وبلال بن رباح، وعمار بن ياسر وأبواه ياسر وسمية، وخباب بن الأرت، وصهيب الرومي، وأبو ذر الغفاري، وسعد بن أبي وقاص. وقد أثنى الله عليهم: «وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ» (سورة التوبة، الآية 100).</p>\n<p><strong>مظاهر الأذى ومظاهر الصبر</strong>:</p>\n<table><thead><tr><th>النموذج</th><th>صورة الأذى</th><th>مظهر الصبر</th></tr></thead><tbody><tr><td>بلال بن رباح</td><td>يُعذّب في رمضاء مكة ويُوضع الصخر على صدره</td><td>يثبت ويردد «أحدٌ أحد»</td></tr><tr><td>آل ياسر (ياسر وسمية وعمار)</td><td>تعذيب شديد أدى إلى وفاة سمية</td><td>ثبات على الدين ووصية النبي لهم بالصبر</td></tr><tr><td>خباب بن الأرت</td><td>يُعذّب حتى أثّر العذاب في جسده</td><td>يشكو إلى النبي فيُوجَّه إلى الصبر واليقين بالنصر</td></tr><tr><td>أبو بكر الصديق</td><td>يُضرب ويُؤذى لدفاعه عن النبي</td><td>يستمر في الدعوة وينفق ويحمي المستضعفين</td></tr><tr><td>المهاجرون إلى الحبشة</td><td>ترك الديار والأموال</td><td>هجرة صابرة حفظا للدين</td></tr></tbody></table>\n<p><strong>نص أساس</strong>: عن خباب بن الأرت رضي الله عنه قال: شكونا إلى رسول الله صلى الله عليه وسلم وهو متوسد بردة له في ظل الكعبة، فقلنا: ألا تستنصر لنا؟ ألا تدعو لنا؟ فقال: «كان الرجل فيمن قبلكم يُمشط بأمشاط الحديد... والله ليتمّنّ هذا الأمر حتى يسير الراكب من صنعاء إلى حضرموت لا يخاف إلا الله» (أخرجه البخاري، كتاب المناقب، حديث رقم 3612، باختصار في اللفظ مع حفظ المعنى).</p>\n<p><strong>أنواع الصبر المستفادة</strong>:</p>\n<ol><li><strong>الصبر على الأذى في الله</strong>: تحمّل التعذيب والمقاطعة والسخرية.</li><li><strong>الصبر على طول الطريق</strong>: ثلاث عشرة سنة بمكة قبل الهجرة.</li><li><strong>الصبر على ترك المألوف</strong>: مقاطعة، وحصار في شعب أبي طالب، وهجرة.</li><li><strong>الصبر عن رد الأذى بمثله في مرحلة الاستضعاف</strong>: التزام بأمر النبي صلى الله عليه وسلم بالكفّ.</li></ol>\n<blockquote><p><strong>قاعدة تربوية</strong>: صبر السابقين لم يكن سلبية ولا استسلاما؛ كان صبرا <strong>مع عمل</strong>: دعوة سرية، وتنظيم في دار الأرقم، وهجرة إلى الحبشة، وتحمل التكاليف. فالصبر عندهم إدارة للمحن لا انتظار لها.</p></blockquote>\n<p><strong>أدلة فضل الصبر</strong>: «وَبَشِّرِ الصَّابِرِينَ (155) الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ (156)» (سورة البقرة، الآيتان 155-156)، و«إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ» (سورة الزمر، الآية 10)، وقال النبي صلى الله عليه وسلم: «ومن يصبر يصبّره الله، وما أُعطي أحد عطاء خيرا وأوسع من الصبر» (أخرجه البخاري، كتاب الزكاة، حديث رقم 1469، ومسلم، حديث رقم 1053).</p>\n<p><strong>مثال محلول 1</strong>: ما الفرق بين صبر بلال وصبر إنسان يائس ساكت؟ الجواب: بلال صبر بيقين في النصر وثبات على الاعتقاد وتصريح به «أحد أحد»؛ واليائس يسكت لعجز بلا يقين ولا موقف.</p>\n<p><strong>مثال محلول 2</strong>: لماذا أُمر المسلمون بالكفّ في مكة؟ الجواب: لأن المرحلة مرحلة تأسيس وقلة عدد، ولحفظ النفوس، وحتى ينبني الدين على قوة عقيدة لا على ردود انفعالية؛ وهذا فقه للمرحلة.</p>\n<p><strong>مثال محلول 3</strong>: كيف يقتدي التلميذ بهذا الصبر؟ الجواب: بالصبر على المراجعة الطويلة، وعلى تصحيح الخطأ، وعلى السخرية عند التميز، وبالاستمرار في الخير مع الحلم على المخالف.</p>\n<p><strong>السياق المغربي</strong>: في المغرب تُروى قصص السابقين الأولين في دروس المساجد وفي المواسم الدينية والمناسبات النبوية، وتُستثمر في التربية على التسامح والثبات على القيم، ضمن مرجعية تحترم إمارة المؤمنين كضامن للثوابت الدينية ووحدة المذهب.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>السابقون الأولون</td><td>أول من أسلم وثبت من المهاجرين والأنصار ومن اتبعهم بإحسان</td></tr><tr><td>الموالي</td><td>من كانوا مملوكين أو محررين، وكانوا من أوائل المسلمين</td></tr><tr><td>رمضاء مكة</td><td>الرمل والحجر الشديد الحرارة</td></tr><tr><td>المقاطعة والحصار</td><td>حصار قريش لبني هاشم في الشعب</td></tr><tr><td>هجرة الحبشة</td><td>خروج جماعة من المسلمين إلى الحبشة فرارا بدينهم</td></tr><tr><td>فقه المرحلة</td><td>مراعاة حال الجماعة وقوّتها في اختيار الأسلوب</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ حصر السابقين الأولين في الرجال والسادة؛ والصواب أن فيهم النساء والموالي، وخديجة رضي الله عنها أول من آمن.</li><li>⚠️ فهم الصبر سلبية وانتظارا؛ والصواب أنه صبر مقرون بعمل وتنظيم وهجرة.</li><li>⚠️ المبالغة في تفاصيل روايات التعذيب بما لا يثبت؛ والصواب الاقتصار على ما صحّ وذكر مصدره.</li><li>⚠️ الاستدلال بكفّ المسلمين في مكة على ترك الحقوق دائما؛ والصواب أنه فقه مرحلة استضعاف.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>من السابقون الأولون؟ اذكر ستة أسماء منهم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>من أول من آمن برسول الله صلى الله عليه وسلم؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر أربعة مظاهر من الأذى الذي لقيه المسلمون بمكة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر آية وحديثا في فضل الصبر مع العزو الكامل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>عرّف: الموالي، هجرة الحبشة، فقه المرحلة.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>أنجز جدولا (النموذج / صورة الأذى / مظهر الصبر) لثلاثة من السابقين.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>استخرج من حديث خباب بن الأرت درسين تربويين.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>عدّد أنواع الصبر الأربعة في المرحلة المكية مع مثال لكل نوع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>بيّن الفرق بين الصبر والاستسلام.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>لماذا أُمر المسلمون بالكفّ عن رد الأذى في مكة؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميلة تُسخر منها لأنها تجتهد في الدراسة وتحضر نادي القراءة. حرّر عشرة أسطر تدعمها فيها بنموذج من صبر السابقين وبخطوات عملية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: «الصبر إدارة للمحنة لا انتظار لها» في ضوء سيرة المرحلة المكية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>قارن بين صبر بلال بن رباح وصبر أبي بكر الصديق من حيث نوع التكليف.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن كيفية استثمار قصص السابقين الأولين في تربية الناشئة على الثبات والتسامح.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"السابقون الأولون","v":"أول من أسلم وثبت من المهاجرين والأنصار ومن اتبعهم بإحسان"},{"r":"الموالي","v":"من كانوا مملوكين أو محررين، وكانوا من أوائل المسلمين"},{"r":"رمضاء مكة","v":"الرمل والحجر الشديد الحرارة"},{"r":"المقاطعة والحصار","v":"حصار قريش لبني هاشم في الشعب"},{"r":"هجرة الحبشة","v":"خروج جماعة من المسلمين إلى الحبشة فرارا بدينهم"},{"r":"فقه المرحلة","v":"مراعاة حال الجماعة وقوّتها في اختيار الأسلوب"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — من السابقون الأولون؟ اذكر خمسة منهم، واستشهد بآية في فضلهم مع العزو.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — أنجز جدولا لثلاثة نماذج (النموذج / صورة الأذى / مظهر الصبر)، ثم بيّن نوع الصبر في كل نموذج.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: تلميذ يريد ترك مشروع تطوعي بعد أول انتقاد لاذع. حرّر عشرة أسطر تناصحه فيها بالاستدلال بسيرة السابقين الأولين، وتقترح خطوات عملية للاستمرار.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: الأسماء 3 ن، الآية مع العزو 3 ن.</li><li>التمرين الثاني: الجدول 4,5 ن، تحديد نوع الصبر 1,5 ن.</li><li>التمرين الثالث: النصح بالنموذج 3 ن، الاستشهاد مع العزو 2 ن، الخطوات العملية 2 ن، اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei17","domaine":"islamique","unite":17,"theme":"الوحدة الثالثة — الدروس EI14 إلى EI19","tag":"EI17","langue":"ar","titre":"مدخل الاستجابة 3: الصلاة (أحكامها ومقاصدها: الفرائض، السنن، المبطلات)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) الصلاة ويبيّن مكانتها في الإسلام.","أن يعدّد فرائض الصلاة عند المالكية ويميّزها من السنن والفضائل.","أن يعدّد مبطلات الصلاة.","أن يستدل على أحكام الصلاة بنصوص من القرآن والسنة مع العزو.","أن يبيّن مقاصد الصلاة وأثرها في سلوك المتعلم(ة)."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: تلميذ صلّى مسرعا فلم يطمئنّ في ركوعه ولا سجوده، فسأل: «هل صلاتي صحيحة؟» ولنعرف الجواب نحتاج أن نميّز بين ما لا تصح الصلاة بتركه وما تصح مع النقصان.</p>\n<p><strong>تعريف الصلاة ومكانتها</strong>:</p>\n<blockquote><p><strong>الصلاة</strong>: أقوال وأفعال مخصوصة، مفتتحة بالتكبير، مختتمة بالسلام، بشروط مخصوصة.</p></blockquote>\n<p>وهي الركن الثاني من أركان الإسلام، وعمود الدين، وأول ما يُحاسب عليه العبد. قال تعالى: «وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ» (سورة البقرة، الآية 43)، وقال: «إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا» (سورة النساء، الآية 103). وقال النبي صلى الله عليه وسلم: «صلّوا كما رأيتموني أصلي» (أخرجه البخاري، كتاب الأذان، حديث رقم 631).</p>\n<p><strong>تصنيف أحكام الصلاة عند المالكية</strong>:</p>\n<table><thead><tr><th>الرتبة</th><th>الحكم</th><th>حال الترك</th></tr></thead><tbody><tr><td>الفرائض (الأركان)</td><td>لا تصح الصلاة بترك واحدة منها</td><td>تبطل الصلاة، ويجب الإتيان بها أو إعادة الصلاة</td></tr><tr><td>السنن</td><td>مطلوبة طلبا مؤكدا</td><td>تُجبر بسجود السهو في الجملة، والصلاة صحيحة</td></tr><tr><td>الفضائل (المستحبات)</td><td>مندوبة</td><td>لا يترتب على تركها شيء</td></tr></tbody></table>\n<p><strong>فرائض الصلاة عند المالكية</strong> (والعدد يُذكر عند المالكية في نحو أربع عشرة أو خمس عشرة فريضة بحسب طريقة العدّ):</p>\n<ol><li>النية.</li><li>تكبيرة الإحرام.</li><li>القيام لتكبيرة الإحرام.</li><li>قراءة الفاتحة.</li><li>القيام لقراءة الفاتحة.</li><li>الركوع.</li><li>الرفع من الركوع.</li><li>السجود على الجبهة.</li><li>الرفع من السجود.</li><li>الجلوس بين السجدتين.</li><li>الجلوس بمقدار السلام.</li><li>السلام.</li><li>الطمأنينة في الأركان.</li><li>الاعتدال في القيام والجلوس.</li><li>ترتيب الفرائض على وجهها.</li></ol>\n<p><strong>من سنن الصلاة</strong>: الأذان والإقامة، والسورة بعد الفاتحة، والتكبيرات غير تكبيرة الإحرام، وسمع الله لمن حمده، والتشهد والجلوس له، والصلاة على النبي صلى الله عليه وسلم في التشهد الأخير، والجهر والإسرار في محلهما، والتسبيح في الركوع والسجود، والسجود على باقي الأعضاء السبعة.</p>\n<p><strong>من فضائل الصلاة</strong>: رفع اليدين مع تكبيرة الإحرام، والدعاء بعد التشهد، وإطالة القراءة في الصبح، والقنوت في محله بحسب المذهب، وتحسين الهيئة والسواك.</p>\n<p><strong>مبطلات الصلاة</strong>:</p>\n<ol><li>ترك فريضة من فرائض الصلاة عمدا.</li><li>الكلام العمد لغير إصلاح الصلاة.</li><li>الأكل والشرب.</li><li>الحدث (انتقاض الطهارة) أو وجود نجاسة غير معفو عنها.</li><li>الضحك بصوت (القهقهة).</li><li>العمل الكثير الأجنبي عن الصلاة.</li><li>استدبار القبلة أو الانحراف عنها عمدا بلا عذر.</li><li>تعمّد زيادة ركن فعلي كركوع أو سجود.</li><li>الردة عن الإسلام، والعياذ بالله.</li><li>تعمّد إبطالها بقطعها بلا عذر شرعي.</li></ol>\n<blockquote><p><strong>قاعدة</strong>: ما تُرك سهوا من السنن يُجبر بسجود السهو، وما تُرك من الفرائض لا يُجبر بسجود بل يجب الإتيان به إن أمكن أو إعادة الصلاة. وتفصيل سجود السهو يأتي في درس مستقل (EI23).</p></blockquote>\n<p><strong>نص أساس في الطمأنينة</strong>: عن أبي هريرة رضي الله عنه أن رجلا صلّى فسلّم على النبي صلى الله عليه وسلم فقال له: «ارجع فصلِّ فإنك لم تصلّ»، ثلاث مرات، ثم علّمه صفة الصلاة وأمره بالطمأنينة في الركوع والسجود (أخرجه البخاري، كتاب الأذان، حديث رقم 757، ومسلم، حديث رقم 397 بنحوه). وهذا الحديث دليل على أن العجلة تُفسد الصلاة، وأن الطمأنينة فريضة.</p>\n<p><strong>مقاصد الصلاة</strong>:</p>\n<ol><li><strong>تحقيق العبودية والصلة بالله</strong>: «وَأَقِمِ الصَّلَاةَ لِذِكْرِي» (سورة طه، الآية 14).</li><li><strong>التطهير من الفواحش</strong>: «إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ» (سورة العنكبوت، الآية 45).</li><li><strong>التربية على الانتظام وحسن تدبير الوقت</strong>: لأنها «كِتَابًا مَوْقُوتًا».</li><li><strong>الطمأنينة النفسية</strong>: راحة يستعيد بها المسلم توازنه في يومه.</li><li><strong>البعد الاجتماعي</strong>: صلاة الجماعة تُعلّم النظام والمساواة والانتماء.</li></ol>\n<p><strong>السياق المغربي</strong>: يعتمد المغرب المذهب المالكي في العبادات، وتُصلّى الصلوات في المساجد بإشراف وزارة الأوقاف والشؤون الإسلامية، ويُرفع الأذان بتوقيت موحّد تنشره الوزارة. ومن مظاهر العناية بالصلاة: كثرة المساجد وحلقات تعليم الصلاة للأطفال في الكتاتيب القرآنية، والصلوات الجامعة في المناسبات الدينية، والتزام كثير من المؤسسات بجدولة تسمح بأداء الصلاة.</p>\n<p><strong>مثال محلول 1</strong>: تلميذ ترك سورة بعد الفاتحة سهوا. الجواب: السورة سنة، فصلاته صحيحة، ويجبر ذلك بسجود السهو، ولا يعيد.</p>\n<p><strong>مثال محلول 2</strong>: تلميذ نسي الفاتحة في ركعة ولم يتذكر إلا بعد السلام. الجواب: الفاتحة فريضة، فلا تُجبر بسجود، والحكم أن ركعته باطلة فيلزمه إتمام صلاته على وجهها أو إعادتها؛ ومثل هذه النازلة يُرجع فيها إلى أهل العلم لتفصيلها.</p>\n<p><strong>مثال محلول 3</strong>: تكلّم تلميذ في الصلاة ليُذكّر زميله بخطأ. الجواب: الكلام العمد مبطل، والسنة أن يُنبّه بالتسبيح إن كان رجلا أو بالتصفيق للنساء، لا بالكلام.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>تكبيرة الإحرام</td><td>قول «الله أكبر» التي تُفتتح بها الصلاة</td></tr><tr><td>الطمأنينة</td><td>السكون في الركن قدرا يُعتدّ به</td></tr><tr><td>الاعتدال</td><td>تسوية الظهر في القيام وتمام الجلوس</td></tr><tr><td>سنة</td><td>ما طُلب طلبا مؤكدا ويُجبر بسجود السهو في الجملة</td></tr><tr><td>فضيلة</td><td>مستحب لا يترتب على تركه شيء</td></tr><tr><td>مبطل</td><td>ما تفسد به الصلاة فتلزم إعادتها</td></tr><tr><td>كتابا موقوتا</td><td>مفروضة في أوقات محددة</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الخلط بين الفريضة والسنة، فيُظن أن السورة بعد الفاتحة فريضة؛ والصواب أنها سنة.</li><li>⚠️ العجلة وترك الطمأنينة؛ والصواب أن الطمأنينة فريضة لحديث «ارجع فصلِّ فإنك لم تصلّ» (البخاري 757).</li><li>⚠️ الظن أن كل خطأ يُجبر بسجود السهو؛ والصواب أن الفرائض لا تُجبر به.</li><li>⚠️ الكلام في الصلاة لتصحيح خطأ الغير؛ والصواب التنبيه بالتسبيح.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف الصلاة، وبيّن مكانتها في الإسلام.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر ثماني فرائض من فرائض الصلاة عند المالكية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر أربع سنن وثلاث فضائل من سنن الصلاة وفضائلها.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر ستة من مبطلات الصلاة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>أتمم الحديث: «صلّوا كما ...» مع العزو.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>أنجز جدولا (الرتبة / التعريف / حال الترك) للفريضة والسنة والفضيلة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ما حكم من ترك السورة بعد الفاتحة سهوا؟ ولماذا؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>استخرج من حديث «ارجع فصلِّ فإنك لم تصلّ» حكمين فقهيين.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>اذكر أربعة من مقاصد الصلاة مع دليل لواحد منها.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>ما الفرق بين ترك الفريضة سهوا وترك السنة سهوا في الحكم؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميل يصلي بسرعة كبيرة ويقول «المهم أني صليت». حرّر عشرة أسطر تناصحه فيها بالدليل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف تربي الصلاة على تدبير الوقت والانتظام في حياة المتعلم(ة)؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>صنّف الحالات الآتية (صحيحة / باطلة / تُجبر بسجود السهو) مع التعليل: ترك الفاتحة عمدا / الكلام العمد / نسيان التشهد / عدم الطمأنينة في الركوع / نسيان التسبيح في السجود.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن مظاهر العناية بالصلاة في المغرب وأثرها الاجتماعي.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"تكبيرة الإحرام","v":"قول «الله أكبر» التي تُفتتح بها الصلاة"},{"r":"الطمأنينة","v":"السكون في الركن قدرا يُعتدّ به"},{"r":"الاعتدال","v":"تسوية الظهر في القيام وتمام الجلوس"},{"r":"سنة","v":"ما طُلب طلبا مؤكدا ويُجبر بسجود السهو في الجملة"},{"r":"فضيلة","v":"مستحب لا يترتب على تركه شيء"},{"r":"مبطل","v":"ما تفسد به الصلاة فتلزم إعادتها"},{"r":"كتابا موقوتا","v":"مفروضة في أوقات محددة"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — اذكر ثماني فرائض من فرائض الصلاة، وأربع سنن، مع بيان الفرق بين الرتبتين في حال الترك.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — صنّف خمس حالات (تُعطى في ورقة الفرض) إلى: صحيحة، باطلة، تُجبر بسجود السهو، مع التعليل.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: تلميذ يصلي بعجلة ويقول إن المهم أداء الصلاة في وقتها. حرّر عشرة أسطر تصحح تصوره بالدليل، وتقترح خطوات عملية للخشوع.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: الفرائض 4 ن، السنن 2 ن، الفرق 1 ن.</li><li>التمرين الثاني: كل حالة مصنفة ومعلّلة 1,2 ن.</li><li>التمرين الثالث: تصحيح التصور 2,5 ن، الاستشهاد مع العزو 2 ن، الخطوات العملية 2 ن، اللغة 0,5 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei18","domaine":"islamique","unite":18,"theme":"الوحدة الثالثة — الدروس EI14 إلى EI19","tag":"EI18","langue":"ar","titre":"مدخل القسط 3: حق الغير (حقوق الآباء والأبناء وذوي الرحم)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) حق الغير ويحدد دوائره.","أن يعدّد حقوق الوالدين على الأبناء بالدليل مع العزو.","أن يعدّد حقوق الأبناء على الآباء.","أن يبيّن حقوق ذوي الرحم وأثر صلة الرحم.","أن يُنجز التزامات عملية في بره بوالديه وصلته بأرحامه."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: تلميذ يقول: «أمي تطلب مني مساعدتها وأنا مشغول بالهاتف، وخالتي مريضة ولم أزرها منذ سنة». ما ترتيب الحقوق؟ وما واجبه؟</p>\n<p><strong>تعريف حق الغير</strong>:</p>\n<blockquote><p><strong>حق الغير</strong>: كل ما يجب لغيرك عليك من حسن معاملة وأداء واجب، ابتداء بأقرب الناس إليك: الوالدان، ثم الأولاد، ثم ذوو الرحم، ثم الجار، ثم عموم الناس.</p></blockquote>\n<p><strong>أولا: حقوق الوالدين</strong>:</p>\n<p>قال تعالى: «وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا ۚ إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلَاهُمَا فَلَا تَقُلْ لَهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا (23) وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا (24)» (سورة الإسراء، الآيتان 23-24). وقال تعالى: «وَوَصَّيْنَا الْإِنسَانَ بِوَالِدَيْهِ حَمَلَتْهُ أُمُّهُ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَالُهُ فِي عَامَيْنِ أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ» (سورة لقمان، الآية 14).</p>\n<p>وعن عبد الله بن مسعود رضي الله عنه سأل النبي صلى الله عليه وسلم: أي العمل أحب إلى الله؟ قال: «الصلاة على وقتها»، قال: ثم أي؟ قال: «ثم بر الوالدين»، قال: ثم أي؟ قال: «ثم الجهاد في سبيل الله» (أخرجه البخاري، كتاب مواقيت الصلاة، حديث رقم 527، ومسلم، حديث رقم 85).</p>\n<p>وعن أبي هريرة رضي الله عنه أن رجلا سأل: من أحقّ الناس بحسن صحابتي؟ قال: «أمك»، ثم قال: «أمك»، ثم قال: «أمك»، ثم قال: «أبوك» (أخرجه البخاري، كتاب الأدب، حديث رقم 5971، ومسلم، حديث رقم 2548).</p>\n<p><strong>مظاهر البر</strong>: طاعتهما في غير معصية، والإحسان إليهما بالقول والفعل، وخفض الصوت وترك التأفف، وخدمتهما خصوصا عند الكبر، والإنفاق عليهما عند الحاجة، والدعاء لهما، وصلة من يحبّان، وحفظ سمعتهما، وشكرهما، والبر بهما بعد الموت بالدعاء والصدقة وصلة أصدقائهما.</p>\n<blockquote><p><strong>ضابط مهم</strong>: الطاعة تكون في المعروف؛ فإن أمرا بمعصية فلا يُطاعان فيها، ومع ذلك تبقى لهما حرمة البر وحسن القول: «وَإِنْ جَاهَدَاكَ عَلَىٰ أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا» (سورة لقمان، الآية 15).</p></blockquote>\n<p><strong>ثانيا: حقوق الأبناء على الآباء</strong>:</p>\n<ol><li>حق الحياة والنسب والاسم الحسن.</li><li>حق النفقة والرعاية الصحية.</li><li>حق التربية والتعليم: «كلكم راعٍ وكلكم مسؤول عن رعيته» (أخرجه البخاري، كتاب النكاح، حديث رقم 5200، ومسلم، حديث رقم 1829).</li><li>حق العدل بين الأولاد وعدم التمييز.</li><li>حق الرحمة وحسن المعاملة: «من لا يرحم لا يُرحم» (أخرجه البخاري، حديث رقم 5997).</li><li>حق التوجيه إلى الصلاة والقيم.</li></ol>\n<p><strong>ثالثا: حقوق ذوي الرحم</strong>:</p>\n<p>الرحم كل من تصلك بهم قرابة: الأجداد، والأعمام والعمات، والأخوال والخالات، والإخوة، وأبناؤهم. قال تعالى: «وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ» (سورة النساء، الآية 1). وقال النبي صلى الله عليه وسلم: «من أحبّ أن يُبسط له في رزقه ويُنسأ له في أثره فليصل رحمه» (أخرجه البخاري، كتاب الأدب، حديث رقم 5986). ومظاهر الصلة: الزيارة، والسؤال والاتصال، والمساعدة عند الحاجة، وحضور المناسبات، والإصلاح بين المتخاصمين، والعفو عن الزلات.</p>\n<p><strong>السياق المغربي</strong>: تحفظ الأسرة المغربية قيم البر وصلة الرحم في ممارسات عملية: زيارة الوالدين والأجداد في العيدين وعقيقة المولود، والتجمع الأسري في المواسم الدينية والمناسبات، والتكافل مع الأقارب في الأفراح والأتراح، والإحسان إلى المسنين. ومدونة الأسرة تنظم واجبات النفقة والحضانة والنسب، فيتكامل الحكم الشرعي مع الإطار القانوني، وهذا من قيم المواطنة المسؤولة.</p>\n<p><strong>مثال محلول 1</strong>: أمرت الأم ابنها بترك مراجعة درسه لينجز شيئا عاجلا. الجواب: يوازن؛ فيستأذنها بلطف ويخبرها بموعد الفرض، وإن أصرّت أطاعها في المعروف، فالبر لا يُنافي حسن التفاهم.</p>\n<p><strong>مثال محلول 2</strong>: أب يميّز بين ابنه وابنته في الهدايا. الجواب: العدل بين الأولاد حق واجب، والتمييز يُورث الحقد والغيرة؛ فيُذكّر بالعدل بلطف واحترام.</p>\n<p><strong>مثال محلول 3</strong>: تلميذ قطع صلة خاله لخلاف مالي بين أبيه وخاله. الجواب: خلاف الآباء لا يسقط حق الرحم؛ فيصل خاله ويجتهد في الإصلاح بينهما.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>حق الغير</td><td>ما يجب لغيرك عليك من واجبات وحسن معاملة</td></tr><tr><td>البر</td><td>الإحسان الواسع إلى الوالدين قولا وفعلا</td></tr><tr><td>العقوق</td><td>ترك البر وإيذاء الوالدين</td></tr><tr><td>ذوو الرحم</td><td>الأقارب الذين تصلك بهم قرابة النسب</td></tr><tr><td>صلة الرحم</td><td>الإحسان إلى الأقارب بالزيارة والمساعدة والسؤال</td></tr><tr><td>الطاعة في المعروف</td><td>طاعة الوالدين في غير معصية</td></tr><tr><td>العدل بين الأولاد</td><td>التسوية بينهم في العطاء والمعاملة</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الظن أن طاعة الوالدين مطلقة حتى في المعصية؛ والصواب أنها في المعروف مع بقاء حسن الصحبة.</li><li>⚠️ حصر البر في النفقة؛ والصواب أنه يشمل القول اللين والخدمة والدعاء وحفظ السمعة.</li><li>⚠️ قطع الرحم بسبب خلاف بين الكبار؛ والصواب أن حق الرحم ثابت مستقل.</li><li>⚠️ اعتبار الصلة مكافأة للواصل فقط؛ والصواب أن الواصل هو من يصل من قطعه.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف حق الغير، واذكر دوائره مرتبة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر أربعة مظاهر لبر الوالدين.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>استظهر الآيتين 23-24 من سورة الإسراء.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر أربعة من حقوق الأبناء على الآباء.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>من هم ذوو الرحم؟ واذكر ثلاثة من مظاهر صلتهم.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>أتمم الحديث: «من أحبّ أن يُبسط له في رزقه ...» مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ما ضابط طاعة الوالدين؟ استشهد بنص.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>بيّن سبب تقديم الأم ثلاثا على الأب في حديث حسن الصحابة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>كيف يكون البر بالوالدين بعد وفاتهما؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>أنجز جدولا (الحق / صاحبه / مظهر عملي) لخمسة حقوق.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: أبوك يخاصم عمك، وعمك مريض. حرّر عشرة أسطر تبيّن واجبك مستدلا بالنصوص.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف تكون صلة الرحم عاملا في تقوية التماسك الاجتماعي؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>صنّف السلوكات الآتية إلى برّ وعقوق مع التعليل: رفع الصوت على الأم / خدمة الجد المسنّ / التأفف من طلب الأب / الدعاء للوالدين / إخفاء نتائج الدراسة عنهما.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن التزامات عملية أسبوعية في بر والديك وصلة أرحامك، مع طريقة لتقويم نفسك.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"حق الغير","v":"ما يجب لغيرك عليك من واجبات وحسن معاملة"},{"r":"البر","v":"الإحسان الواسع إلى الوالدين قولا وفعلا"},{"r":"العقوق","v":"ترك البر وإيذاء الوالدين"},{"r":"ذوو الرحم","v":"الأقارب الذين تصلك بهم قرابة النسب"},{"r":"صلة الرحم","v":"الإحسان إلى الأقارب بالزيارة والمساعدة والسؤال"},{"r":"الطاعة في المعروف","v":"طاعة الوالدين في غير معصية"},{"r":"العدل بين الأولاد","v":"التسوية بينهم في العطاء والمعاملة"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — عرّف حق الغير، واذكر أربعة مظاهر لبر الوالدين، ونصا واحدا مع العزو.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — اذكر أربعة من حقوق الأبناء على الآباء، وثلاثة من مظاهر صلة الرحم.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: انقطعت الصلة بين فرعي أسرة بسبب خلاف على إرث، وأنت من الجيل الجديد. حرّر اثني عشر سطرا تبيّن الحكم الشرعي، وتقترح مبادرة عملية للإصلاح.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 1,5 ن، المظاهر 3 ن، النص مع العزو 1,5 ن.</li><li>التمرين الثاني: حقوق الأبناء 4 ن، مظاهر الصلة 2 ن.</li><li>التمرين الثالث: بيان الحكم 3 ن، الاستشهاد مع العزو 2 ن، المبادرة العملية 2 ن، اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei19","domaine":"islamique","unite":19,"theme":"الوحدة الثالثة — الدروس EI14 إلى EI19","tag":"EI19","langue":"ar","titre":"مدخل الحكمة 3: التجمل بمحاسن الأخلاق","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) الخلق ومحاسن الأخلاق.","أن يستدل على مكانة الأخلاق في الإسلام بنصوص مع العزو.","أن يعدّد أمثلة من محاسن الأخلاق ويقابلها بمساوئها.","أن يبيّن وسائل تحصيل الأخلاق الحسنة.","أن ينجز مشروعا صفّيا للتجمل بخلق محدد وتقويم أثره."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: تلميذ حافظ للدروس، مجتهد في الفروض، لكنه سليط اللسان يسخر من زملائه. هل يُعدّ متعلما ناجحا؟ ولم كانت الأخلاق ميزانا للإيمان لا زينة زائدة؟</p>\n<p><strong>التعريفات</strong>:</p>\n<blockquote><p><strong>الخلق</strong>: هيئة راسخة في النفس تصدر عنها الأفعال بيسر بلا تكلّف.</p></blockquote>\n<blockquote><p><strong>محاسن الأخلاق</strong>: الصفات الحسنة التي حسّنها الشرع وحمدها العقل، كالصدق والأمانة والحلم والحياء والرحمة والوفاء والتواضع والكرم والعفو والعدل.</p></blockquote>\n<p><strong>مكانة الأخلاق في الإسلام</strong>:</p>\n<ol><li><strong>مقصد من مقاصد البعثة</strong>: قال النبي صلى الله عليه وسلم: «إنما بُعثت لأتمم صالح الأخلاق» (أخرجه أحمد في المسند، حديث رقم 8952، وأخرجه البخاري في الأدب المفرد، حديث رقم 273 بلفظ «إنما بُعثت لأتمم مكارم الأخلاق»).</li><li><strong>ميزان لكمال الإيمان</strong>: «أكمل المؤمنين إيمانا أحسنهم خلقا» (أخرجه أبو داود، كتاب السنة، حديث رقم 4682، والترمذي، حديث رقم 1162، وحسّنه).</li><li><strong>ثقل في الميزان</strong>: «ما شيء أثقل في ميزان المؤمن يوم القيامة من خلق حسن» (أخرجه أبو داود، حديث رقم 4799، والترمذي، حديث رقم 2002 بنحوه).</li><li><strong>وصف للنبي صلى الله عليه وسلم</strong>: «وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ» (سورة القلم، الآية 4).</li><li><strong>أمر قرآني صريح</strong>: «خُذِ الْعَفْوَ وَأْمُرْ بِالْمَعْرُوفِ وَأَعْرِضْ عَنِ الْجَاهِلِينَ» (سورة الأعراف، الآية 199).</li></ol>\n<p><strong>نماذج من محاسن الأخلاق ومقابلها</strong>:</p>\n<table><thead><tr><th>الخلق الحسن</th><th>معناه</th><th>مقابله المذموم</th></tr></thead><tbody><tr><td>الصدق</td><td>مطابقة القول للواقع</td><td>الكذب</td></tr><tr><td>الأمانة</td><td>حفظ ما استُودعت ورد الحقوق</td><td>الخيانة</td></tr><tr><td>الحلم</td><td>ضبط النفس عند الغضب</td><td>الطيش والانتقام</td></tr><tr><td>الحياء</td><td>انقباض النفس عن القبيح</td><td>الوقاحة</td></tr><tr><td>الرحمة</td><td>لين القلب ورفع الأذى</td><td>القسوة</td></tr><tr><td>التواضع</td><td>خفض الجناح مع الحق</td><td>الكِبر</td></tr><tr><td>الوفاء</td><td>حفظ العهد والوعد</td><td>الغدر</td></tr><tr><td>العفو</td><td>ترك المؤاخذة مع القدرة</td><td>الحقد</td></tr><tr><td>الكرم</td><td>البذل بلا منّ</td><td>الشحّ</td></tr><tr><td>العدل</td><td>إعطاء كل ذي حق حقه</td><td>الظلم</td></tr></tbody></table>\n<p><strong>وسائل تحصيل محاسن الأخلاق</strong>:</p>\n<ol><li><strong>العلم والقصد</strong>: أن يعرف الخلق ويعتزم التخلق به.</li><li><strong>القدوة</strong>: النظر في أخلاق النبي صلى الله عليه وسلم وسيرة الصالحين.</li><li><strong>المجاهدة والتكرار</strong>: فالأخلاق تُكتسب بالتدريب حتى تصير هيئة راسخة.</li><li><strong>الصحبة الصالحة</strong>: فالمرء يتخلق بأخلاق من يجالس.</li><li><strong>محاسبة النفس</strong>: تقويم يومي أو أسبوعي.</li><li><strong>الدعاء</strong>: كان النبي صلى الله عليه وسلم يدعو: «واهدني لأحسن الأخلاق لا يهدي لأحسنها إلا أنت» (أخرجه مسلم، كتاب صلاة المسافرين، حديث رقم 771، في دعاء الاستفتاح).</li><li><strong>تجنب المثبّطات</strong>: صحبة السوء، والمحتوى الذي يزيّن السخرية والعنف.</li></ol>\n<blockquote><p><strong>قاعدة</strong>: الأخلاق تُكتسب بالتدريب كما تُكتسب المهارة؛ فمن أراد الحلم تدرّب على الصمت ثلاث ثوان قبل الجواب، ومن أراد الصدق التزم صدق حديثه في الصغير قبل الكبير.</p></blockquote>\n<p><strong>نشاط عملي</strong>: يختار كل متعلم خلقا واحدا لمدة أسبوعين، ويضع مؤشرا للقياس (عدد مرات الإخلال / عدد مرات التطبيق)، ويقدّم عرضا قصيرا للقسم عن تجربته.</p>\n<p><strong>مثال محلول 1</strong>: كيف يكون الخلق ميزانا للإيمان وهو عمل ظاهر؟ الجواب: لأن الخلق ثمرة العقيدة؛ فمن آمن بالله واليوم الآخر خشي أن يظلم أو يكذب، فصار الظاهر دليلا على صحة الباطن.</p>\n<p><strong>مثال محلول 2</strong>: تلميذ يقول: «طبعي عصبي ولا أستطيع تغييره». الجواب: الطبع أصل والخلق مكسوب؛ والشرع كلّف بما يُستطاع، والنبي صلى الله عليه وسلم علّم أصحابه علاجا عمليا للغضب، فمن جاهد نفسه بالتدريب تغيّر سلوكه وإن بقي طبعه سريع الانفعال.</p>\n<p><strong>مثال محلول 3</strong>: ما موقفك من زميل شتمك؟ الجواب: مقتضى الخلق الحسن العفو والإعراض عن الجاهلين: «وَأَعْرِضْ عَنِ الْجَاهِلِينَ»، مع حفظ الحق في الشكوى للإدارة إن تكرر الأذى؛ فالعفو ليس تنازلا عن كرامة.</p>\n<p><strong>السياق المغربي</strong>: تُعنى منظومة التربية بالمغرب بالتربية على القيم؛ وقد جعل منهاج التربية الإسلامية المنقّح <strong>التوحيد</strong> قيمة مركزية تتفرع عنها قيم المحبة والإحسان والاستقامة والحرية (مستجدات منهاج التربية الإسلامية). وتُترجم هذه القيم في الحياة المدرسية عبر أندية المؤسسة، والمبادرات التضامنية، وميثاق القسم، والاحتفاء بالمناسبات الدينية والوطنية.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>الخلق</td><td>هيئة راسخة في النفس تصدر عنها الأفعال بيسر</td></tr><tr><td>محاسن الأخلاق</td><td>الصفات الحسنة التي حسّنها الشرع وحمدها العقل</td></tr><tr><td>مكارم الأخلاق</td><td>أعلى مراتب الخلق الحسن</td></tr><tr><td>المجاهدة</td><td>تدريب النفس على الخلق حتى يصير عادة</td></tr><tr><td>محاسبة النفس</td><td>مراجعة الأعمال والأخلاق وتقويمها</td></tr><tr><td>التوحيد قيمة مركزية</td><td>جعل الإيمان بالله أصلا تتفرع عنه قيم المحبة والإحسان والاستقامة والحرية</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ اعتبار الأخلاق زينة زائدة عن الدين؛ والصواب أنها مقصد من مقاصد البعثة وميزان لكمال الإيمان.</li><li>⚠️ الاعتذار بالطبع «هكذا خُلقت»؛ والصواب أن الخلق يُكتسب بالمجاهدة والتدريب.</li><li>⚠️ الفصل بين التحصيل الدراسي والخلق؛ والصواب أن العلم بلا خلق ناقص الأثر.</li><li>⚠️ فهم العفو تنازلا عن الحق دائما؛ والصواب أنه ترك المؤاخذة مع بقاء الحق في المطالبة عند الحاجة.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف الخلق ومحاسن الأخلاق.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر حديثين في مكانة الأخلاق مع العزو الكامل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>أتمم: «خُذِ الْعَفْوَ ...» مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر ستا من محاسن الأخلاق ومقابل كل واحدة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>اذكر أربعا من وسائل تحصيل الأخلاق الحسنة.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>بيّن كيف تكون الأخلاق ميزانا لكمال الإيمان.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ناقش: «طبعي عصبي ولا أستطيع تغييره».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>أنجز جدولا (الخلق / معناه / مظهر عملي في القسم) لأربعة أخلاق.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>ما القيم المتفرعة عن قيمة التوحيد في منهاج المادة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>ما الفرق بين العفو والذل؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: تلميذ متفوق في النتائج لكنه يسخر من زملائه الضعفاء. حرّر عشرة أسطر تناصحه فيها بالدليل وتقترح خطة تصحيح.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: «الأخلاق تُكتسب بالتدريب كما تُكتسب المهارة».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز خطة شخصية للتخلق بخلق واحد لمدة أسبوعين (الخلق / الالتزامات / مؤشر القياس / التقويم).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن دور نوادي المؤسسة وميثاق القسم في التربية على محاسن الأخلاق.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"الخلق","v":"هيئة راسخة في النفس تصدر عنها الأفعال بيسر"},{"r":"محاسن الأخلاق","v":"الصفات الحسنة التي حسّنها الشرع وحمدها العقل"},{"r":"مكارم الأخلاق","v":"أعلى مراتب الخلق الحسن"},{"r":"المجاهدة","v":"تدريب النفس على الخلق حتى يصير عادة"},{"r":"محاسبة النفس","v":"مراجعة الأعمال والأخلاق وتقويمها"},{"r":"التوحيد قيمة مركزية","v":"جعل الإيمان بالله أصلا تتفرع عنه قيم المحبة والإحسان والاستقامة والحرية"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — عرّف الخلق، واذكر ثلاثة أوجه لمكانة الأخلاق في الإسلام مع نص لكل وجه والعزو.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — أنجز جدولا لخمسة أخلاق (الخلق / معناه / مقابله المذموم / مظهر عملي).</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: كثرت في مؤسستك ظاهرة الألقاب الساخرة بين التلاميذ. حرّر اثني عشر سطرا تبيّن الحكم الشرعي بالاستدلال، وتقترح مشروعا صفّيا لمعالجة الظاهرة مع مؤشرات لقياس نجاحه.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 1,5 ن، كل وجه بنصه وعزوه 1,5 ن.</li><li>التمرين الثاني: كل سطر مكتمل 1,2 ن.</li><li>التمرين الثالث: بيان الحكم مع الاستدلال 3 ن، المشروع الصفي 3 ن، مؤشرات القياس 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>\n<p>## الوحدة الرابعة — الدروس EI20 إلى EI26</p>\n<p>تُتمّ الوحدة الرابعة الدورة الرابعة من المداخل الستة، وتُختم بالشطر الثالث من سورة لقمان. وموضوعاتها: وصايا لقمان، والقرآن هدى ورحمة، ودار الأرقم، وأحكام السهو وقضاء الفوائت، وحق البيئة، وحديث الفقيه، ثم خواتيم سورة لقمان.</p>"}},
{"id":"islamique-ei20","domaine":"islamique","unite":20,"theme":"الوحدة الرابعة — الدروس EI20 إلى EI26","tag":"EI20","langue":"ar","titre":"مدخل التزكية (القرآن الكريم) 5: الشطر الثاني من سورة لقمان (الآية 12 إلى 21)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يرتّل المتعلم(ة) الآيات 12-21 من سورة لقمان ترتيلا سليما ويحفظها.","أن يشرح مفردات المقطع.","أن يعدّد وصايا لقمان لابنه ويرتّبها.","أن يبيّن مكانة الشكر والتوحيد وبر الوالدين في المقطع.","أن يستثمر الوصايا في سلوكه اليومي داخل المؤسسة والأسرة."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: طُلب من تلاميذ القسم أن يكتب كل واحد ثلاث نصائح يقدّمها لأخيه الصغير. ثم نقرأ وصايا لقمان الحكيم لابنه لنرى منهج النصح في القرآن: من أين يبدأ؟ وبأي أسلوب؟</p>\n<p><strong>نص المقطع (12-21)</strong>:</p>\n<blockquote><p>«وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ أَنِ اشْكُرْ لِلَّهِ ۚ وَمَنْ يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ ۖ وَمَنْ كَفَرَ فَإِنَّ اللَّهَ غَنِيٌّ حَمِيدٌ (12) وَإِذْ قَالَ لُقْمَانُ لِابْنِهِ وَهُوَ يَعِظُهُ يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ ۖ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ (13) وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حَمَلَتْهُ أُمُّهُ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَالُهُ فِي عَامَيْنِ أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ (14) وَإِنْ جَاهَدَاكَ عَلَىٰ أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا ۖ وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا ۖ وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ ۚ ثُمَّ إِلَيَّ مَرْجِعُكُمْ فَأُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ (15) يَا بُنَيَّ إِنَّهَا إِنْ تَكُ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ فَتَكُنْ فِي صَخْرَةٍ أَوْ فِي السَّمَاوَاتِ أَوْ فِي الْأَرْضِ يَأْتِ بِهَا اللَّهُ ۚ إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ (16) يَا بُنَيَّ أَقِمِ الصَّلَاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنْكَرِ وَاصْبِرْ عَلَىٰ مَا أَصَابَكَ ۖ إِنَّ ذَٰلِكَ مِنْ عَزْمِ الْأُمُورِ (17) وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا ۖ إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ (18) وَاقْصِدْ فِي مَشْيِكَ وَاغْضُضْ مِنْ صَوْتِكَ ۚ إِنَّ أَنْكَرَ الْأَصْوَاتِ لَصَوْتُ الْحَمِيرِ (19) أَلَمْ تَرَوْا أَنَّ اللَّهَ سَخَّرَ لَكُمْ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظَاهِرَةً وَبَاطِنَةً ۗ وَمِنَ النَّاسِ مَنْ يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَابٍ مُنِيرٍ (20) وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنْزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا ۚ أَوَلَوْ كَانَ الشَّيْطَانُ يَدْعُوهُمْ إِلَىٰ عَذَابِ السَّعِيرِ (21)» — سورة لقمان، الآيات 12-21.</p></blockquote>\n<p><strong>شرح المفردات</strong>:</p>\n<table><thead><tr><th>الكلمة</th><th>الشرح</th></tr></thead><tbody><tr><td>الحكمة</td><td>العلم النافع المقرون بالعمل وإصابة الصواب في القول والفعل</td></tr><tr><td>غني حميد</td><td>لا يحتاج إلى شكر أحد، ومحمود في ذاته</td></tr><tr><td>يعظه</td><td>ينصحه نصحا يرقّق القلب</td></tr><tr><td>يا بنيّ</td><td>نداء تصغير للتحبب والتلطف</td></tr><tr><td>وهنا على وهن</td><td>ضعفا يتزايد مع الحمل</td></tr><tr><td>فصاله</td><td>فطامه عن الرضاع</td></tr><tr><td>أناب إليّ</td><td>رجع إليّ بالتوبة والطاعة</td></tr><tr><td>مثقال حبة من خردل</td><td>أصغر مقدار يُتصوّر، والخردل حبّ دقيق جدا</td></tr><tr><td>لطيف خبير</td><td>عالم بدقائق الأمور خبير بخفاياها</td></tr><tr><td>عزم الأمور</td><td>ما يحتاج إلى قوة عزيمة وصبر</td></tr><tr><td>لا تصعّر خدك</td><td>لا تُعرض بوجهك تكبّرا</td></tr><tr><td>مرحا</td><td>تبخترا وخيلاء</td></tr><tr><td>مختال فخور</td><td>متكبر في مشيه مفتخر على الناس</td></tr><tr><td>اقصد في مشيك</td><td>توسّط فيه بلا إسراع مفرط ولا تبختر</td></tr><tr><td>اغضض من صوتك</td><td>اخفضه ولا ترفعه بلا حاجة</td></tr><tr><td>أسبغ</td><td>أتمّ ووسّع</td></tr><tr><td>كتاب منير</td><td>وحي مبين يُهتدى به</td></tr></tbody></table>\n<p><strong>من هو لقمان؟</strong> رجل صالح آتاه الله الحكمة، وليس نبيا على قول جمهور المفسرين، وذُكرت وصاياه في القرآن لأنها حكمة خالصة صالحة لكل زمان.</p>\n<p><strong>وصايا لقمان مرتّبة</strong>:</p>\n<ol><li><strong>توحيد الله والنهي عن الشرك</strong>: «يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ ۖ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ» — فبدأ بالأصل الأكبر، وسمّى الشرك ظلما لأنه وضع الشيء في غير موضعه.</li><li><strong>الإيمان بعلم الله المحيط ومراقبته</strong>: «إِنْ تَكُ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ... يَأْتِ بِهَا اللَّهُ» — فالمراقبة تصنع الأمانة.</li><li><strong>إقامة الصلاة</strong>: صلة دائمة بالله.</li><li><strong>الأمر بالمعروف والنهي عن المنكر</strong>: مسؤولية اجتماعية.</li><li><strong>الصبر على ما يصيبه</strong>: لأن هذه المهمة تكلّف ثمنا، وهي «مِنْ عَزْمِ الْأُمُورِ».</li><li><strong>التواضع في المعاملة</strong>: «وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ».</li><li><strong>التواضع في الهيئة والمشي</strong>: «وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا»، و«وَاقْصِدْ فِي مَشْيِكَ».</li><li><strong>أدب الصوت</strong>: «وَاغْضُضْ مِنْ صَوْتِكَ».</li></ol>\n<p><strong>وصية الله المعترضة (14-15)</strong>: أدخل الله بين وصايا لقمان وصيته هو ببر الوالدين، تعظيما لحقهما وربطا للبر بشكر الله: «أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ». ثم قيّد الطاعة بغير المعصية: «وَإِنْ جَاهَدَاكَ عَلَىٰ أَنْ تُشْرِكَ بِي... فَلَا تُطِعْهُمَا ۖ وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا»، فجمع بين الثبات على الدين وحسن الصحبة.</p>\n<p><strong>قضية التقليد الأعمى (20-21)</strong>: يذكّر المقطع بتسخير ما في السماوات والأرض وإسباغ النعم الظاهرة والباطنة، ثم يعيب من يجادل في الله بغير علم، ومن يرفض الوحي بحجة أنه وجد آباءه على غيره: «بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا». والعبرة: العادة والموروث ليسا دليلا في ذاتهما، والمعيار هو ما أنزل الله.</p>\n<blockquote><p><strong>منهج النصح المستفاد</strong>: بدأ لقمان بالنداء المحبب «يا بنيّ»، ثم بالأهم (العقيدة)، ثم بالشعائر، ثم بالسلوك الاجتماعي، ثم بالهيئة الظاهرة؛ وعلّل كل وصية بحكمة. فالنصح الناجح يبدأ بالمحبة ويرتّب الأولويات ويقنع بالتعليل.</p></blockquote>\n<p><strong>مثال محلول 1</strong>: لماذا سمّى الشرك ظلما عظيما؟ الجواب: لأن الظلم وضع الشيء في غير موضعه، وصرف العبادة لغير الخالق أعظم صور ذلك؛ وفيه ظلم للنفس بتعريضها للخسران.</p>\n<p><strong>مثال محلول 2</strong>: ما وجه المناسبة بين خفض الصوت وذكر صوت الحمير؟ الجواب: تشبيه منفّر يبيّن أن رفع الصوت بلا حاجة سلوك مذموم، فالكلام الحسن بقوة معناه لا بعلوّ نبرته.</p>\n<p><strong>مثال محلول 3</strong>: كيف تُفهم الوصايا في حياة التلميذ؟ الجواب: التوحيد يمنعه من التعلق بالتمائم والخرافات، والمراقبة تمنعه من الغش، والصلاة تنظم وقته، والأمر بالمعروف يجعله يمنع التنمر في قسمه، والصبر يعينه على المراجعة، والتواضع يحفظه من الاستعلاء عند النجاح، وأدب الصوت يحسّن سلوكه في القسم والحي.</p>\n<p><strong>السياق المغربي</strong>: وصايا لقمان من أكثر النصوص المستحضرة في التربية الأسرية المغربية، وتُروى في الحكم والأمثال الشعبية الداعية إلى التواضع وخفض الصوت وبر الوالدين. وتنسجم مع القيم التي يقوم عليها منهاج المادة: المحبة والإحسان والاستقامة والحرية، متفرعة عن قيمة التوحيد (مستجدات منهاج التربية الإسلامية).</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<ul><li>الحكمة عطاء من الله، وأول شعبها الشكر: «أَنِ اشْكُرْ لِلَّهِ».</li><li>لقمان رجل صالح حكيم، وليس نبيا على قول الجمهور.</li><li>الوصايا: التوحيد، مراقبة الله، الصلاة، الأمر بالمعروف والنهي عن المنكر، الصبر، التواضع، أدب المشي، أدب الصوت.</li><li>وصية الله ببر الوالدين معترضة بين وصايا لقمان تعظيما لحقهما.</li><li>الطاعة مقيدة: لا طاعة في معصية، مع بقاء حسن الصحبة.</li><li>الموروث ليس دليلا: «بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا» موقف مذموم.</li></ul>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ القول إن لقمان نبي؛ والصواب أن جمهور المفسرين على أنه رجل صالح حكيم.</li><li>⚠️ فهم «فَلَا تُطِعْهُمَا» إذنا بالجفاء؛ والصواب أن الآية نفسها أمرت بحسن الصحبة.</li><li>⚠️ حصر التواضع في المشي؛ والصواب أنه خلق يشمل المعاملة والقول والهيئة.</li><li>⚠️ الخلط بين احترام تقاليد الأسرة وبين التقليد الأعمى المخالف للوحي؛ والمعيار ما أنزل الله.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>اكتب الآيتين 13 و17 من سورة لقمان مع الشكل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اشرح: الحكمة، وهنا على وهن، عزم الأمور، لا تصعّر خدك، اغضض من صوتك.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>عدّد وصايا لقمان لابنه.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>من هو لقمان؟ وما القول الراجح في نبوته؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>أتمم: «وَاقْصِدْ فِي مَشْيِكَ ...» مع رقم الآية.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>لماذا بدأ لقمان وصاياه بالنهي عن الشرك؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>بيّن سبب اعتراض وصية الله ببر الوالدين بين وصايا لقمان.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>استخرج من الآية 15 ضابط طاعة الوالدين.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>أنجز جدولا (الوصية / نوعها: عقدية أم تعبدية أم سلوكية / مظهرها في حياتك).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>ما موقف القرآن من حجة «وَجَدْنَا عَلَيْهِ آبَاءَنَا»؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: تريد أن تنصح أخاك الصغير الذي يرفع صوته ويتكبر على أصدقائه. حرّر عشرة أسطر تطبّق فيها منهج لقمان في النصح.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف تصنع مراقبة الله (الآية 16) أمانة التلميذ في الفروض؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>قارن بين التواضع والذلة، وبين الثقة بالنفس والكِبر.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن النعم الظاهرة والباطنة في قوله «وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظَاهِرَةً وَبَاطِنَةً» مع أمثلة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"الحكمة","v":"العلم النافع المقرون بالعمل وإصابة الصواب في القول والفعل"},{"r":"غني حميد","v":"لا يحتاج إلى شكر أحد، ومحمود في ذاته"},{"r":"يعظه","v":"ينصحه نصحا يرقّق القلب"},{"r":"يا بنيّ","v":"نداء تصغير للتحبب والتلطف"},{"r":"وهنا على وهن","v":"ضعفا يتزايد مع الحمل"},{"r":"فصاله","v":"فطامه عن الرضاع"},{"r":"أناب إليّ","v":"رجع إليّ بالتوبة والطاعة"},{"r":"مثقال حبة من خردل","v":"أصغر مقدار يُتصوّر، والخردل حبّ دقيق جدا"},{"r":"لطيف خبير","v":"عالم بدقائق الأمور خبير بخفاياها"},{"r":"عزم الأمور","v":"ما يحتاج إلى قوة عزيمة وصبر"},{"r":"لا تصعّر خدك","v":"لا تُعرض بوجهك تكبّرا"},{"r":"مرحا","v":"تبخترا وخيلاء"},{"r":"مختال فخور","v":"متكبر في مشيه مفتخر على الناس"},{"r":"اقصد في مشيك","v":"توسّط فيه بلا إسراع مفرط ولا تبختر"},{"r":"اغضض من صوتك","v":"اخفضه ولا ترفعه بلا حاجة"},{"r":"أسبغ","v":"أتمّ ووسّع"},{"r":"كتاب منير","v":"وحي مبين يُهتدى به"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — اكتب الآيات 17-19 مع الشكل، واشرح: عزم الأمور، مرحا، اغضض من صوتك.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — عدّد ست وصايا من وصايا لقمان، وصنّفها إلى عقدية وتعبدية وسلوكية.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: ينصح زميل زميلا بأسلوب قاسٍ فيزيد إصراره على الخطأ. حرّر عشرة أسطر تصحح الأسلوب على منهج لقمان في النصح، مع الاستشهاد.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: الآيات 4 ن، الشرح 3 ن.</li><li>التمرين الثاني: الوصايا 3 ن، التصنيف 3 ن.</li><li>التمرين الثالث: منهج النصح 3 ن، الاستشهاد مع العزو 2 ن، الأسلوب البديل 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei21","domaine":"islamique","unite":21,"theme":"الوحدة الرابعة — الدروس EI20 إلى EI26","tag":"EI21","langue":"ar","titre":"مدخل التزكية (العقيدة) 4: القرآن الكريم هدى ورحمة للعالمين","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) القرآن الكريم تعريفا اصطلاحيا دقيقا.","أن يبيّن معنى كون القرآن هدى ورحمة، ويميّز بين الهدى والرحمة.","أن يستدل على عمومه للعالمين بنصوص مع العزو.","أن يعدّد مجالات هدى القرآن: العقيدة، والعبادة، والأخلاق، والمعاملات، والتشريع.","أن يحدد واجبه نحو القرآن: التلاوة، والتدبر، والحفظ، والعمل، والأدب معه."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: يحفظ تلميذ سورا كثيرة ويجيد الترتيل، لكنه يغش في الفروض ويسيء لزملائه. فما معنى أن يكون القرآن هدى ورحمة إذا لم يظهر أثره؟</p>\n<p><strong>تعريف القرآن الكريم</strong>:</p>\n<blockquote><p><strong>القرآن الكريم</strong>: كلام الله المنزّل على نبيه محمد صلى الله عليه وسلم بواسطة جبريل عليه السلام، المنقول إلينا بالتواتر، المتعبَّد بتلاوته، المكتوب في المصاحف، المبدوء بسورة الفاتحة والمختوم بسورة الناس.</p></blockquote>\n<p><strong>معنى الهدى والرحمة</strong>:</p>\n<table><thead><tr><th>الوصف</th><th>معناه</th><th>مظهره</th></tr></thead><tbody><tr><td>هدى</td><td>بيان وإرشاد إلى الحق في العقيدة والعمل</td><td>معرفة الله، وأحكام العبادات، وميزان الحلال والحرام</td></tr><tr><td>رحمة</td><td>لطف وتيسير ورفع للحرج وشفاء للقلوب</td><td>التخفيف والتدرج، والبشارة، والطمأنينة، والعفو</td></tr></tbody></table>\n<p>فالهدى يخصّ العقل بالبيان، والرحمة تخصّ القلب والحياة بالتيسير؛ ولا ينفصلان: هدى بلا رحمة يصير تشددا، ورحمة بلا هدى تصير تسيّبا.</p>\n<p><strong>الأدلة على أنه هدى ورحمة</strong>: «شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ هُدًى لِلنَّاسِ وَبَيِّنَاتٍ مِنَ الْهُدَىٰ وَالْفُرْقَانِ» (سورة البقرة، الآية 185)، و«وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ» (سورة النحل، الآية 89)، و«يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ» (سورة يونس، الآية 57)، و«هُدًى وَرَحْمَةً لِلْمُحْسِنِينَ» (سورة لقمان، الآية 3).</p>\n<p><strong>الأدلة على عمومه للعالمين</strong>: «وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ» (سورة الأنبياء، الآية 107)، و«تَبَارَكَ الَّذِي نَزَّلَ الْفُرْقَانَ عَلَىٰ عَبْدِهِ لِيَكُونَ لِلْعَالَمِينَ نَذِيرًا» (سورة الفرقان، الآية 1)، و«وَمَا هُوَ إِلَّا ذِكْرٌ لِلْعَالَمِينَ» (سورة القلم، الآية 52).</p>\n<p><strong>مجالات هدى القرآن</strong>:</p>\n<ol><li><strong>العقيدة</strong>: توحيد الله، والإيمان بالغيب والرسل والبعث.</li><li><strong>العبادة</strong>: بيان الشعائر ومقاصدها.</li><li><strong>الأخلاق</strong>: الصدق، والعدل، والرحمة، والحياء.</li><li><strong>المعاملات</strong>: البيع، والدين، والوصية، والأمانة، وحفظ الحقوق.</li><li><strong>الأسرة والمجتمع</strong>: بر الوالدين، وحقوق الزوجين، وصلة الرحم، وحق الجار.</li><li><strong>التشريع والحكم</strong>: العدل، والشورى، وحفظ النفس والمال والعرض.</li><li><strong>الكون والمعرفة</strong>: الدعوة إلى النظر والتفكر والعلم.</li></ol>\n<p><strong>مظاهر الرحمة في القرآن</strong>: سعة العفو والتوبة، والتخفيف بالرخص عند العذر (كالفطر للمريض والمسافر)، والتدرج في التشريع، ورفع الحرج، ومخاطبة الناس بما يطيقون: «لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا» (سورة البقرة، الآية 286)، والشفاء النفسي والطمأنينة.</p>\n<p><strong>واجبنا نحو القرآن</strong>:</p>\n<ol><li><strong>الإيمان</strong> بأنه كلام الله وتعظيمه.</li><li><strong>التلاوة الصحيحة</strong> مع أحكام التجويد.</li><li><strong>الحفظ</strong> بحسب الطاقة.</li><li><strong>التدبر والفهم</strong> بالرجوع إلى التفاسير المعتمدة.</li><li><strong>العمل</strong> به، وهو المقصد الأعظم.</li><li><strong>التعليم والدعوة</strong> إليه بالحسنى.</li><li><strong>الأدب معه</strong>: الطهارة عند مسّه، وحسن حمله وحفظه، والإنصات عند تلاوته: «وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا» (سورة الأعراف، الآية 204).</li></ol>\n<p><strong>السياق المغربي</strong>: للقرآن الكريم في المغرب مكانة راسخة: تُقرأ رواية ورش عن نافع، وتُعتنى بها في المصحف المحمدي الذي أشرفت على إصداره المؤسسة المحمدية للعلماء بالمغرب، وتنتشر الكتاتيب القرآنية ومدارس التعليم العتيق، وتُنظّم مسابقات وطنية في الحفظ والترتيل، وتُقام الأحزاب القرآنية في المساجد. ويأتي هذا ضمن الثوابت الدينية الوطنية بإشراف إمارة المؤمنين ووزارة الأوقاف والشؤون الإسلامية.</p>\n<p><strong>مثال محلول 1</strong>: كيف يكون القرآن هدى لغير المسلم؟ الجواب: هو هدى في أصل خطابه لكل الناس لأنه دعوة عامة: «لِيَكُونَ لِلْعَالَمِينَ نَذِيرًا»؛ وأما الانتفاع الكامل فمرتبط بالإيمان والاستجابة.</p>\n<p><strong>مثال محلول 2</strong>: كيف نجيب من يقول: «القرآن كتاب قديم لا يصلح لعصرنا»؟ الجواب: يُميّز بين الأحكام القطعية الثابتة (كالعدل وحرمة الظلم) وبين الوسائل والاجتهادات المتغيرة؛ فالمقاصد ثابتة والوسائل تتجدد باجتهاد أهل العلم، وهذا سرّ صلاحه لكل زمان.</p>\n<p><strong>مثال محلول 3</strong>: ما الفرق بين حافظ لا يعمل وقارئ قليل الحفظ يعمل؟ الجواب: الحفظ فضل عظيم، لكن المقصد العمل؛ فمن حفظ وعمل جمع الفضلين، ومن حفظ ولم يعمل فقد فرّط في المقصد الأعظم.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>التواتر</td><td>نقل الجمع عن الجمع بما يستحيل معه التواطؤ على الكذب</td></tr><tr><td>المتعبَّد بتلاوته</td><td>تلاوته عبادة يُثاب عليها</td></tr><tr><td>الفرقان</td><td>من أسماء القرآن، لأنه يفرق بين الحق والباطل</td></tr><tr><td>رواية ورش</td><td>رواية قرآنية عن نافع المدني، وهي المعتمدة بالمغرب</td></tr><tr><td>المصحف المحمدي</td><td>مصحف مغربي بإشراف المؤسسة المحمدية للعلماء</td></tr><tr><td>رفع الحرج</td><td>التخفيف عن المكلّف عند العذر</td></tr><tr><td>التدبر</td><td>التأمل في معاني الآيات للعمل بها</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الاقتصار على الحفظ والترتيل دون العمل؛ والصواب أن المقصد الأعظم العمل.</li><li>⚠️ الظن أن الرحمة تعني إلغاء الأحكام؛ والصواب أنها التيسير ورفع الحرج مع بقاء الحكم.</li><li>⚠️ تفسير القرآن بالرأي المجرد؛ والصواب الرجوع إلى التفاسير المعتمدة وأهل العلم.</li><li>⚠️ الخلط بين ثوابت الأحكام ومتغيرات الوسائل والاجتهاد.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف القرآن الكريم تعريفا اصطلاحيا.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>ما معنى كون القرآن هدى؟ وما معنى كونه رحمة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر آيتين تدلان على أنه هدى ورحمة مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر آيتين تدلان على عمومه للعالمين مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>عدّد خمسة من مجالات هدى القرآن.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>اذكر أربعة من مظاهر الرحمة في القرآن مع مثال لكل مظهر.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>اذكر خمسة من واجباتنا نحو القرآن الكريم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>ما الرواية المعتمدة في المغرب؟ واذكر ثلاثة من مظاهر العناية بالقرآن فيه.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>لماذا لا ينفصل الهدى عن الرحمة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>أنجز جدولا (المجال / مثال من القرآن / أثره في حياة التلميذ) لثلاثة مجالات.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: قال زميل: «القرآن كتاب قديم لا يصلح لعصرنا». حرّر عشرة أسطر تناقش المقولة بهدوء وبالدليل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: العلاقة بين حفظ القرآن والعمل به.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>اكتب برنامجا شخصيا أسبوعيا لعلاقتك بالقرآن (التلاوة / الحفظ / التدبر / العمل) مع مؤشرات القياس.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن أثر الكتاتيب القرآنية والمسابقات القرآنية في المغرب في تربية الناشئة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"التواتر","v":"نقل الجمع عن الجمع بما يستحيل معه التواطؤ على الكذب"},{"r":"المتعبَّد بتلاوته","v":"تلاوته عبادة يُثاب عليها"},{"r":"الفرقان","v":"من أسماء القرآن، لأنه يفرق بين الحق والباطل"},{"r":"رواية ورش","v":"رواية قرآنية عن نافع المدني، وهي المعتمدة بالمغرب"},{"r":"المصحف المحمدي","v":"مصحف مغربي بإشراف المؤسسة المحمدية للعلماء"},{"r":"رفع الحرج","v":"التخفيف عن المكلّف عند العذر"},{"r":"التدبر","v":"التأمل في معاني الآيات للعمل بها"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — عرّف القرآن الكريم، وبيّن معنى كونه هدى ورحمة مع آية لكل وصف والعزو.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — عدّد خمسة من مجالات هدى القرآن مع مثال لكل مجال، وأربعة من واجباتنا نحوه.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: تلميذ حافظ لأجزاء من القرآن لكنه يغش في الفروض ويقول: «الحفظ يكفي». حرّر اثني عشر سطرا تصحح تصوره بالدليل، وتقترح برنامجا يربط الحفظ بالعمل.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 2 ن، المعنيان 2 ن، الآيتان مع العزو 2 ن.</li><li>التمرين الثاني: المجالات وأمثلتها 4 ن، الواجبات 2 ن.</li><li>التمرين الثالث: تصحيح التصور 3 ن، الاستشهاد مع العزو 2 ن، البرنامج العملي 2 ن، اللغة 1 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei22","domaine":"islamique","unite":22,"theme":"الوحدة الرابعة — الدروس EI20 إلى EI26","tag":"EI22","langue":"ar","titre":"مدخل الاقتداء 4: دار الأرقم (التآلف والتشاور)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) دار الأرقم ويحدد موقعها ودورها.","أن يبيّن وظائف دار الأرقم في مرحلة الدعوة السرية.","أن يستخرج قيمتي التآلف والتشاور من هذه التجربة.","أن يستدل على مشروعية الشورى والتآلف بنصوص مع العزو.","أن يقترح تطبيقات لهذه القيم في القسم والمؤسسة."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: أراد تلاميذ القسم إنشاء نادٍ للقراءة فاختلفوا: أين نجتمع؟ ومن يقرر؟ فتفرقوا. فكيف نظّم النبي صلى الله عليه وسلم جماعة المسلمين الأولى في مرحلة أصعب بكثير؟</p>\n<p><strong>دار الأرقم: التعريف والموقع</strong>: هي دار الأرقم بن أبي الأرقم المخزومي رضي الله عنه، وكانت عند الصفا بمكة، اتخذها النبي صلى الله عليه وسلم مقرا للدعوة والتكوين في مرحلة الاستضعاف، فكان يجتمع فيها بأصحابه سرا، ويُقرئهم القرآن، ويعلّمهم أحكام الدين، ويُسلم فيها من أسلم. وقد أسلم فيها عمر بن الخطاب رضي الله عنه في المشهور من الروايات.</p>\n<p><strong>وظائف دار الأرقم</strong>:</p>\n<table><thead><tr><th>الوظيفة</th><th>مظهرها</th></tr></thead><tbody><tr><td>التعليم والتكوين</td><td>إقراء القرآن، وتعليم أحكام الدين والأخلاق</td></tr><tr><td>التربية والتزكية</td><td>الصلاة والذكر وتربية النفوس على الصبر</td></tr><tr><td>التنظيم والتشاور</td><td>تدارس أحوال الدعوة واتخاذ القرار بالمشاورة</td></tr><tr><td>الحماية والأمن</td><td>مكان آمن بعيد عن أعين قريش لقلة الشبهة فيه</td></tr><tr><td>التآلف وبناء الأخوّة</td><td>التقاء الأشراف والموالي والنساء والرجال في مكان واحد</td></tr><tr><td>الاحتضان النفسي</td><td>تخفيف وحدة المسلم المستضعف بإحساسه بالجماعة</td></tr></tbody></table>\n<p><strong>قيمة التآلف</strong>: الأخوّة التي رُبّي عليها المسلمون في دار الأرقم أذابت الفوارق: أبو بكر التاجر الشريف، وبلال المولى، وعمار وأمه، وعثمان بن عفان، ومصعب بن عمير الفتى المترف، اجتمعوا على عقيدة واحدة. قال تعالى: «وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا» (سورة آل عمران، الآية 103)، وقال النبي صلى الله عليه وسلم: «مثل المؤمنين في توادّهم وتراحمهم وتعاطفهم كمثل الجسد؛ إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى» (أخرجه مسلم، كتاب البر والصلة، حديث رقم 2586).</p>\n<p><strong>قيمة التشاور</strong>: الشورى أصل في الإسلام: «وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ» (سورة الشورى، الآية 38)، و«وَشَاوِرْهُمْ فِي الْأَمْرِ» (سورة آل عمران، الآية 159). وقد شاور النبي صلى الله عليه وسلم أصحابه في مواقف كثيرة، وابتدأ ذلك في المرحلة المكية بتدارس أمور الدعوة، ثم ظهر في بدر والخندق والحديبية.</p>\n<blockquote><p><strong>فائدة تربوية</strong>: الشورى ليست تنازلا من القائد بل قوة له: تُنضج الرأي، وتكشف الأخطاء، وتصنع التزاما جماعيا بالقرار، وتربّي الأفراد على المسؤولية.</p></blockquote>\n<p><strong>الدروس المستفادة من التجربة</strong>:</p>\n<ol><li>أهمية المكان المنظّم للعمل التربوي (فضاء يجمع ويكوّن ويحمي).</li><li>الجمع بين العلم والتربية، فلا تكوين بلا تزكية.</li><li>الأخوّة تُذيب الفوارق الاجتماعية.</li><li>التخطيط والسرّية في مرحلتهما ليسا خوفا بل حكمة.</li><li>الشورى منهج قيادة لا شعار.</li><li>صناعة الكوادر: من دار الأرقم خرج من حمل الدعوة إلى المدينة والحبشة.</li></ol>\n<p><strong>السياق المغربي</strong>: تتحقق قيمة التآلف والتشاور في المؤسسات التعليمية المغربية عبر مجالس المؤسسة، ومجلس القسم، وأندية الحياة المدرسية، ومكتب جمعية أمهات وآباء وأولياء التلاميذ. وفي المجال الديني تُمثّل المجالس العلمية المحلية والمجلس العلمي الأعلى نموذجا للاجتهاد الجماعي المؤسسي بدلا من الفتوى الفردية.</p>\n<p><strong>مثال محلول 1</strong>: لماذا اختار النبي صلى الله عليه وسلم دار الأرقم بالخصوص؟ الجواب: لأن الأرقم رضي الله عنه من بني مخزوم، وهم من خصوم بني هاشم، فلم تكن قريش تتوقع اجتماع المسلمين في داره؛ وهذا من حسن التدبير.</p>\n<p><strong>مثال محلول 2</strong>: كيف نطبّق الشورى في نادي القسم؟ الجواب: بجمع الآراء كتابة، ومناقشتها، والتصويت، وتوزيع المهام، وتقويم النتائج دوريا، مع احترام رأي الأقلية وحفظ حقها في التعبير.</p>\n<p><strong>مثال محلول 3</strong>: ما الفرق بين التآلف والمجاملة؟ الجواب: التآلف رحمة صادقة تظهر في المساعدة والنصح والصدق؛ والمجاملة كلام حسن بلا أثر، وقد تُسكت عن الخطأ.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>دار الأرقم</td><td>دار الأرقم بن أبي الأرقم عند الصفا بمكة، مقر الدعوة والتكوين</td></tr><tr><td>الدعوة السرية</td><td>مرحلة أولى من الدعوة اقتضتها ظروف الاستضعاف</td></tr><tr><td>التآلف</td><td>تحقق المحبة والأخوّة بين أفراد الجماعة</td></tr><tr><td>التشاور</td><td>تبادل الرأي للوصول إلى القرار الأصوب</td></tr><tr><td>التزكية</td><td>تربية النفس وتطهيرها</td></tr><tr><td>صناعة الكوادر</td><td>تكوين أفراد قادرين على حمل المسؤولية</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الظن أن الدعوة السرية خوف أو ضعف؛ والصواب أنها حكمة تدبير في مرحلة الاستضعاف.</li><li>⚠️ اختصار دار الأرقم في كونها مكان اجتماع؛ والصواب أنها مؤسسة تعليمية وتربوية وتنظيمية.</li><li>⚠️ فهم الشورى استفتاء بلا مسؤولية؛ والصواب أنها مشاركة في القرار مع تحمّل نتائجه.</li><li>⚠️ حصر التآلف في المشاعر؛ والصواب أنه يظهر في العمل والمساعدة والصدق.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>ما دار الأرقم؟ وأين كانت؟ ومن صاحبها؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر أربعا من وظائف دار الأرقم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر آية وحديثا في التآلف مع العزو الكامل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر آيتين في الشورى مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>من أشهر من أسلم في دار الأرقم؟</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>لماذا اختار النبي صلى الله عليه وسلم دار الأرقم مقرا للدعوة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>بيّن كيف أذابت دار الأرقم الفوارق الاجتماعية بأمثلة من الصحابة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>اذكر أربعة من فوائد الشورى.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>ما الفرق بين التآلف والمجاملة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>أنجز جدولا (الوظيفة / مظهرها في دار الأرقم / نظيرها في مؤسستك).</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: يريد تلاميذ قسمك إنشاء نادٍ لكنهم اختلفوا وتفرقوا. حرّر عشرة أسطر تقترح فيها منهجا مستفادا من دار الأرقم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف تكون الشورى قوة للقائد لا ضعفا؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>استخرج من تجربة دار الأرقم خمسة دروس تنظيمية قابلة للتطبيق في الحياة المدرسية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن دور مجالس المؤسسة والأندية في تربية التلاميذ على التشاور والمسؤولية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"دار الأرقم","v":"دار الأرقم بن أبي الأرقم عند الصفا بمكة، مقر الدعوة والتكوين"},{"r":"الدعوة السرية","v":"مرحلة أولى من الدعوة اقتضتها ظروف الاستضعاف"},{"r":"التآلف","v":"تحقق المحبة والأخوّة بين أفراد الجماعة"},{"r":"التشاور","v":"تبادل الرأي للوصول إلى القرار الأصوب"},{"r":"التزكية","v":"تربية النفس وتطهيرها"},{"r":"صناعة الكوادر","v":"تكوين أفراد قادرين على حمل المسؤولية"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — ما دار الأرقم؟ واذكر أربعا من وظائفها، ومن أشهر من أسلم فيها.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — استشهد بنصين في التآلف ونصين في الشورى مع العزو الكامل، وبيّن دلالة كل نص.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: تعثّر نادي مؤسستك بسبب غياب التشاور وتفرق الأعضاء. حرّر اثني عشر سطرا تقترح فيها خطة إصلاح مستفادة من تجربة دار الأرقم، مع مؤشرات نجاح.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 2 ن، الوظائف 3 ن، الصحابي 1 ن.</li><li>التمرين الثاني: كل نص مع عزوه ودلالته 1,5 ن.</li><li>التمرين الثالث: خطة الإصلاح 4 ن، الاستفادة من التجربة بالاستشهاد 2 ن، مؤشرات النجاح 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei23","domaine":"islamique","unite":23,"theme":"الوحدة الرابعة — الدروس EI20 إلى EI26","tag":"EI23","langue":"ar","titre":"مدخل الاستجابة 4: الصلاة (أحكام السهو، قضاء الفوائت، أحكام المسبوق)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) سجود السهو ويبيّن حكمه ومواضعه على المذهب المالكي.","أن يميّز بين سجود السهو قبل السلام وبعده.","أن يبيّن حكم قضاء الفوائت وترتيبها.","أن يعرّف المسبوق ويبيّن أحكامه.","أن يحلّ نوازل عملية في هذه الأحكام مع ردّ التفاصيل إلى أهل العلم."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: ثلاث حالات في القسم: تلميذ نسي التشهد الأول، وتلميذ استيقظ متأخرا فوجد الصبح قد خرج وقته، وتلميذ دخل المسجد فوجد الإمام في الركعة الثالثة. ما حكم كل واحد؟</p>\n<p><strong>أولا: سجود السهو</strong></p>\n<blockquote><p><strong>سجود السهو</strong>: سجدتان يُجبر بهما الخلل الواقع في الصلاة سهوا بنقص سنة أو زيادة فعل غير مبطل.</p></blockquote>\n<p><strong>حكمه</strong>: سنة عند المالكية، ومحلّه يختلف بحسب سبب السهو:</p>\n<table><thead><tr><th>حالة السهو</th><th>محلّ السجود</th><th>التوضيح</th></tr></thead><tbody><tr><td>نقص سنة (كترك التشهد أو السورة)</td><td><strong>قبل السلام</strong></td><td>سجدتان قبل السلام، ثم يتشهد ويسلّم</td></tr><tr><td>زيادة فعل غير مبطل (كزيادة سجدة أو قيام)</td><td><strong>بعد السلام</strong></td><td>يسلّم ثم يسجد سجدتين ثم يتشهد ويسلّم</td></tr><tr><td>نقص وزيادة معا</td><td><strong>قبل السلام</strong></td><td>يُغلَّب حكم النقص</td></tr></tbody></table>\n<p><strong>قواعد مهمة</strong>:</p>\n<ol><li>ما نُقص من <strong>الفرائض</strong> لا يُجبر بسجود السهو، بل يُتمّ الفريضة إن أمكن أو تُعاد الصلاة.</li><li>من ترك سجود السهو الذي محلّه قبل السلام فتفصيل حكمه عند أهل المذهب بحسب ما تُرك من السنن، قلّة وكثرة؛ وهذا مما يُرجع فيه إلى أهل العلم والمصادر المالكية المعتمدة.</li><li>من شكّ هل صلّى ثلاثا أم أربعا بنى على الأقل (اليقين) وأتمّ، ثم سجد للسهو بعد السلام لاحتمال الزيادة.</li><li>المأموم لا يسجد للسهو إذا سها وحده تبعا لإمامه؛ وإذا سها الإمام سجد المأموم معه.</li></ol>\n<p><strong>نص أساس</strong>: قال النبي صلى الله عليه وسلم: «إذا شكّ أحدكم في صلاته فلم يدرِ كم صلّى، ثلاثا أم أربعا، فليطرح الشك وليبنِ على ما استيقن، ثم يسجد سجدتين قبل أن يسلّم» (أخرجه مسلم، كتاب المساجد ومواضع الصلاة، حديث رقم 571).</p>\n<p><strong>ثانيا: قضاء الفوائت</strong></p>\n<blockquote><p><strong>الفائتة</strong>: الصلاة التي خرج وقتها ولم تُؤدَّ.</p></blockquote>\n<p><strong>الأحكام</strong>:</p>\n<ol><li><strong>وجوب القضاء</strong>: قال النبي صلى الله عليه وسلم: «من نسي صلاة فليصلّها إذا ذكرها، لا كفارة لها إلا ذلك» (أخرجه البخاري، كتاب مواقيت الصلاة، حديث رقم 597، ومسلم، حديث رقم 684).</li><li><strong>الفور</strong>: تُقضى عند الذكر أو الاستيقاظ من غير تأخير.</li><li><strong>الترتيب</strong>: تُقضى مرتبة كما فُرضت؛ فمن فاتته الظهر والعصر قضى الظهر ثم العصر.</li><li><strong>الترتيب مع الحاضرة</strong>: من كان عليه فوائت يسيرة قدّم قضاءها على الحاضرة إن لم يخف خروج وقت الحاضرة، وتفصيل عدد اليسير والكثير عند المالكية يُرجع فيه إلى المصادر المعتمدة.</li><li><strong>صفة القضاء</strong>: تُقضى الفائتة على صفتها من جهر أو سرّ بحسب أصلها.</li><li><strong>الفرق بين النسيان والترك العمد</strong>: النسيان والنوم معذور فيهما، والترك العمد إثم عظيم يوجب التوبة مع القضاء.</li></ol>\n<p><strong>ثالثا: أحكام المسبوق</strong></p>\n<blockquote><p><strong>المسبوق</strong>: من فاته بعض الصلاة مع الإمام فأدرك بعضها.</p></blockquote>\n<p><strong>الأحكام</strong>:</p>\n<ol><li><strong>البناء لا الاستئناف</strong>: قال النبي صلى الله عليه وسلم: «إذا سمعتم الإقامة فامشوا إلى الصلاة وعليكم السكينة والوقار ولا تُسرعوا، فما أدركتم فصلّوا، وما فاتكم فأتموا» (أخرجه البخاري، كتاب الجمعة، حديث رقم 908، ومسلم، حديث رقم 602، وأصله في البخاري حديث رقم 636).</li><li><strong>متى تُحسب الركعة؟</strong> يُدرك المسبوق الركعة بإدراك الركوع مع الإمام قبل رفعه منه.</li><li><strong>الدخول مع الإمام على أي حال</strong>: يكبّر تكبيرة الإحرام قائما ثم يتابع الإمام فيما هو فيه.</li><li><strong>قضاء ما فاته</strong>: بعد سلام الإمام يُتمّ ما بقي عليه، فما أدركه مع الإمام هو آخر صلاته في الفعل وأولها في الحكم على المشهور عند المالكية: فيُقضى القول والفعل على وجهه؛ وهذه من مواضع التفصيل التي تُراجع في كتب المذهب.</li><li><strong>الطمأنينة والسكينة</strong>: لا يجوز الإسراع المفرط والجري إلى الصف.</li></ol>\n<p><strong>مقاصد هذه الأحكام</strong>:</p>\n<ul><li><strong>التخفيف ورفع الحرج</strong>: فالسهو من طبيعة الإنسان، فجُعل له جابر.</li><li><strong>العناية بالصلاة</strong>: القضاء الفوري يبيّن أن الصلاة دين لا يسقط.</li><li><strong>صيانة الجماعة</strong>: أحكام المسبوق تشجع على اللحاق بالجماعة ولو متأخرا.</li><li><strong>التربية على الدقة والمسؤولية</strong>: تنبيه على تنظيم الوقت والنوم لتجنب الفوائت.</li></ul>\n<p><strong>السياق المغربي</strong>: تُعلّم هذه الأحكام في المغرب على المذهب المالكي، ويُرجع في نوازلها إلى المجالس العلمية المحلية والمجلس العلمي الأعلى بإشراف إمارة المؤمنين، وإلى المصادر المالكية المعتمدة كمتون المذهب وشروحها. ومن الآداب المتبعة في المساجد المغربية عدم الإسراع إلى الصف والالتزام بالسكينة، وإتمام المسبوق صلاته بعد سلام الإمام في هدوء.</p>\n<p><strong>مثال محلول 1</strong>: نسي مصلٍّ التشهد الأول وقام إلى الثالثة. الجواب: التشهد سنة، فيستمر ولا يعود، ويسجد للسهو سجدتين <strong>قبل السلام</strong> لأنه نقص.</p>\n<p><strong>مثال محلول 2</strong>: زاد مصلٍّ سجدة خامسة سهوا. الجواب: زيادة فعل غير مبطل، فيسجد للسهو <strong>بعد السلام</strong>.</p>\n<p><strong>مثال محلول 3</strong>: دخل تلميذ المسجد فأدرك الإمام في الركعة الثالثة من العشاء. الجواب: يكبّر ويدخل، فيصلّي معه ركعتين، ثم بعد سلام الإمام يقوم فيُتمّ ركعتين، وقد أدرك الجماعة؛ وينبغي أن يدخل بسكينة لا مسرعا.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>سجود السهو</td><td>سجدتان يُجبر بهما خلل النقص أو الزيادة سهوا</td></tr><tr><td>النقص</td><td>ترك سنة من سنن الصلاة سهوا</td></tr><tr><td>الزيادة</td><td>فعل زائد غير مبطل كزيادة سجدة أو قيام</td></tr><tr><td>الفائتة</td><td>صلاة خرج وقتها ولم تُؤدَّ</td></tr><tr><td>الترتيب</td><td>قضاء الفوائت على نظم فرضها</td></tr><tr><td>المسبوق</td><td>من أدرك بعض الصلاة مع الإمام وفاته بعضها</td></tr><tr><td>البناء</td><td>إتمام ما بقي بعد سلام الإمام</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الظن أن سجود السهو يجبر ترك الفرائض؛ والصواب أنه يجبر السنن والزيادة غير المبطلة.</li><li>⚠️ الخلط في محلّ السجود؛ والضابط: النقص قبل السلام، والزيادة بعده، وعند اجتماعهما يُغلَّب النقص فيكون قبل السلام.</li><li>⚠️ تأخير قضاء الفوائت بلا عذر؛ والصواب المبادرة عند الذكر لحديث «فليصلّها إذا ذكرها».</li><li>⚠️ الإسراع والجري للحاق بالصف؛ والصواب السكينة والوقار: «فما أدركتم فصلّوا وما فاتكم فأتموا».</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف سجود السهو، وبيّن حكمه عند المالكية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>ما محلّ سجود السهو في النقص؟ وما محله في الزيادة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>عرّف الفائتة، واذكر حكم قضائها بالدليل مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>عرّف المسبوق، وبيّن بم يُدرك الركعة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>أتمم الحديث: «فما أدركتم فصلّوا ...» مع العزو.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>أنجز جدولا (حالة السهو / محلّ السجود / التعليل) لثلاث حالات.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ما حكم من شكّ هل صلّى ثلاثا أم أربعا؟ وما دليله؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>ما الفرق بين من فاتته الصلاة بنوم أو نسيان ومن تركها عمدا؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>اذكر أربعة من مقاصد أحكام السهو والقضاء.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>ما حكم الإسراع إلى الصف؟ ولماذا؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>حلّ الحالات الآتية مع التعليل: نسي التشهد الأول / زاد قياما بعد الرابعة سهوا / نسي الفاتحة في ركعة / أدرك الإمام في السجود من الركعة الثانية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>وضعية: تلميذ يفوّت صلاة الصبح كثيرا بسبب السهر على الهاتف. حرّر عشرة أسطر تبيّن الحكم وتقترح خطة عملية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>حلّل: كيف تربّي أحكام السهو والقضاء على المسؤولية ورفع الحرج في وقت واحد؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن أهمية الرجوع إلى أهل العلم والمصادر المالكية المعتمدة في تفاصيل النوازل الفقهية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"سجود السهو","v":"سجدتان يُجبر بهما خلل النقص أو الزيادة سهوا"},{"r":"النقص","v":"ترك سنة من سنن الصلاة سهوا"},{"r":"الزيادة","v":"فعل زائد غير مبطل كزيادة سجدة أو قيام"},{"r":"الفائتة","v":"صلاة خرج وقتها ولم تُؤدَّ"},{"r":"الترتيب","v":"قضاء الفوائت على نظم فرضها"},{"r":"المسبوق","v":"من أدرك بعض الصلاة مع الإمام وفاته بعضها"},{"r":"البناء","v":"إتمام ما بقي بعد سلام الإمام"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — عرّف سجود السهو، وبيّن محلّه في النقص والزيادة وعند اجتماعهما مع التعليل.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — عرّف الفائتة والمسبوق، واستشهد لكل واحد بحديث مع العزو الكامل.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — حلّ أربع نوازل (تُعطى في ورقة الفرض) في السهو والقضاء وأحكام المسبوق مع التعليل، ثم بيّن في أربعة أسطر لماذا تُرجع الدقائق إلى أهل العلم.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 2 ن، المحلّان والاجتماع 4 ن.</li><li>التمرين الثاني: التعريفان 2 ن، الحديثان مع العزو 4 ن.</li><li>التمرين الثالث: كل نازلة 1,5 ن، والتعليل الختامي 2 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei24","domaine":"islamique","unite":24,"theme":"الوحدة الرابعة — الدروس EI20 إلى EI26","tag":"EI24","langue":"ar","titre":"مدخل القسط 4: حق البيئة (حماية البيئة من التلوث المادي والمعنوي)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يعرّف المتعلم(ة) البيئة والتلوث ويميّز بين المادي والمعنوي.","أن يستدل على حق البيئة بنصوص شرعية مع العزو.","أن يعدّد مظاهر الإفساد البيئي وآثاره.","أن يبيّن مسؤولية الإنسان كخليفة ومستعمر في الأرض.","أن ينجز مشروعا بيئيا صفّيا مرتبطا بمحيطه بالمغرب."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: في ساحة المؤسسة أوراق ملقاة، وحنفية تسيل، وجدار مكتوب عليه بألفاظ جارحة. أي هذه المظاهر تلوث مادي؟ وأيها تلوث معنوي؟ وما واجبك؟</p>\n<p><strong>التعريفات</strong>:</p>\n<blockquote><p><strong>البيئة</strong>: المحيط الذي يعيش فيه الإنسان بما فيه من ماء وهواء وتراب وكائنات حية وموارد ومرافق.</p></blockquote>\n<blockquote><p><strong>التلوث المادي</strong>: إفساد عناصر البيئة المحسوسة: تلويث الماء والهواء والتراب، والنفايات، والضجيج، والإتلاف.</p></blockquote>\n<blockquote><p><strong>التلوث المعنوي</strong>: إفساد البيئة الأخلاقية والاجتماعية: الألفاظ النابية، والمنشورات الضارة، والمشاهد المخلّة، وترويج العنف والكراهية، والتشهير.</p></blockquote>\n<p><strong>الأصول الشرعية لحق البيئة</strong>:</p>\n<ol><li><strong>الاستخلاف والاستعمار في الأرض</strong>: «هُوَ أَنْشَأَكُمْ مِنَ الْأَرْضِ وَاسْتَعْمَرَكُمْ فِيهَا» (سورة هود، الآية 61)؛ فالأرض أمانة يُعمرها الإنسان لا يخرّبها.</li><li><strong>النهي عن الإفساد</strong>: «وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا» (سورة الأعراف، الآية 56)، و«ظَهَرَ الْفَسَادُ فِي الْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتْ أَيْدِي النَّاسِ» (سورة الروم، الآية 41).</li><li><strong>النهي عن الإسراف</strong>: «وَلَا تُسْرِفُوا ۚ إِنَّهُ لَا يُحِبُّ الْمُسْرِفِينَ» (سورة الأعراف، الآية 31).</li><li><strong>الأمر بالنظافة</strong>: قال النبي صلى الله عليه وسلم: «إن الله طيّب يحب الطيب، نظيف يحب النظافة» (أخرجه الترمذي، كتاب الأدب، حديث رقم 2799، وحسّنه بعض أهل العلم؛ وفي معناه أحاديث أخرى في الحث على النظافة).</li><li><strong>حرمة إيذاء الناس في طرقهم ومواردهم</strong>: «اتقوا الملاعن الثلاث: البراز في الموارد وقارعة الطريق والظلّ» (أخرجه أبو داود، كتاب الطهارة، حديث رقم 26، وحسّنه بعض أهل العلم).</li><li><strong>إزالة الأذى من الطريق شعبة من الإيمان</strong>: «الإيمان بضع وسبعون شعبة... وأدناها إماطة الأذى عن الطريق» (أخرجه مسلم، كتاب الإيمان، حديث رقم 35، بمعناه).</li><li><strong>الحث على الغرس والإعمار</strong>: «من غرس غرسا فما أكل منه الآدمي أو أكلت الطير فهو له صدقة» (أخرجه مسلم، كتاب المساقاة، حديث رقم 1552، بمعناه).</li><li><strong>الرفق بالحيوان</strong>: «في كل ذات كبد رطبة أجر» في معنى ما ورد في قصة الرجل الذي سقى الكلب (أخرجه البخاري، كتاب المساقاة، حديث رقم 2363).</li></ol>\n<p><strong>مظاهر الإفساد البيئي وآثاره</strong>:</p>\n<table><thead><tr><th>المظهر</th><th>مثاله</th><th>أثره</th></tr></thead><tbody><tr><td>تلويث الماء</td><td>صبّ النفايات في الوديان</td><td>أمراض، ونقص الماء الصالح</td></tr><tr><td>تلويث الهواء</td><td>الأدخنة وحرق النفايات</td><td>أمراض تنفسية، وتغير مناخي</td></tr><tr><td>النفايات والأزبال</td><td>إلقاؤها في الأزقة والشواطئ</td><td>تشويه المنظر، وانتشار الحشرات</td></tr><tr><td>هدر الماء والطاقة</td><td>حنفية مفتوحة، إضاءة نهارا</td><td>إجهاد الموارد وارتفاع التكلفة</td></tr><tr><td>إتلاف المرافق</td><td>تحطيم كرسي، تشويه جدار</td><td>خسارة مال عام، وتربية على اللامسؤولية</td></tr><tr><td>قطع الأشجار</td><td>القطع الجائر</td><td>تصحّر وانجراف التربة</td></tr><tr><td>التلوث المعنوي</td><td>ألفاظ نابية، محتوى مؤذٍ</td><td>تسميم العلاقات وإفساد القيم</td></tr><tr><td>الضجيج</td><td>أبواق ومكبرات بلا حاجة</td><td>إجهاد نفسي وسمعي</td></tr></tbody></table>\n<p><strong>مسؤولية المسلم تجاه البيئة</strong>: النظافة الشخصية والمكانية، وترشيد الماء والكهرباء، وفرز النفايات، والمشاركة في حملات النظافة والتشجير، والحفاظ على المرافق العمومية، وترك الضجيج، وطهارة اللسان والمحتوى الذي ينشره، والنصح بالحسنى، واحترام القوانين المنظّمة.</p>\n<p><strong>السياق المغربي</strong>: يواجه المغرب إجهادا مائيا وتحديات مناخية، ولذلك أُطلقت سياسات وطنية للاقتصاد الأخضر وترشيد الماء والطاقات المتجددة، كما تنظّم المؤسسات التعليمية أندية بيئية وحملات نظافة وتشجير. ومن الجانب الديني تُخصّص خطب ودروس في المساجد للتحسيس بترشيد الماء وحرمة الإفساد، وهذا من قيم المواطنة المسؤولة. ومن العادات الحسنة في المغرب العناية بالسقايات العمومية والعيون والأحباس المخصصة للماء، وهي تعبير قديم عن الوعي بحق البيئة والمرفق العام.</p>\n<p><strong>مثال محلول 1</strong>: تلميذ يقول: «ورقة واحدة لا تُغيّر شيئا». الجواب: مجموع الأوراق هو ما يُشوّه الفضاء؛ والقاعدة الشرعية أن كل واحد مسؤول عن فعله، فلو قال كل تلميذ ذلك لتحول الفضاء إلى مزبلة.</p>\n<p><strong>مثال محلول 2</strong>: كتابة ألفاظ جارحة على جدار. الجواب: هذا اعتداء مزدوج: على المرفق العام (تلوث مادي)، وعلى كرامة الناس (تلوث معنوي)، والواجب المسح والاعتذار والامتناع.</p>\n<p><strong>مثال محلول 3</strong>: ترشيد الماء في الوضوء. الجواب: من السنة الاقتصاد في الماء حتى في العبادة، والإسراف منهي عنه: «وَلَا تُسْرِفُوا»؛ وفي بلد يعاني إجهادا مائيا يتضاعف الواجب.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<table><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td>البيئة</td><td>المحيط الذي يعيش فيه الإنسان بموارده وكائناته ومرافقه</td></tr><tr><td>الاستعمار في الأرض</td><td>تكليف الإنسان بإعمارها وإصلاحها</td></tr><tr><td>التلوث المادي</td><td>إفساد عناصر البيئة المحسوسة</td></tr><tr><td>التلوث المعنوي</td><td>إفساد البيئة الأخلاقية والاجتماعية</td></tr><tr><td>الإسراف</td><td>تجاوز الحد في الاستعمال والاستهلاك</td></tr><tr><td>إماطة الأذى</td><td>إزالة ما يؤذي الناس من الطريق</td></tr><tr><td>الإجهاد المائي</td><td>نقص الموارد المائية عن حاجة السكان</td></tr><tr><td>المرفق العمومي</td><td>ما هُيّئ لخدمة الناس جميعا</td></tr></tbody></table>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ حصر البيئة في النظافة المادية؛ والصواب أنها تشمل البيئة الأخلاقية والاجتماعية.</li><li>⚠️ الاعتقاد أن الفعل الفردي لا أثر له؛ والصواب أن المجموع من الأفراد.</li><li>⚠️ الإسراف في الماء حتى في العبادة؛ والصواب أن الاقتصاد مطلوب حتى في الوضوء.</li><li>⚠️ اعتبار المرفق العمومي بلا صاحب؛ والصواب أنه ملك للجميع، والاعتداء عليه اعتداء على حق عام.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>عرّف البيئة، وميّز بين التلوث المادي والمعنوي بمثالين لكل نوع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اذكر آيتين في النهي عن الإفساد والإسراف مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر حديثين في النظافة وإماطة الأذى مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر ستا من مظاهر الإفساد البيئي.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>ما معنى «وَاسْتَعْمَرَكُمْ فِيهَا»؟</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>أنجز جدولا (المظهر / مثاله / أثره) لأربعة مظاهر.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>بيّن كيف يكون هدر الماء إفسادا في الأرض مع الربط بالوضع المائي بالمغرب.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>ناقش: «ورقة واحدة لا تُغيّر شيئا».</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>اذكر ستا من مسؤوليات المسلم تجاه البيئة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>كيف يكون التلوث المعنوي أخطر من المادي في بعض الحالات؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: يشوّه بعض التلاميذ جدران المؤسسة ويتلفون المرافق. حرّر عشرة أسطر تبيّن الحكم الشرعي والقانوني وتقترح مبادرة إصلاحية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: علاقة قيمة القسط بحق البيئة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز مشروعا بيئيا صفّيا (الهدف / الأنشطة / الشراكات / المؤشرات / مدة التنفيذ).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن مظاهر الوعي البيئي في التقاليد المغربية والسياسات الوطنية الحديثة.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"البيئة","v":"المحيط الذي يعيش فيه الإنسان بموارده وكائناته ومرافقه"},{"r":"الاستعمار في الأرض","v":"تكليف الإنسان بإعمارها وإصلاحها"},{"r":"التلوث المادي","v":"إفساد عناصر البيئة المحسوسة"},{"r":"التلوث المعنوي","v":"إفساد البيئة الأخلاقية والاجتماعية"},{"r":"الإسراف","v":"تجاوز الحد في الاستعمال والاستهلاك"},{"r":"إماطة الأذى","v":"إزالة ما يؤذي الناس من الطريق"},{"r":"الإجهاد المائي","v":"نقص الموارد المائية عن حاجة السكان"},{"r":"المرفق العمومي","v":"ما هُيّئ لخدمة الناس جميعا"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — عرّف البيئة، وميّز بين التلوث المادي والمعنوي بأربعة أمثلة، واستشهد بنص مع العزو.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — اذكر ستا من مسؤوليات المسلم تجاه البيئة، وبيّن أثر اثنتين منها في محيط مؤسستك.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: تعاني مؤسستك من النفايات وهدر الماء وتشويه الجدران. حرّر اثني عشر سطرا تبيّن الحكم الشرعي، وتقترح مشروعا بيئيا بمؤشرات قياس وشراكات.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: التعريف 1,5 ن، الأمثلة 3 ن، النص مع العزو 1,5 ن.</li><li>التمرين الثاني: المسؤوليات 4 ن، بيان الأثر 2 ن.</li><li>التمرين الثالث: الحكم الشرعي بالاستدلال 3 ن، المشروع 3 ن، المؤشرات والشراكات 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei25","domaine":"islamique","unite":25,"theme":"الوحدة الرابعة — الدروس EI20 إلى EI26","tag":"EI25","langue":"ar","titre":"مدخل الحكمة 4: حديث (الفقيه كل الفقيه)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يقرأ المتعلم(ة) نص الأثر قراءة سليمة ويشرح مفرداته.","أن يعرف درجة النص ومصدره بأمانة علمية.","أن يستخرج صفات الفقيه الحقّ من النص.","أن يميّز بين الفقه المحمود والغلوّ والتسيّب.","أن يستثمر معاني النص في التعامل مع نفسه ومع الناس وفي أخذ العلم من أهله."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: سُئل تلميذان عن حكم شرعي، فأجاب الأول: «كل من فعل هذا آثم وسيدخل النار»، وأجاب الثاني: «الأمر واسع، افعل ما شئت». فأيهما أصاب؟ ولنقرأ نصا يرسم صفة الفقيه الحقّ.</p>\n<p><strong>نص الدرس</strong>:</p>\n<blockquote><p>عن علي بن أبي طالب رضي الله عنه قال: «الفقيه كلّ الفقيه: الذي لا يُقنّط الناس من رحمة الله، ولا يُرخّص لهم في معاصي الله، ولا يدع القرآن رغبة عنه إلى غيره» (أثر عن علي رضي الله عنه، أخرجه الدارمي في سننه في المقدمة، حديث رقم 305 في بعض الطبعات، وذكره ابن عبد البر في جامع بيان العلم وفضله).</p></blockquote>\n<p><strong>تنبيه علمي مهم</strong>: هذا النص <strong>أثر موقوف على علي بن أبي طالب رضي الله عنه</strong>، وليس حديثا مرفوعا إلى النبي صلى الله عليه وسلم، وقد ورد في بعض الكتب المدرسية والدروس بعنوان «حديث» تجاوزا في التسمية. والأمانة العلمية تقتضي بيان أنه أثر عن الصحابي، وأن أرقام الأحاديث في سنن الدارمي تختلف بحسب الطبعة. ومعناه صحيح ومقرَّر بأصول الشرع.</p>\n<p><strong>شرح المفردات</strong>:</p>\n<table><thead><tr><th>الكلمة</th><th>الشرح</th></tr></thead><tbody><tr><td>الفقيه</td><td>العالم بأحكام الشرع الفاهم لمقاصده</td></tr><tr><td>كلّ الفقيه</td><td>الفقيه الكامل التام في فقهه</td></tr><tr><td>لا يُقنّط</td><td>لا يُوقع الناس في اليأس والقنوط من رحمة الله</td></tr><tr><td>لا يُرخّص</td><td>لا يُهوّن المعصية ولا يفتح بابها بحجة السماحة</td></tr><tr><td>لا يدع القرآن رغبة عنه</td><td>لا يهجره ولا يستبدله بغيره من الكلام</td></tr></tbody></table>\n<p><strong>صفات الفقيه الحقّ في النص</strong>:</p>\n<ol><li><strong>الجمع بين الترغيب والترهيب</strong>: لا يُقنّط ولا يُرخّص، فالتوازن هو الفقه.</li><li><strong>حسن الظن بالله وبأهل الإسلام</strong>: يفتح باب التوبة ولا يحكم على المآلات.</li><li><strong>الأمانة في التبليغ</strong>: لا يحلّل ما حرّم الله ولا يشدّد بما لم يشدّد به.</li><li><strong>التمسك بالقرآن أصلا للمعرفة</strong>: فلا يستبدله بأقوال الناس ولا بمواد الترفيه.</li><li><strong>الرحمة في العلم</strong>: فالعلم بلا رحمة يصير سلاحا على الناس.</li></ol>\n<p><strong>قواعد شرعية تدعم معاني النص</strong>:</p>\n<ul><li>النهي عن القنوط: «قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ» (سورة الزمر، الآية 53).</li><li>النهي عن الأمن من عقوبة الله: «أَفَأَمِنُوا مَكْرَ اللَّهِ ۚ فَلَا يَأْمَنُ مَكْرَ اللَّهِ إِلَّا الْقَوْمُ الْخَاسِرُونَ» (سورة الأعراف، الآية 99).</li><li>الأمر بالتيسير والتبشير: «يسّروا ولا تعسّروا، وبشّروا ولا تنفّروا» (أخرجه البخاري، كتاب العلم، حديث رقم 69 بمعناه، ومسلم، حديث رقم 1732).</li><li>حرمة القول بغير علم: «وَلَا تَقُولُوا لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ هَٰذَا حَلَالٌ وَهَٰذَا حَرَامٌ لِتَفْتَرُوا عَلَى اللَّهِ الْكَذِبَ» (سورة النحل، الآية 116).</li></ul>\n<p><strong>ثلاثة مسالك ومسلك واحد صحيح</strong>:</p>\n<table><thead><tr><th>المسلك</th><th>وصفه</th><th>خطره</th></tr></thead><tbody><tr><td>التقنيط والتشديد</td><td>تخويف بلا رحمة، وتضييق بلا دليل</td><td>تنفير الناس من الدين ودفعهم إلى اليأس</td></tr><tr><td>الترخيص والتسيّب</td><td>تهوين المعاصي بحجة السماحة</td><td>ضياع الأحكام وفتح باب المعصية</td></tr><tr><td><strong>الوسط: الفقه الحقّ</strong></td><td>بيان الحكم بأمانة مع الرحمة وفتح باب التوبة</td><td>هو المطلوب شرعا</td></tr></tbody></table>\n<p><strong>من أخذ العلم؟</strong> يُؤخذ العلم عن أهله المشهود لهم بالعلم والاستقامة، وعن المؤسسات العلمية المعتمدة؛ ولا يُؤخذ من مجهول على الشبكات. وفي المغرب مرجعية علمية منظّمة: المجلس العلمي الأعلى والمجالس العلمية المحلية، ودار الحديث الحسنية، والمؤسسة المحمدية للعلماء، بإشراف إمارة المؤمنين؛ وهي ضمان لوحدة الفتوى ومنع الفوضى في الأحكام.</p>\n<p><strong>مثال محلول 1</strong>: قال تلميذ لزميله الذي قصّر في الصلاة: «أنت من أهل النار». الجواب: هذا تقنيط وحكم على الغيب، والصواب أن يُذكّره ويُرغّبه ويفتح له باب التوبة، فالحكم على المصير لله وحده.</p>\n<p><strong>مثال محلول 2</strong>: قال آخر: «الدين يسر، فلا تشدّد على نفسك في الصلاة». الجواب: هذا ترخيص في معصية باسم اليسر؛ واليسر في الشرع رفع الحرج في الكيفية لا إسقاط الفريضة.</p>\n<p><strong>مثال محلول 3</strong>: من أين تأخذ الحكم إذا أشكل عليك؟ الجواب: من أستاذ المادة، ومن المصادر المعتمدة، ومن المجالس العلمية، لا من مقاطع مجهولة المصدر.</p>\n<p><strong>السياق المغربي وقيم المواطنة</strong>: تنسجم معاني هذا الأثر مع ما يقوم عليه المنهاج من الوسطية والاعتدال، وبتوجيه الاختيار المذهبي المغربي: المذهب المالكي، والعقيدة الأشعرية، والتصوف السنّي، وإمارة المؤمنين (مستجدات منهاج التربية الإسلامية). وأثره في المواطنة: احترام الاختلاف، ورفض الخطاب المتشدد والمنفلت معا، والاحتكام إلى المؤسسات العلمية.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<ul><li>النص أثر موقوف على علي بن أبي طالب رضي الله عنه، أخرجه الدارمي في المقدمة، ويُسمّى في بعض الكتب المدرسية حديثا تجاوزا.</li><li>صفات الفقيه: لا يُقنّط، ولا يُرخّص، ولا يهجر القرآن.</li><li>المسالك ثلاثة: التقنيط، والترخيص، والوسط الحق.</li><li>التيسير المشروع رفع للحرج لا إسقاط للفرائض.</li><li>العلم يُؤخذ عن أهله وعن المؤسسات المعتمدة.</li><li>المرجعية المغربية: المجلس العلمي الأعلى والمجالس المحلية بإشراف إمارة المؤمنين.</li></ul>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ نسبة النص إلى النبي صلى الله عليه وسلم؛ والصواب أنه أثر عن علي رضي الله عنه أخرجه الدارمي.</li><li>⚠️ الحكم على أعيان الناس بالنار أو الجنة؛ والصواب أن المصير إلى الله والوعيد يُذكر عاما.</li><li>⚠️ استعمال «الدين يسر» لإسقاط الواجبات؛ والصواب أن اليسر رفع للحرج لا إبطال للحكم.</li><li>⚠️ أخذ الأحكام من مصادر مجهولة على الشبكات؛ والصواب الرجوع إلى أهل العلم والمؤسسات المعتمدة.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>اكتب نص الأثر كاملا، وبيّن مصدره ودرجته.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اشرح: لا يُقنّط، لا يُرخّص، رغبة عنه.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر صفات الفقيه الثلاث الواردة في النص.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>اذكر آية في النهي عن القنوط وآية في النهي عن الأمن من عقوبة الله مع العزو.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>أتمم الحديث: «يسّروا ولا تعسّروا ...» مع العزو.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>أنجز جدولا للمسالك الثلاثة (المسلك / وصفه / خطره).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ما الفرق بين التيسير المشروع والترخيص المذموم؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>لماذا كان من صفة الفقيه ألا يهجر القرآن؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>عن من يُؤخذ العلم؟ واذكر ثلاث مؤسسات علمية بالمغرب.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>ما حكم الحكم على أعيان الناس بالجنة أو النار؟ ولماذا؟</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: زميلك يقول لمن قصّر في الصلاة: «أنت من أهل النار». حرّر عشرة أسطر تصحح خطابه بالاستدلال.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>وضعية أخرى: زميل يقول: «الدين يسر فلا تشدّد على نفسك في الصلاة». حرّر ثمانية أسطر تصحح المفهوم.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>حلّل: كيف يكون العلم بلا رحمة سلاحا على الناس؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن دور المرجعية العلمية المؤسسية بالمغرب في حماية الاعتدال ووحدة الفتوى.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"الفقيه","v":"العالم بأحكام الشرع الفاهم لمقاصده"},{"r":"كلّ الفقيه","v":"الفقيه الكامل التام في فقهه"},{"r":"لا يُقنّط","v":"لا يُوقع الناس في اليأس والقنوط من رحمة الله"},{"r":"لا يُرخّص","v":"لا يُهوّن المعصية ولا يفتح بابها بحجة السماحة"},{"r":"لا يدع القرآن رغبة عنه","v":"لا يهجره ولا يستبدله بغيره من الكلام"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (6 نقط)</strong> — اكتب نص الأثر، وبيّن مصدره ودرجته، واشرح: لا يُقنّط، لا يُرخّص.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — أنجز جدول المسالك الثلاثة (المسلك / وصفه / خطره)، واستشهد لكل من التقنيط والترخيص بنص مع العزو.</p>\n<p><strong>التمرين الثالث (8 نقط)</strong> — وضعية: تنشر في مجموعة القسم مقاطع تحكم على الناس بالنار، وأخرى تُهوّن ترك الصلاة. حرّر اثني عشر سطرا تصحح الخطابين، وتبيّن مصادر أخذ العلم الموثوقة بالمغرب.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: النص 2 ن، المصدر والدرجة 2 ن، الشرح 2 ن.</li><li>التمرين الثاني: الجدول 4 ن، النصان مع العزو 2 ن.</li><li>التمرين الثالث: تصحيح الخطاب المقنّط 3 ن، تصحيح الخطاب المرخّص 3 ن، المصادر الموثوقة 1,5 ن، اللغة 0,5 ن.</li></ul>\n<hr>"}},
{"id":"islamique-ei26","domaine":"islamique","unite":26,"theme":"الوحدة الرابعة — الدروس EI20 إلى EI26","tag":"EI26","langue":"ar","titre":"مدخل التزكية (القرآن الكريم) 6: الشطر الثالث من سورة لقمان (الآية 22 إلى 34)","duree":"2 س","niveau":"1re année collège · Maroc","objectifs":["أن يرتّل المتعلم(ة) الآيات 22-34 من سورة لقمان ترتيلا سليما ويحفظ ما تيسّر منها.","أن يشرح مفردات المقطع.","أن يستخرج مضامينه: الاستمساك بالعروة الوثقى، وسعة علم الله، ومفاتح الغيب.","أن يستنتج علاقة خواتيم السورة بمقدمتها.","أن يستثمر المقطع في تربية اليقين والاستعداد للآخرة."],"cours":[{"t":"htmlcard","titre":"📘 Cours","x":"<p><strong>وضعية الانطلاق</strong>: يسأل تلميذ: «هل يمكن أن يعلم أحد ما سيحدث لي غدا؟» وخواتيم سورة لقمان تجيب بجواب قاطع: مفاتح الغيب عند الله وحده.</p>\n<p><strong>نص المقطع (22-34)</strong>:</p>\n<blockquote><p>«وَمَنْ يُسْلِمْ وَجْهَهُ إِلَى اللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ ۗ وَإِلَى اللَّهِ عَاقِبَةُ الْأُمُورِ (22) وَمَنْ كَفَرَ فَلَا يَحْزُنْكَ كُفْرُهُ ۚ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُمْ بِمَا عَمِلُوا ۚ إِنَّ اللَّهَ عَلِيمٌ بِذَاتِ الصُّدُورِ (23) نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ (24) وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ ۚ قُلِ الْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ (25) لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۚ إِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ (26) وَلَوْ أَنَّمَا فِي الْأَرْضِ مِنْ شَجَرَةٍ أَقْلَامٌ وَالْبَحْرُ يَمُدُّهُ مِنْ بَعْدِهِ سَبْعَةُ أَبْحُرٍ مَا نَفِدَتْ كَلِمَاتُ اللَّهِ ۗ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ (27) مَا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَاحِدَةٍ ۗ إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ (28) أَلَمْ تَرَ أَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي إِلَىٰ أَجَلٍ مُسَمًّى وَأَنَّ اللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ (29) ذَٰلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ الْبَاطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِيُّ الْكَبِيرُ (30) أَلَمْ تَرَ أَنَّ الْفُلْكَ تَجْرِي فِي الْبَحْرِ بِنِعْمَتِ اللَّهِ لِيُرِيَكُمْ مِنْ آيَاتِهِ ۚ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ (31) وَإِذَا غَشِيَهُمْ مَوْجٌ كَالظُّلَلِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ فَمِنْهُمْ مُقْتَصِدٌ ۚ وَمَا يَجْحَدُ بِآيَاتِنَا إِلَّا كُلُّ خَتَّارٍ كَفُورٍ (32) يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا لَا يَجْزِي وَالِدٌ عَنْ وَلَدِهِ وَلَا مَوْلُودٌ هُوَ جَازٍ عَنْ وَالِدِهِ شَيْئًا ۚ إِنَّ وَعْدَ اللَّهِ حَقٌّ ۖ فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا وَلَا يَغُرَّنَّكُمْ بِاللَّهِ الْغَرُورُ (33) إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ ۖ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا ۖ وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ ۚ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ (34)» — سورة لقمان، الآيات 22-34.</p></blockquote>\n<p><strong>شرح المفردات</strong>:</p>\n<table><thead><tr><th>الكلمة</th><th>الشرح</th></tr></thead><tbody><tr><td>يُسلم وجهه</td><td>ينقاد لله بكليته إخلاصا وعملا</td></tr><tr><td>العروة الوثقى</td><td>العهد المحكم الذي لا ينقطع، وهو الإسلام</td></tr><tr><td>عاقبة الأمور</td><td>مآلها ونهايتها</td></tr><tr><td>عليم بذات الصدور</td><td>عالم بما تُخفيه القلوب</td></tr><tr><td>نضطرهم</td><td>نُلجئهم ونسوقهم قهرا</td></tr><tr><td>عذاب غليظ</td><td>شديد ثقيل</td></tr><tr><td>ما نفدت</td><td>ما انتهت ولا فرغت</td></tr><tr><td>كلمات الله</td><td>علمه وحكمه وما تكلم به سبحانه</td></tr><tr><td>يُولج</td><td>يُدخل بعضه في بعض</td></tr><tr><td>أجل مسمى</td><td>وقت محدد معلوم</td></tr><tr><td>الفلك</td><td>السفن</td></tr><tr><td>صبّار شكور</td><td>كثير الصبر كثير الشكر</td></tr><tr><td>موج كالظلل</td><td>أمواج عالية كالجبال والسحاب</td></tr><tr><td>مقتصد</td><td>متوسط في وفائه، أو ثابت على الحق بحسب المعنى</td></tr><tr><td>ختّار</td><td>غادر شديد الخيانة</td></tr><tr><td>لا يجزي والد عن ولده</td><td>لا يقضي عنه شيئا ولا يُغني عنه</td></tr><tr><td>الغرور</td><td>كل ما يخدع ويوهم، ومنه الشيطان</td></tr><tr><td>مفاتح الغيب</td><td>ما لا يعلمه إلا الله من الغيب</td></tr></tbody></table>\n<p><strong>المضامين الأساسية</strong>:</p>\n<ol><li><strong>العروة الوثقى</strong> لمن أسلم وجهه لله وهو محسن؛ فالإسلام الحقيقي عقيدة وعمل محسن.</li><li><strong>تسلية النبي صلى الله عليه وسلم</strong> عن كفر المكذبين، فمرجعهم إلى الله العليم بما في الصدور.</li><li><strong>متاع الدنيا قليل</strong>، والعذاب غليظ لمن أعرض.</li><li><strong>إقرار المشركين بالخالق</strong> مع مخالفتهم في العبادة، وهذا تناقض: «لَيَقُولُنَّ اللَّهُ».</li><li><strong>سعة علم الله وكلماته</strong>: لو صارت الأشجار أقلاما والبحار مدادا ما نفدت كلمات الله.</li><li><strong>هوان الخلق والبعث على الله</strong>: «مَا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَاحِدَةٍ».</li><li><strong>أدلة الكون</strong>: إيلاج الليل في النهار، وتسخير الشمس والقمر إلى أجل مسمى، وجري الفلك في البحر.</li><li><strong>حال الإنسان عند الشدة</strong>: يُخلص الدعاء في الموج، فإذا نجا رجع كثير منهم إلى الجحود، وهذا خُلق «ختّار كفور».</li><li><strong>الأمر بالتقوى والخشية من يوم لا ينفع فيه أحد أحدا</strong>، وتحذير من غرور الدنيا.</li><li><strong>مفاتح الغيب</strong>: علم الساعة، وتنزيل الغيث، وما في الأرحام، وما تكسبه النفس غدا، وأرض الموت؛ فهي مما اختصّ الله بعلمه.</li></ol>\n<blockquote><p><strong>علاقة الخواتيم بالمقدمة</strong>: بدأت السورة بأن القرآن هدى ورحمة للمحسنين، وختمت بأن من أسلم وجهه لله وهو محسن استمسك بالعروة الوثقى؛ فتكرر وصف <strong>الإحسان</strong> في الطرفين، وهذا من إحكام النظم القرآني.</p></blockquote>\n<p><strong>تنبيه في فهم مفاتح الغيب</strong>: تنزيل الغيث ومعرفة ما في الأرحام مما يختص الله بعلمه على وجه الإحاطة والقطع؛ وأما ما يقوم به الناس من توقع الأمطار أو الكشف الطبي فهو ظنّ مبني على أسباب ومقدمات، ولا يبلغ العلم القطعي المحيط، ولا يخالف الآية. وهذا من دقيق الفهم الذي ينبغي بيانه للمتعلمين بلا تكلّف.</p>\n<p><strong>مثال محلول 1</strong>: ما الفرق بين إسلام الوجه والإسلام باللسان فقط؟ الجواب: إسلام الوجه انقياد كامل: عقيدة صحيحة وعمل محسن؛ وأما الإسلام باللسان فقط فدعوى تنقصها الاستجابة.</p>\n<p><strong>مثال محلول 2</strong>: كيف نفهم إخلاص المشركين في الدعاء عند الموج؟ الجواب: هو دليل على أن التوحيد أصل مركوز في النفس، تظهره الشدة؛ لكن الثبات عليه في الرخاء هو الامتحان الحقيقي.</p>\n<p><strong>مثال محلول 3</strong>: ما الفائدة العملية من قوله «وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا»؟ الجواب: أن يعمل الإنسان اليوم ولا يسوّف، ويستعد للممات في كل وقت، ويترك التعلق بالتنبؤ والتخريف.</p>\n<p><strong>السياق المغربي</strong>: تُختم سورة لقمان في الدورة الثانية من مقرر المستوى الأولى إعدادي، وتُقرأ برواية ورش عن نافع. ومعاني الآية 34 تُستثمر في مواجهة الخرافات والتنبؤ بالمستقبل التي تنتشر أحيانا في الوسائل الحديثة، وتُعزّز الاختيار العقدي الأشعري القائم على تنزيه الله وإفراده بعلم الغيب، ضمن الثوابت الدينية الوطنية.</p>"},{"t":"htmlcard","titre":"🎯 Points clés","x":"<ul><li>«وَمَنْ يُسْلِمْ وَجْهَهُ إِلَى اللَّهِ وَهُوَ مُحْسِنٌ»: عقيدة وعمل.</li><li>كلمات الله لا تنفد ولو كانت الأشجار أقلاما والبحار مدادا.</li><li>الخلق والبعث سواء في يسرهما على الله.</li><li>أدلة الكون: إيلاج الليل في النهار، تسخير الشمس والقمر، جري الفلك.</li><li>الإخلاص عند الشدة والجحود عند النجاة خُلق مذموم.</li><li>يوم القيامة لا يجزي والد عن ولده ولا مولود عن والده.</li><li>مفاتح الغيب خمسة في الآية 34.</li></ul>"},{"t":"htmlcard","titre":"⚠️ Erreurs fréquentes","x":"<ul><li>⚠️ الظن أن توقع الأمطار أو الكشف الطبي يخالف الآية 34؛ والصواب أن ما يعلمه الناس ظنّ بأسباب لا علم محيط قاطع.</li><li>⚠️ فهم «فَلَا يَحْزُنْكَ كُفْرُهُ» ترك الدعوة؛ والصواب أنها تسلية للنبي لا إسقاط للبلاغ.</li><li>⚠️ الخلط بين «الفلك» بمعنى السفن و«الفلك» بمعنى المدار.</li><li>⚠️ الوقف على «لَيَقُولُنَّ» وقطع «اللَّهُ»، وهو وقف يُفسد المعنى.</li></ul>"}],"exercices":[{"type":"ouverte","badge":1,"diff":"","consigne":"Exercice 1","q":"<p>اكتب الآية 34 من سورة لقمان مع الشكل.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":2,"diff":"","consigne":"Exercice 2","q":"<p>اشرح: العروة الوثقى، نضطرهم، يولج، صبّار شكور، ختّار.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":3,"diff":"","consigne":"Exercice 3","q":"<p>اذكر مفاتح الغيب الخمسة الواردة في الآية 34.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":4,"diff":"","consigne":"Exercice 4","q":"<p>أتمم: «مَا خَلْقُكُمْ وَلَا بَعْثُكُمْ ...» مع رقم الآية.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":5,"diff":"","consigne":"Exercice 5","q":"<p>اذكر ثلاثة أدلة كونية وردت في المقطع.</p>\n<p><strong>المستوى الثاني: التدريب</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":6,"diff":"","consigne":"Exercice 6","q":"<p>بيّن معنى «يُسلم وجهه إلى الله وهو محسن»، وما علاقته بمقدمة السورة؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":7,"diff":"","consigne":"Exercice 7","q":"<p>ما دلالة الآية 27 على سعة علم الله؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":8,"diff":"","consigne":"Exercice 8","q":"<p>كيف تكشف الآية 25 تناقض المشركين؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":9,"diff":"","consigne":"Exercice 9","q":"<p>حلّل حال الإنسان في الآية 32 (الشدة والرخاء).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":10,"diff":"","consigne":"Exercice 10","q":"<p>استخرج من المقطع كلمتين فيهما مد وحدد نوعه.</p>\n<p><strong>المستوى الثالث: التعميق</strong></p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":11,"diff":"","consigne":"Exercice 11","q":"<p>وضعية: يتابع زميل صفحات تتنبأ بالمستقبل وتدّعي معرفة الغيب. حرّر عشرة أسطر تناصحه بالاستدلال بالآية 34، مع بيان الفرق بين العلم بالأسباب والعلم بالغيب.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":12,"diff":"","consigne":"Exercice 12","q":"<p>حلّل: كيف يربّي قوله «لَا يَجْزِي وَالِدٌ عَنْ وَلَدِهِ» على المسؤولية الشخصية؟</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":13,"diff":"","consigne":"Exercice 13","q":"<p>أنجز جدولا (الآية / المضمون / القيمة) لست آيات من المقطع.</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]},{"type":"ouverte","badge":14,"diff":"","consigne":"Exercice 14","q":"<p>اكتب ثمانية أسطر عن العبرة من قوله تعالى «فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا» في حياة المتعلم(ة).</p>","modele":"<em>Corrige avec ton manuel ou ton professeur.</em>","criteres":["Compare ta réponse avec la correction","Rédige sur ton cahier"]}],"flash":[{"r":"يُسلم وجهه","v":"ينقاد لله بكليته إخلاصا وعملا"},{"r":"العروة الوثقى","v":"العهد المحكم الذي لا ينقطع، وهو الإسلام"},{"r":"عاقبة الأمور","v":"مآلها ونهايتها"},{"r":"عليم بذات الصدور","v":"عالم بما تُخفيه القلوب"},{"r":"نضطرهم","v":"نُلجئهم ونسوقهم قهرا"},{"r":"عذاب غليظ","v":"شديد ثقيل"},{"r":"ما نفدت","v":"ما انتهت ولا فرغت"},{"r":"كلمات الله","v":"علمه وحكمه وما تكلم به سبحانه"},{"r":"يُولج","v":"يُدخل بعضه في بعض"},{"r":"أجل مسمى","v":"وقت محدد معلوم"},{"r":"الفلك","v":"السفن"},{"r":"صبّار شكور","v":"كثير الصبر كثير الشكر"},{"r":"موج كالظلل","v":"أمواج عالية كالجبال والسحاب"},{"r":"مقتصد","v":"متوسط في وفائه، أو ثابت على الحق بحسب المعنى"},{"r":"ختّار","v":"غادر شديد الخيانة"},{"r":"لا يجزي والد عن ولده","v":"لا يقضي عنه شيئا ولا يُغني عنه"},{"r":"الغرور","v":"كل ما يخدع ويوهم، ومنه الشيطان"},{"r":"مفاتح الغيب","v":"ما لا يعلمه إلا الله من الغيب"}],"devoir":{"titre":"📝 Devoir","consigne":"<p><strong>التمرين الأول (7 نقط)</strong> — اكتب الآيتين 33 و34 مع الشكل، واشرح: العروة الوثقى، صبّار شكور، الغرور.</p>\n<p><strong>التمرين الثاني (6 نقط)</strong> — استخرج من المقطع ثلاثة مضامين مع استشهاد لكل مضمون وبيان القيمة المستفادة.</p>\n<p><strong>التمرين الثالث (7 نقط)</strong> — وضعية: انتشرت في محيطك ادّعاءات بمعرفة المستقبل والتنبؤ بالغيب. حرّر اثني عشر سطرا تبيّن الحكم بالاستدلال بالآية 34، وتوضح الفرق بين العلم بالأسباب وعلم الغيب، وتقترح بدائل نافعة.</p>","criteres":["Respecte le barème","Montre toutes les étapes","Relis-toi avant de voir la correction"],"modele":"<ul><li>التمرين الأول: الآيتان 4 ن، الشرح 3 ن.</li><li>التمرين الثاني: كل مضمون باستشهاده وقيمته 2 ن.</li><li>التمرين الثالث: بيان الحكم مع الاستشهاد 3 ن، التمييز بين الأسباب والغيب 2,5 ن، البدائل 1 ن، اللغة 0,5 ن.</li></ul>\n<hr>\n<p>## Annexes — الملاحق</p>\n<p>### A. Devoirs de synthèse — الفروض التركيبية</p>\n<p>تتضمن هذه الملحقة أربعة فروض تركيبية: فرضان في الدورة الأولى وفرضان في الدورة الثانية. كل فرض منقط على عشرين نقطة، ويحترم السلم المعتمد في الوثيقة: <strong>الترتيل والحفظ 4 نقط، المضامين والمفاهيم 6 نقط، الاستدلال الشرعي 4 نقط، الوضعية الإدماجية 6 نقط</strong>. مدة الإنجاز ساعة واحدة.</p>"}});
